<script setup lang="ts">
import { ref } from 'vue'

const emit = defineEmits(['login', 'register'])

const isLogin = ref(true)
const email = ref('')
const password = ref('')
const username = ref('')

const submitForm = () => {
  const userData = {
    email: email.value,
    username: username.value
  }
  if (isLogin.value) {
    emit('login', userData)
  } else {
    emit('register', userData)
  }
}
</script>

