    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, player.jumping]);

  // Start game
  const startGame = () => {
    setGameState('playing');
    setScore(0);
    setLevel(1);
    setPlayer({
      x: 50,
      y: 300,
      width: 40,
      height: 60,
      velocityY: 0,
      jumping: false
    });
    setRocks([]);
    setObstacles([]);
    setCollectibles([]);
    generateRocks();
    generateObstacles();
    generateCollectibles();
  };

  // Toggle pause
  const togglePause = () => {
    setGameState(gameState === 'playing' ? 'paused' : 'playing');
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100 p-4">
      <h1 className="text-4xl font-bold text-maroon-800 mb-4">Flying Rock Climber</h1>

      <div className="relative">
        <canvas
          ref={canvasRef}
          className="border-4 border-maroon-800 rounded-lg shadow-lg"
        />

        {gameState === 'ready' && (
