<script setup lang="ts">
import { ref, onMounted } from 'vue'

interface Trade {
  id: number
  strategy: string
  currencyPair: string
  direction: 'BUY' | 'SELL'
  entryPrice: number
  currentPrice: number
  pnl: number
  status: 'open' | 'closed'
}

const trades = ref<Trade[]>([])
const isLoading = ref(true)

// Mock data generation
const generateMockTrades = () => {
  const mockTrades = []
  const strategies = ['EMA Crossover', 'RSI Divergence', 'Bollinger Bands']
  const pairs = ['EUR/USD', 'GBP/USD', 'USD/JPY', 'AUD/USD', 'USD/CAD']

  for (let i = 0; i < 10; i++) {
    const direction = Math.random() > 0.5 ? 'BUY' : 'SELL'
    const entryPrice = Number((Math.random() * 1.5 + 0.5).toFixed(5))
    const currentPrice = Number((entryPrice + (Math.random() * 0.02 - 0.01)).toFixed(5))
    const pnl = Number(((currentPrice - entryPrice) * 10000).toFixed(2))

    mockTrades.push({
      id: i + 1,
      strategy: strategies[Math.floor(Math.random() * strategies.length)],
      currencyPair: pairs[Math.floor(Math.random() * pairs.length)],
      direction,
      entryPrice,
      currentPrice,
      pnl,
      status: Math.random() > 0.7 ? 'closed' : 'open'
    })
  }

  return mockTrades
}

// Simulate real-time updates
onMounted(() => {
  trades.value = generateMockTrades()
  isLoading.value = false

  setInterval(() => {
    trades.value = trades.value.map(trade => {
      if (trade.status === 'open') {
        const newPrice = Number((trade.currentPrice + (Math.random() * 0.002 - 0.001)).toFixed(5))
        return {
          ...trade,
          currentPrice: newPrice,
          pnl: Number(((newPrice - trade.entryPrice) * 10000).toFixed(2))
        }
      }
      return trade
    })
  }, 3000)
})
</script>

