            <th>ID</th>
            <th>Strategy</th>
            <th>Pair</th>
            <th>Direction</th>
            <th>Entry Price</th>
            <th>Current Price</th>
            <th>P/L</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="trade in trades" :key="trade.id" :class="{ closed: trade.status === 'closed' }">
            <td>{{ trade.id }}</td>
            <td>{{ trade.strategy }}</td>
            <td>{{ trade.currencyPair }}</td>
            <td :class="{ buy: trade.direction === 'BUY', sell: trade.direction === 'SELL' }">
              {{ trade.direction }}
