export function useResources() {
  const [resources, setResources] = useState<Resource[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const fetchResources = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 800))
        const mockResources: Resource[] = [
          {
            id: '1',
            name: 'Example Resource',
            description: 'This is an example resource for demonstration purposes.',
            createdAt: new Date().toISOString()
          },
          {
            id: '2',
            name: 'Development Notes',
            description: 'Important notes for the development team.',
            createdAt: new Date(Date.now() - 86400000).toISOString()
          }
        ]
        setResources(mockResources)
      } catch (err) {
        setError('Failed to fetch resources')
      } finally {
        setIsLoading(false)
      }
    }

    fetchResources()
  }, [])

  const addResource = async (data: { name: string; description: string }) => {
    try {
      setIsLoading(true)
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500))
      const newResource: Resource = {
        id: Date.now().toString(),
        name: data.name,
        description: data.description,
        createdAt: new Date().toISOString()
      }
      setResources(prev => [...prev, newResource])
    } catch (err) {
      setError('Failed to add resource')
    } finally {
      setIsLoading(false)
    }
  }

  const updateResource = async (id: string, data: Partial<Resource>) => {
    try {
      setIsLoading(true)
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500))
      setResources(prev =>
        prev.map(resource =>
          resource.id === id ? { ...resource, ...data } : resource
        )
      )
    } catch (err) {
      setError('Failed to update resource')
    } finally {
      setIsLoading(false)
    }
  }

  const deleteResource = async (id: string) => {
    try {
      setIsLoading(true)
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 300))
      setResources(prev => prev.filter(resource => resource.id !== id))
    } catch (err) {
      setError('Failed to delete resource')
    } finally {
      setIsLoading(false)
    }
  }

  return {
    resources,
    isLoading,
    error,
    addResource,
    updateResource,
    deleteResource
  }
}
