  <boltAction type="file" filePath="src/api.ts">
interface Resource {
  id: string;
  title: string;
  description: string;
  createdAt: string;
}

const DB: Resource[] = [];

export const getResources = async (): Promise<Resource[]> => {
  return DB;
};

export const getResource = async (id: string): Promise<Resource | undefined> => {
  return DB.find(resource => resource.id === id);
};

export const createResource = async (data: Omit<Resource, 'id' | 'createdAt'>): Promise<Resource> => {
  const newResource = {
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    ...data
  };
  DB.push(newResource);
  return newResource;
};

export const updateResource = async (id: string, data: Partial<Resource>): Promise<Resource | undefined> => {
  const index = DB.findIndex(resource => resource.id === id);
  if (index === -1) return undefined;

  DB[index] = { ...DB[index], ...data };
  return DB[index];
};

export const deleteResource = async (id: string): Promise<boolean> => {
  const index = DB.findIndex(resource => resource.id === id);
  if (index === -1) return false;

  DB.splice(index, 1);
  return true;
};
