import { ref } from 'vue'
import { useNotification } from '../composables/notifications'

const { addNotification } = useNotification()

const indicators = ref([
  { name: 'pH Level', value: 6.8, min: 6.5, max: 7.5, unit: '' },
  { name: 'Copper Content', value: 0.15, min: 0.1, max: 0.2, unit: '%' },
  { name: 'Tensile Strength', value: 420, min: 400, max: 450, unit: 'MPa' }
])

const formulas = ref([
  { name: 'Standard Coating', components: ['Copper: 85%', 'Zinc: 10%', 'Other: 5%'] },
  { name: 'Anti-Corrosion', components: ['Copper: 70%', 'Zinc: 25%', 'Additives: 5%'] }
])

function checkThresholds() {
  indicators.value.forEach(indicator => {
    if (indicator.value < indicator.min || indicator.value > indicator.max) {
      addNotification({
        type: 'warning',
        message: `${indicator.name} out of range (${indicator.value}${indicator.unit})`
      })
    }
  })
}

// Simulate real-time updates
setInterval(() => {
  indicators.value.forEach(indicator => {
    // Random fluctuation within ±5% of value
    const fluctuation = indicator.value * (0.05 * (Math.random() > 0.5 ? 1 : -1))
    indicator.value = parseFloat((indicator.value + fluctuation).toFixed(2))
  })
  checkThresholds()
}, 5000)
</script>

