const mainLines = ref([
  { id: 1, name: 'Line A', process: 'Drawing', person: 'John Doe', power: 42.5, status: 'running' },
  { id: 2, name: 'Line B', process: 'Coating', person: 'Jane Smith', power: 38.2, status: 'maintenance' },
  { id: 3, name: 'Line C', process: 'Annealing', person: 'Mike Johnson', power: 45.7, status: 'running' }
])

const subLines = ref([
  { id: 1, mainLineId: 1, slot: 'A1', waterSupplement: 75, waterStop: 90, status: 'normal' },
  { id: 2, mainLineId: 1, slot: 'A2', waterSupplement: 85, waterStop: 90, status: 'warning' },
  { id: 3, mainLineId: 2, slot: 'B1', waterSupplement: 65, waterStop: 90, status: 'normal' }
])

function getSubLines(lineId: number) {
  return subLines.value.filter(sub => sub.mainLineId === lineId)
}

// Simulate real-time updates
setInterval(() => {
  mainLines.value.forEach(line => {
    // Random power fluctuation
    line.power = parseFloat((line.power + (Math.random() * 2 - 1)).toFixed(1))
  })

  subLines.value.forEach(sub => {
    // Random water level changes
    sub.waterSupplement = Math.min(
      sub.waterStop - 5,
      Math.max(0, sub.waterSupplement + (Math.random() * 10 - 5))
    )

    // Check thresholds
    if (sub.waterSupplement >= sub.waterStop - 5 && sub.status !== 'warning') {
      sub.status = 'warning'
      addNotification({
        type: 'warning',
        message: `Water supplement threshold reached on slot ${sub.slot}`
      })
    } else if (sub.waterSupplement < sub.waterStop - 5) {
      sub.status = 'normal'
    }
  })
}, 3000)
</script>

