    { id: 3, date: '2023-11-03', hours: 5, description: 'Developed worklog viewer' }
  )
  currentView.value = 'worklogs'
}

const handleExport = () => {
  const csvContent = "data:text/csv;charset=utf-8," + 
    "Date,Hours,Description\n" +
    worklogs.map(log => `${log.date},${log.hours},"${log.description}"`).join("\n")

  const encodedUri = encodeURI(csvContent)
  const link = document.createElement("a")
  link.setAttribute("href", encodedUri)
  link.setAttribute("download", `worklogs_${selectedProject.value?.name || 'project'}.csv`)
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
}

const handleBack = () => {
  currentView.value = 'projects'
}
</script>

