<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps<{
  username: string
}>()

const branches = ref([
  { id: 1, name: 'Main' },
  { id: 2, name: 'Development' },
  { id: 3, name: 'Feature-A' },
  { id: 4, name: 'Feature-B' }
])

const selectedBranch = ref<number | null>(null)
const files = ref<File[]>([])
const updateRecords = ref<Array<{
  id: number
  branch: string
  filename: string
  timestamp: string
  user: string
}>>([])

const handleFileChange = (e: Event) => {
  const target = e.target as HTMLInputElement
  if (target.files) {
    files.value = Array.from(target.files)
  }
}

const handleUpload = () => {
  if (!selectedBranch.value || files.value.length === 0) return

  const branchName = branches.value.find(b => b.id === selectedBranch.value)?.name || 'Unknown'

  files.value.forEach(file => {
    updateRecords.value.push({
      id: Date.now(),
      branch: branchName,
      filename: file.name,
      timestamp: new Date().toLocaleString(),
      user: props.username
    })
  })

  // In a real app, you would upload to server here
  alert(`Files uploaded to ${branchName} branch successfully!`)
  files.value = []
}
</script>

<template>
  <div class="file-manager">
    <div class="branch-selector">
      <h2>Select Branch</h2>
      <select v-model="selectedBranch">
        <option disabled value="">Select a branch</option>
        <option v-for="branch in branches" :key="branch.id" :value="branch.id">
          {{ branch.name }}
        </option>
      </select>
    </div>

    <div class="file-upload">
      <h2>Upload Files</h2>
      <input type="file" multiple @change="handleFileChange" />
      <button @click="handleUpload" :disabled="!selectedBranch || files.length === 0">
        Upload to Branch
      </button>
      <div v-if="files.length > 0">
        <p>Selected files:</p>
        <ul>
          <li v-for="file in files" :key="file.name">{{ file.name }}</li>
        </ul>
      </div>
    </div>

    <div class="update-records">
      <h2>Update Records</h2>
      <table>
        <thead>
          <tr>
            <th>Branch</th>
            <th>Filename</th>
