<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'

interface Task {
  id: number
  execute: () => Promise<void>
}

const props = defineProps({
  maxWorkers: {
    type: Number,
    default: 5
  },
  maxQueueSize: {
    type: Number,
    default: 100
  }
})

const activeWorkers = ref(0)
const taskQueue = ref<Task[]>([])
const completedTasks = ref(0)
const failedTasks = ref(0)
const isRunning = ref(false)
const nextId = ref(1)

const queueLength = computed(() => taskQueue.value.length)
const queuePercentage = computed(() => (queueLength.value / props.maxQueueSize) * 100)
const workerPercentage = computed(() => (activeWorkers.value / props.maxWorkers) * 100)

const addTask = (task: () => Promise<void>) => {
  if (queueLength.value >= props.maxQueueSize) {
    throw new Error('Task queue is full')
  }

  const taskId = nextId.value++
  taskQueue.value.push({ id: taskId, execute: task })
  processQueue()
}

const processQueue = async () => {
  if (!isRunning.value || activeWorkers.value >= props.maxWorkers || queueLength.value === 0) {
    return
  }

  activeWorkers.value++
  const task = taskQueue.value.shift()!

  try {
    await task.execute()
    completedTasks.value++
  } catch (error) {
    console.error('Task failed:', error)
    failedTasks.value++
  } finally {
    activeWorkers.value--
    processQueue()
  }
}

const startPool = () => {
  isRunning.value = true
  processQueue()
}

const stopPool = () => {
  isRunning.value = false
}

const clearQueue = () => {
  taskQueue.value = []
}

defineExpose({
  addTask,
  startPool,
  stopPool,
  clearQueue
})
</script>

<template>
  <div class="pool-container">
    <div class="pool-controls">
      <button @click="startPool" :disabled="isRunning">Start</button>
      <button @click="stopPool" :disabled="!isRunning">Stop</button>
      <button @click="clearQueue">Clear Queue</button>
    </div>

    <div class="pool-stats">
      <div class="stat-item">
        <span>Workers: {{ activeWorkers }}/{{ maxWorkers }}</span>
        <div class="progress-bar">
          <div class="progress-fill" :style="{ width: `${workerPercentage}%`, backgroundColor: 'royalblue' }"></div>
        </div>
      </div>

      <div class="stat-item">
        <span>Queue: {{ queueLength }}/{{ maxQueueSize }}</span>
        <div class="progress-bar">
          <div class="progress-fill" :style="{ width: `${queuePercentage}%`, backgroundColor: 'royalblue' }"></div>
        </div>
      </div>

      <div class="stat-item">
        <span>Completed: {{ completedTasks }}</span>
      </div>
      <div class="stat-item">
        <span>Failed: {{ failedTasks }}</span>
      </div>
    </div>
  </div>
</template>

