<script setup lang="ts">
import { ref } from 'vue'
import FormBuilder from './components/FormBuilder.vue'
import FormPreview from './components/FormPreview.vue'
import AuthManager from './components/AuthManager.vue'

const activeTab = ref('builder')
const forms = ref<Array<{id: string, title: string, fields: any[]}>>([])
const currentForm = ref<any>(null)

const handleFormSave = (form: any) => {
  if (!currentForm.value?.id) {
    form.id = Date.now().toString()
    forms.value.push(form)
  } else {
    const index = forms.value.findIndex(f => f.id === currentForm.value.id)
    if (index !== -1) {
      forms.value[index] = form
    }
  }
  currentForm.value = null
}
</script>

<template>
  <div class="app-container">
    <AuthManager />

    <div class="tabs">
      <button 
        @click="activeTab = 'builder'" 
        :class="{ active: activeTab === 'builder' }"
      >
        Form Builder
      </button>
      <button 
        @click="activeTab = 'preview'" 
        :class="{ active: activeTab === 'preview' }"
      >
        Preview
      </button>
    </div>

    <div v-if="activeTab === 'builder'">
      <FormBuilder 
        :form="currentForm" 
        @save="handleFormSave" 
        @cancel="currentForm = null"
      />
      <div class="form-list">
        <h3>Saved Forms</h3>
        <div 
          v-for="form in forms" 
          :key="form.id" 
          class="form-item"
