<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps({
  form: {
    type: Object,
    default: null
  }
})

const emit = defineEmits(['save', 'cancel'])

const formTitle = ref('')
const fields = ref<any[]>([])
const selectedField = ref<any>(null)

const fieldTypes = [
  { label: 'Text', value: 'text' },
  { label: 'Number', value: 'number' },
  { label: 'Email', value: 'email' },
  { label: 'Password', value: 'password' },
  { label: 'Checkbox', value: 'checkbox' },
  { label: 'Radio', value: 'radio' },
  { label: 'Select', value: 'select' },
  { label: 'Textarea', value: 'textarea' },
  { label: 'Date', value: 'date' }
]

watch(() => props.form, (newForm) => {
  if (newForm) {
    formTitle.value = newForm.title
    fields.value = [...newForm.fields]
  } else {
    formTitle.value = ''
    fields.value = []
  }
}, { immediate: true })

const addField = () => {
  const newField = {
    id: Date.now().toString(),
    type: 'text',
    label: '',
    required: false,
    placeholder: '',
    options: []
  }
  fields.value.push(newField)
  selectedField.value = newField
}

const removeField = (id: string) => {
  fields.value = fields.value.filter(f => f.id !== id)
  if (selectedField.value?.id === id) {
    selectedField.value = null
  }
}

const addOption = () => {
  if (selectedField.value) {
    selectedField.value.options.push({
      label: '',
      value: ''
    })
  }
}

const removeOption = (index: number) => {
  if (selectedField.value) {
    selectedField.value.options.splice(index, 1)
  }
}

const saveForm = () => {
  emit('save', {
    title: formTitle.value,
    fields: fields.value
  })
}
</script>

<template>
  <div class="form-builder">
    <div class="form-header">
      <input 
        v-model="formTitle" 
        placeholder="Form Title" 
        class="form-title"
      >
      <button @click="saveForm" class="save-btn">Save Form</button>
      <button @click="$emit('cancel')" class="cancel-btn">Cancel</button>
    </div>

    <div class="builder-container">
      <div class="fields-list">
        <button @click="addField" class="add-field-btn">Add Field</button>

        <div 
          v-for="field in fields" 
          :key="field.id" 
          class="field-item"
          :class="{ selected: selectedField?.id === field.id }"
          @click="selectedField = field"
        >
          {{ field.label || 'Unnamed Field' }} ({{ field.type }})
          <button @click.stop="removeField(field.id)" class="remove-btn">×</button>
        </div>
      </div>

      <div class="field-editor" v-if="selectedField">
        <div class="field-property">
          <label>Field Type:</label>
          <select v-model="selectedField.type">
            <option v-for="type in fieldTypes" :value="type.value">
              {{ type.label }}
            </option>
          </select>
        </div>

        <div class="field-property">
          <label>Label:</label>
          <input v-model="selectedField.label" placeholder="Field label">
        </div>

        <div class="field-property">
          <label>
            <input type="checkbox" v-model="selectedField.required">
            Required
          </label>
        </div>

        <div class="field-property">
          <label>Placeholder:</label>
          <input v-model="selectedField.placeholder" placeholder="Placeholder text">
        </div>

        <div v-if="['select', 'radio'].includes(selectedField.type)" class="options-section">
          <h4>Options</h4>
          <button @click="addOption" class="add-option-btn">Add Option</button>

          <div v-for="(option, index) in selectedField.options" :key="index" class="option-item">
            <input v-model="option.label" placeholder="Option label">
            <input v-model="option.value" placeholder="Option value">
            <button @click="removeOption(index)" class="remove-option-btn">×</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

