<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps(['roles'])

const newRoleName = ref('')
const newPermissions = ref([])
const availablePermissions = ref([
  'create', 'read', 'update', 'delete', 'manage_users', 'manage_roles'
])

const addRole = () => {
  if (!newRoleName.value) return

  props.roles.push({
    id: Date.now(),
    name: newRoleName.value,
    permissions: [...newPermissions.value]
  })

  newRoleName.value = ''
  newPermissions.value = []
}

const togglePermission = (permission) => {
  if (newPermissions.value.includes(permission)) {
    newPermissions.value = newPermissions.value.filter(p => p !== permission)
  } else {
    newPermissions.value.push(permission)
  }
}
</script>

<template>
  <div class="role-management">
    <h2>Role Management</h2>

    <div class="card">
      <h3>Add New Role</h3>
      <div class="form-group">
        <label>Role Name</label>
        <input v-model="newRoleName" type="text" placeholder="Enter role name">
      </div>
      <div class="form-group">
        <label>Permissions</label>
        <div class="permissions-grid">
          <div 
            v-for="perm in availablePermissions" 
            :key="perm"
            class="permission-item"
            :class="{ selected: newPermissions.includes(perm) }"
            @click="togglePermission(perm)"
          >
            {{ perm }}
          </div>
        </div>
      </div>
      <button @click="addRole" class="btn">Add Role</button>
    </div>

    <div class="roles-list">
      <h3>Existing Roles</h3>
      <div v-for="role in roles" :key="role.id" class="role-card">
