<script setup lang="ts">
import { ref, computed } from 'vue'

const props = defineProps(['users', 'roles'])

const newUsername = ref('')
const newPassword = ref('')
const newRole = ref(props.roles[0]?.id || null)
const searchQuery = ref('')

const filteredUsers = computed(() => {
  if (!searchQuery.value) return props.users
  return props.users.filter(user => 
    user.username.toLowerCase().includes(searchQuery.value.toLowerCase())
  )
})

const addUser = () => {
  if (!newUsername.value || !newPassword.value || !newRole.value) return

  const role = props.roles.find(r => r.id === newRole.value)

  props.users.push({
    id: Date.now(),
    username: newUsername.value,
    password: newPassword.value,
    role: role.name
  })

  newUsername.value = ''
  newPassword.value = ''
  newRole.value = props.roles[0]?.id || null
}
</script>

<template>
