<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps<{
  mode: string
}>()

const emit = defineEmits(['auth-success', 'switch-view'])

const formData = ref({
  username: '',
  email: '',
  password: '',
  confirmPassword: ''
})

const error = ref('')

const validateForm = () => {
  if (props.mode === 'register' && formData.value.password !== formData.value.confirmPassword) {
    error.value = 'Passwords do not match'
    return false
  }
  if (formData.value.password.length < 6) {
    error.value = 'Password must be at least 6 characters'
    return false
  }
  error.value = ''
  return true
}

const handleSubmit = () => {
  if (!validateForm()) return

  // In a real app, this would call your backend API
  emit('auth-success', {
    username: formData.value.username,
    email: formData.value.email
  })
}

const switchAuthMode = () => {
  const newMode = props.mode === 'login' ? 'register' : 'login'
  emit('switch-view', newMode)
}

const requestPasswordReset = () => {
  emit('switch-view', 'reset')
}
</script>

<template>
  <div class="auth-container">
    <h2>{{ mode === 'login' ? 'Login' : mode === 'register' ? 'Register' : 'Reset Password' }}</h2>

    <form @submit.prevent="handleSubmit">
      <div v-if="mode === 'register'" class="form-group">
        <label>Username</label>
        <input v-model="formData.username" required />
      </div>

      <div class="form-group">
        <label>Email</label>
        <input v-model="formData.email" type="email" required />
      </div>

      <div v-if="mode !== 'reset'" class="form-group">
        <label>Password</label>
        <input v-model="formData.password" type="password" required />
      </div>

      <div v-if="mode === 'register'" class="form-group">
        <label>Confirm Password</label>
        <input v-model="formData.confirmPassword" type="password" required />
      </div>

      <div v-if="error" class="error-message">{{ error }}</div>

      <button type="submit">
        {{ mode === 'login' ? 'Login' : mode === 'register' ? 'Register' : 'Reset Password' }}
      </button>
    </form>

    <div class="auth-actions">
      <button v-if="mode !== 'reset'" @click="switchAuthMode">
        {{ mode === 'login' ? 'Need an account? Register' : 'Already have an account? Login' }}
      </button>
      <button v-if="mode === 'login'" @click="requestPasswordReset">
        Forgot Password?
      </button>
    </div>
  </div>
</template>

