<script setup lang="ts">
import { ref, computed } from 'vue'
import ProductList from './components/ProductList.vue'
import ArticleList from './components/ArticleList.vue'

const products = ref([
  { id: 1, name: 'Premium Headphones', category: 'Audio', price: 199.99, rating: 4.5, image: '/placeholder-product.jpg', description: 'High-quality noise-cancelling headphones with premium sound.' },
  { id: 2, name: 'Wireless Keyboard', category: 'Accessories', price: 79.99, rating: 4.2, image: '/placeholder-product.jpg', description: 'Ergonomic wireless keyboard with long battery life.' },
  { id: 3, name: 'Smart Watch', category: 'Wearables', price: 249.99, rating: 4.7, image: '/placeholder-product.jpg', description: 'Feature-packed smartwatch with health monitoring.' },
  { id: 4, name: 'Bluetooth Speaker', category: 'Audio', price: 129.99, rating: 4.3, image: '/placeholder-product.jpg', description: 'Portable speaker with 20-hour battery life.' },
  { id: 5, name: 'Gaming Mouse', category: 'Accessories', price: 59.99, rating: 4.8, image: '/placeholder-product.jpg', description: 'High-precision gaming mouse with customizable buttons.' }
])

const articles = ref([
  { id: 1, title: 'How to Choose the Right Headphones', date: '2023-10-15', excerpt: 'Learn what features to look for in your next pair of headphones.' },
  { id: 2, title: 'The Future of Wearable Technology', date: '2023-09-28', excerpt: 'Exploring upcoming trends in smart wearables.' }
])

const searchQuery = ref('')
const selectedCategory = ref('All')
const activeTab = ref('products')

const filteredProducts = computed(() => {
  return products.value.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
                         product.description.toLowerCase().includes(searchQuery.value.toLowerCase())
    const matchesCategory = selectedCategory.value === 'All' || 
                          product.category === selectedCategory.value
    return matchesSearch && matchesCategory
  })
})

const categories = computed(() => {
  const allCategories = ['All', ...new Set(products.value.map(p => p.category))]
  return allCategories
})
</script>

<template>
  <div class="app-container">
    <header>
      <h1>Product Showcase</h1>
      <div class="tabs">
        <button 
          @click="activeTab = 'products'"
          :class="{ active: activeTab === 'products' }"
        >
          Products
        </button>
        <button 
          @click="activeTab = 'articles'"
          :class="{ active: activeTab === 'articles' }"
        >
          Articles
        </button>
      </div>
    </header>

    <main>
      <div v-if="activeTab === 'products'" class="products-view">
        <div class="controls">
          <input 
            type="text" 
            v-model="searchQuery" 
            placeholder="Search products..."
          />
          <select v-model="selectedCategory">
            <option v-for="category in categories" :key="category" :value="category">
