<script setup lang="ts">
import { ref } from 'vue'

const zoom = ref(1)
const center = ref({ lat: 0, lng: 0 })

function handleZoomIn() {
  zoom.value = Math.min(zoom.value + 0.5, 5)
}

function handleZoomOut() {
  zoom.value = Math.max(zoom.value - 0.5, 0.5)
}

function handleMapClick(e: MouseEvent) {
  const rect = (e.target as HTMLElement).getBoundingClientRect()
  center.value = {
    lat: ((e.clientY - rect.top) / rect.height - 0.5) * 180,
    lng: ((e.clientX - rect.left) / rect.width - 0.5) * 360
  }
}
</script>

<template>
  <div class="map-container">
    <div class="map-controls">
      <button @click="handleZoomIn">+</button>
      <button @click="handleZoomOut">-</button>
    </div>
    <div 
      class="map" 
      @click="handleMapClick"
      :style="{
        transform: `scale(${zoom})`,
        transformOrigin: 'center center'
      }"
    >
      <div class="grid">
        <div class="grid-line" v-for="i in 18" :key="i"></div>
      </div>
      <div class="marker" :style="{
        top: `${50 - center.lat / 1.8}%`,
        left: `${50 + center.lng / 3.6}%`
      }"></div>
    </div>
