  <boltAction type="file" filePath="script.js">const validateBtn = document.getElementById('validateBtn');
const urlInput = document.getElementById('urlInput');
const errorMessage = document.getElementById('errorMessage');

const validDomains = ['example.com', 'trustedsite.org'];

validateBtn.addEventListener('click', () => {
  const url = urlInput.value.trim();

  if (!url) {
    showError('Please enter a URL');
    return;
  }

  try {
    const urlObj = new URL(url.startsWith('http') ? url : `https://${url}`);
    const domain = urlObj.hostname.replace('www.', '');

    if (validDomains.includes(domain)) {
      // In a real implementation, you would redirect here
      alert(`Valid URL detected. Would redirect to: ${urlObj.href}`);
    } else {
      showError('Invalid domain. Please enter a trusted website URL.');
    }
  } catch (e) {
    showError('Invalid URL format. Please enter a valid URL.');
  }
});

function showError(message) {
  errorMessage.textContent = message;
  errorMessage.classList.remove('hidden');
}</boltAction>

