import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useContentStore = defineStore('content', () => {
  const siteTitle = ref('Enterprise CMS')
  const tabs = ref([
    { id: 'home', label: 'Home', content: 'Welcome to our website!' },
    { id: 'about', label: 'About', content: 'Learn more about our company.' },
    { id: 'contact', label: 'Contact', content: 'Get in touch with us.' }
  ])

  const widgets = ref<Record<string, any[]>>({
    home: [],
    about: [],
    contact: []
  })

  const messages = ref([
    { id: 1, author: 'Admin', text: 'Welcome to our message board!' }
  ])

  function addTab(label: string) {
    const id = label.toLowerCase().replace(/\s+/g, '-')
    tabs.value.push({ id, label, content: '' })
    widgets.value[id] = []
  }

  function addWidget(tabId: string, type: string) {
    const baseWidget = { type }
    if (type === 'text') {
      widgets.value[tabId].push({ ...baseWidget, content: 'New text content' })
    } else if (type === 'image') {
      widgets.value[tabId].push({ ...baseWidget, url: '', alt: '' })
    } else {
      widgets.value[tabId].push(baseWidget)
    }
  }

  function removeWidget(tabId: string, index: number) {
    widgets.value[tabId].splice(index, 1)
  }

  function getWidgets(tabId: string) {
    return widgets.value[tabId] || []
  }

  function addMessage(message: Omit<typeof messages.value[0], 'id'>) {
    messages.value.push({
      id: messages.value.length + 1,
      ...message
    })
  }

  function deleteMessage(id: number) {
    messages.value = messages.value.filter(m => m.id !== id)
  }

  function getComponent(tabId: string) {
    return {
      template: `<div>${tabs.value.find(t => t.id === tabId)?.content}</div>`
    }
  }

  return {
    siteTitle,
    tabs,
    widgets,
    messages,
    addTab,
    addWidget,
    removeWidget,
    getWidgets,
    addMessage,
    deleteMessage,
    getComponent
  }
})
</boltAction>

