import { useCallback, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, ImagePlus } from 'lucide-react';

interface ImageUploaderProps {
  onImageUpload: (file: File) => void;
}

export function ImageUploader({ onImageUpload }: ImageUploaderProps) {
  const [preview, setPreview] = useState<string | null>(null);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setPreview(reader.result as string);
        onImageUpload(file);
      };
      reader.readAsDataURL(file);
    }
  }, [onImageUpload]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.jpeg', '.jpg', '.png', '.webp']
    },
    maxFiles: 1
  });

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div
        {...getRootProps()}
        className={`border-2 border-dashed border-primary rounded-xl p-8 text-center cursor-pointer transition-colors ${
          isDragActive ? 'bg-primary/10' : 'bg-white'
        }`}
      >
        <input {...getInputProps()} />
        {preview ? (
          <div className="relative">
            <img
              src={preview}
              alt="Preview"
              className="max-h-80 w-auto mx-auto rounded-lg"
            />
            <button
              type="button"
              className="mt-4 flex items-center justify-center gap-2 bg-primary text-white px-4 py-2 rounded-lg hover:bg-primary-dark transition-colors mx-auto"
            >
              <ImagePlus size={18} />
              Change Image
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="bg-primary/10 p-4 rounded-full inline-block">
              <Upload className="text-primary" size={32} />
            </div>
            <h3 className="text-lg font-medium text-text">
              {isDragActive ? 'Drop your image here' : 'Drag & drop your image'}
            </h3>
            <p className="text-light-text">or click to browse</p>
            <p className="text-sm text-light-text">
              Supports: JPEG, JPG, PNG, WEBP
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
  </boltAction>

