import { useState, useEffect } from 'react';
import { Loader2, CheckCircle, Download } from 'lucide-react';

interface PreviewPanelProps {
  effect: string | null;
  image: File | null;
}

export function PreviewPanel({ effect, image }: PreviewPanelProps) {
  const [processedImage, setProcessedImage] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (effect && image) {
      setIsProcessing(true);
      // Simulate AI processing delay
      const timer = setTimeout(() => {
        // In a real app, this would be the processed image from your API
        const reader = new FileReader();
        reader.onload = () => {
          setProcessedImage(reader.result as string);
          setIsProcessing(false);
        };
        reader.readAsDataURL(image);
      }, 2000);

      return () => clearTimeout(timer);
    }
  }, [effect, image]);

  if (!effect || !image) return null;

  return (
    <div className="mt-8 bg-white rounded-xl p-6 shadow-sm">
      <h2 className="text-xl font-bold text-text mb-4">Preview</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <h3 className="font-medium text-light-text mb-2">Original</h3>
          <img
            src={URL.createObjectURL(image)}
            alt="Original"
            className="w-full h-auto rounded-lg"
          />
        </div>
        <div>
          <h3 className="font-medium text-light-text mb-2">Processed</h3>
          {isProcessing ? (
            <div className="h-full flex flex-col items-center justify-center bg-background rounded-lg">
              <Loader2 className="animate-spin text-primary" size={32} />
              <p className="mt-4 text-light-text">Processing your image...</p>
            </div>
          ) : (
            <div className="relative">
              <img
                src={processedImage || ''}
                alt="Processed"
                className="w-full h-auto rounded-lg"
              />
              {processedImage && (
                <div className="absolute bottom-4 right-4 flex gap-2">
                  <button className="bg-primary text-white p-2 rounded-full hover:bg-primary-dark transition-colors">
                    <Download size={20} />
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
      {processedImage && (
        <div className="mt-6 bg-success/10 text-success p-3 rounded-lg flex items-center gap-2">
          <CheckCircle size={18} />
          <span>Processing complete! Ready to download or purchase credits.</span>
        </div>
      )}
    </div>
  );
}
  </boltAction>

