import { useState } from 'react';
import { Navbar } from './components/Navbar';
import { ImageUploader } from './components/ImageUploader';
import { EffectSelector } from './components/EffectSelector';
import { PreviewPanel } from './components/PreviewPanel';
import { PricingPlans } from './components/PricingPlans';

function App() {
  const [image, setImage] = useState<File | null>(null);
  const [effect, setEffect] = useState<string | null>(null);

  const handleImageUpload = (file: File) => {
    setImage(file);
  };

  const handleEffectSelect = (effectId: string) => {
    setEffect(effectId);
  };

  return (
    <div className="min-h-screen bg-background">
      <Navbar />
      <main className="container mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold text-text text-center mb-2">
          AI Image Processing
        </h1>
        <p className="text-light-text text-center mb-8">
          Upload your image and apply stunning AI effects in seconds
        </p>

        <ImageUploader onImageUpload={handleImageUpload} />
        {image && (
          <>
            <EffectSelector onEffectSelect={handleEffectSelect} />
            <PreviewPanel effect={effect} image={image} />
          </>
        )}
        <PricingPlans />
      </main>
    </div>
  );
}

export default App;
