    items.value.push({
      id: items.value.length + 1,
      ...newItem.value
    })
    newItem.value = { name: '', price: 0, description: '' }
  }
}

const purchaseItem = (id: number) => {
  items.value = items.value.filter(item => item.id !== id)
}
