<script setup lang="ts">
import { ref, onMounted } from 'vue'

const flashSales = ref([
  {
    id: 1,
    name: '4K Smart TV',
    price: 399.99,
    originalPrice: 599.99,
    image: 'tv.jpg',
    endTime: Date.now() + 3600000 // 1 hour from now
  },
  {
    id: 2,
    name: 'Gaming Laptop',
    price: 899.99,
    originalPrice: 1299.99,
    image: 'laptop.jpg',
    endTime: Date.now() + 7200000 // 2 hours from now
  }
])

const timeLeft = ref<{[key: number]: string}>({})

const updateCountdown = () => {
  const now = Date.now()
  flashSales.value.forEach(sale => {
    const diff = sale.endTime - now
    if (diff <= 0) {
      timeLeft.value[sale.id] = 'Ended'
    } else {
      const hours = Math.floor(diff / (1000 * 60 * 60))
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))
      const seconds = Math.floor((diff % (1000 * 60)) / 1000)
      timeLeft.value[sale.id] = `${hours}h ${minutes}m ${seconds}s`
    }
  })
}

onMounted(() => {
  updateCountdown()
  setInterval(updateCountdown, 1000)
})

const addToCart = (id: number) => {
  console.log('Added flash sale item to cart:', id)
}
</script>

