<boltAction type="file" filePath="src/views/CartView.vue">
<script setup lang="ts">
import { ref } from 'vue'

const cartItems = ref([
  { id: 1, name: 'Premium Headphones', price: 99.99, quantity: 1 },
  { id: 2, name: 'Smart Watch', price: 149.99, quantity: 1 }
])

const couponCode = ref('')
const subtotal = ref(cartItems.value.reduce((sum, item) => sum + (item.price * item.quantity), 0))
const discount = ref(0)
const total = ref(subtotal.value - discount.value)

const updateQuantity = (id: number, change: number) => {
  const item = cartItems.value.find(i => i.id === id)
  if (item) {
    item.quantity = Math.max(1, item.quantity + change)
    updateTotals()
  }
}

const removeItem = (id: number) => {
  cartItems.value = cartItems.value.filter(i => i.id !== id)
  updateTotals()
}

const applyCoupon = () => {
  // In a real app, this would validate with the server
  if (couponCode.value === 'SAAS10') {
    discount.value = subtotal.value * 0.1
    total.value = subtotal.value - discount.value
  }
}

const updateTotals = () => {
  subtotal.value = cartItems.value.reduce((sum, item) => sum + (item.price * item.quantity), 0)
  total.value = subtotal.value - discount.value
}

const checkout = () => {
  console.log('Proceeding to checkout')
}
</script>

<template>
  <div class="cart-view">
    <h1>Your Shopping Cart</h1>

    <div v-if="cartItems.length === 0" class="empty-cart">
      <p>Your cart is empty</p>
      <router-link to="/" class="continue-shopping">Continue Shopping</router-link>
    </div>

    <div v-else>
      <div class="cart-items">
        <div v-for="item in cartItems" :key="item.id" class="cart-item">
          <div class="item-info">
            <h3>{{ item.name }}</h3>
            <p>${{ item.price.toFixed(2) }}</p>
          </div>
          <div class="item-quantity">
            <button @click="updateQuantity(item.id, -1)">-</button>
            <span>{{ item.quantity }}</span>
            <button @click="updateQuantity(item.id, 1)">+</button>
          </div>
          <div class="item-total">
            ${{ (item.price * item.quantity).toFixed(2) }}
          </div>
          <button class="remove-btn" @click="removeItem(item.id)">Remove</button>
        </div>
      </div>

      <div class="coupon-section">
        <input v-model="couponCode" placeholder="Enter coupon code">
        <button @click="applyCoupon">Apply Coupon</button>
      </div>

      <div class="summary">
        <div class="summary-row">
          <span>Subtotal:</span>
          <span>${{ subtotal.toFixed(2) }}</span>
        </div>
        <div v-if="discount > 0" class="summary-row">
          <span>Discount:</span>
          <span>-${{ discount.toFixed(2) }}</span>
        </div>
        <div class="summary-row total">
          <span>Total:</span>
          <span>${{ total.toFixed(2) }}</span>
        </div>
        <button class="checkout-btn" @click="checkout">Proceed to Checkout</button>
      </div>
    </div>
  </div>
</template>

