<script setup lang="ts">
import { ref, computed } from 'vue'
import { useProducts } from '../stores/products'

const productStore = useProducts()

interface Order {
  id: number
  productId: number
  amount: number
  status: 'pending' | 'completed' | 'cancelled'
  date: string
}

const orders = ref<Order[]>([
  { id: 1, productId: 1, amount: 1, status: 'completed', date: '2023-05-15' },
  { id: 2, productId: 2, amount: 1, status: 'pending', date: '2023-05-16' },
  { id: 3, productId: 3, amount: 1, status: 'cancelled', date: '2023-05-17' }
])

const newOrder = ref({
  productId: 1,
  amount: 1
})

const addOrder = () => {
  const order: Order = {
    id: Math.max(0, ...orders.value.map(o => o.id)) + 1,
    productId: newOrder.value.productId,
    amount: newOrder.value.amount,
    status: 'pending',
    date: new Date().toISOString().split('T')[0]
  }
  orders.value.push(order)
}

const updateOrderStatus = (id: number, status: 'completed' | 'cancelled') => {
  const order = orders.value.find(o => o.id === id)
  if (order) {
    order.status = status
  }
}

const filteredOrders = computed(() => {
  return orders.value.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
})
</script>

