interface Product {
  id: number
  name: string
  description: string
  price: number
  available: boolean
}

export const useProducts = () => {
  const products = ref<Product[]>([
    { id: 1, name: 'Savings Account', description: 'Basic savings account', price: 0, available: true },
    { id: 2, name: 'Investment Fund', description: 'Medium risk investment', price: 1000, available: true },
    { id: 3, name: 'Premium Card', description: 'Exclusive benefits card', price: 50, available: false }
  ])

  const availableProducts = computed(() => {
    return products.value.filter(p => p.available)
  })

  const getProductById = (id: number) => {
    return products.value.find(p => p.id === id)
  }

  return {
    products,
    availableProducts,
    getProductById
  }
}
