<script setup lang="ts">
import { ref, computed } from 'vue'
import ProductList from './ProductList.vue'
import OrderHistory from './OrderHistory.vue'
import AccountSettings from './AccountSettings.vue'

const props = defineProps({
  user: Object
})

const emit = defineEmits(['logout'])

const activeTab = ref('products')
const cart = ref([])
const orders = ref([])

const products = ref([
  { id: 1, name: 'Basic Plan', price: 9.99, description: 'Basic features' },
  { id: 2, name: 'Pro Plan', price: 19.99, description: 'Advanced features' },
  { id: 3, name: 'Enterprise Plan', price: 49.99, description: 'All features + support' }
])

const addToCart = (product) => {
  cart.value.push(product)
}

const removeFromCart = (index) => {
  cart.value.splice(index, 1)
}

const placeOrder = () => {
  const newOrder = {
    id: Date.now(),
    date: new Date().toISOString(),
    items: [...cart.value],
    total: cart.value.reduce((sum, item) => sum + item.price, 0)
  }
  orders.value.unshift(newOrder)
  cart.value = []
  activeTab.value = 'orders'
}

const cartTotal = computed(() => {
  return cart.value.reduce((sum, item) => sum + item.price, 0)
})
</script>

<template>
