<script setup lang="ts">
import { ref } from 'vue'
import ProductCard from './ProductCard.vue'
import AdPublisher from './AdPublisher.vue'
import ConversionTracker from './ConversionTracker.vue'

const products = ref([
  { id: 1, name: 'Smartphone', price: 599, views: 0, clicks: 0 },
  { id: 2, name: 'Laptop', price: 1299, views: 0, clicks: 0 },
  { id: 3, name: 'Headphones', price: 199, views: 0, clicks: 0 }
])

const selectedProduct = ref(null)
const showAdPublisher = ref(false)

function trackView(productId: number) {
  const product = products.value.find(p => p.id === productId)
  if (product) product.views++
}

function trackClick(productId: number) {
  const product = products.value.find(p => p.id === productId)
  if (product) product.clicks++
}

function selectProduct(product: any) {
  selectedProduct.value = product
  showAdPublisher.value = true
}
</script>

<template>
  <div class="catalog-container">
    <h1 style="color: darkmagenta">Product Catalog</h1>

    <div class="products-grid">
      <ProductCard 
        v-for="product in products" 
        :key="product.id"
        :product="product"
        @view="trackView(product.id)"
        @click="trackClick(product.id)"
        @select="selectProduct(product)"
      />
    </div>

    <AdPublisher 
      v-if="showAdPublisher && selectedProduct"
      :product="selectedProduct"
      @close="showAdPublisher = false"
    />

    <ConversionTracker :products="products" />
  </div>
</template>

