      :is="currentView === 'login' ? LoginForm : 
           currentView === 'register' ? RegisterForm : 
           isAdmin ? AdminPanel : Dashboard"
      @login="handleLogin"
      @logout="handleLogout"
      @navigate="(view) => currentView = view"
    />
  </div>
</template>

