const payments = ref([
  { id: 1, amount: 100, date: '2023-05-15', status: 'Completed' },
  { id: 2, amount: 50, date: '2023-06-20', status: 'Pending' }
])

const amount = ref('')
const paymentError = ref('')

const makePayment = () => {
  if (!amount.value) {
    paymentError.value = 'Please enter an amount'
    return
  }

  payments.value.unshift({
    id: payments.value.length + 1,
    amount: parseFloat(amount.value),
