<script setup lang="ts">
import { ref, reactive } from 'vue'

const envVars = reactive<Record<string, string>>({})
const newVarName = ref('')
const newVarValue = ref('')
const selectedVar = ref('')
const editValue = ref('')
const fileInput = ref<HTMLInputElement | null>(null)

const loadFromFile = () => {
  if (fileInput.value?.files?.length) {
    const file = fileInput.value.files[0]
    const reader = new FileReader()
    reader.onload = (e) => {
      const content = e.target?.result as string
      content.split('\n').forEach(line => {
        const [key, value] = line.split('=')
        if (key && value) {
          envVars[key.trim()] = value.trim()
        }
      })
    }
    reader.readAsText(file)
  }
}

const addVariable = () => {
  if (newVarName.value && newVarValue.value) {
    envVars[newVarName.value] = newVarValue.value
    newVarName.value = ''
    newVarValue.value = ''
  }
}

const editVariable = (key: string) => {
  selectedVar.value = key
  editValue.value = envVars[key]
}

const saveEdit = () => {
  if (selectedVar.value) {
    envVars[selectedVar.value] = editValue.value
    selectedVar.value = ''
  }
}

const deleteVariable = (key: string) => {
  delete envVars[key]
}

const saveToFile = () => {
  let content = ''
  for (const key in envVars) {
    content += `${key}=${envVars[key]}\n`
  }

  const blob = new Blob([content], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = '.env'
  a.click()
  URL.revokeObjectURL(url)
}
</script>

<template>
  <div class="env-manager">
    <div class="file-actions">
      <input 
        type="file" 
        ref="fileInput" 
        accept=".env,.txt" 
        style="display: none" 
        @change="loadFromFile"
      />
      <button @click="fileInput?.click()" class="action-btn">Load from File</button>
      <button @click="saveToFile" class="action-btn">Save to File</button>
    </div>

    <div class="add-variable">
      <input v-model="newVarName" placeholder="Variable name" class="input-field" />
      <input v-model="newVarValue" placeholder="Variable value" class="input-field" />
      <button @click="addVariable" class="add-btn">Add</button>
    </div>

    <div class="variables-list">
      <div v-for="(value, key) in envVars" :key="key" class="variable-item">
        <div v-if="selectedVar !== key" class="variable-display">
          <span class="variable-name">{{ key }}</span>
          <span class="variable-value">{{ value }}</span>
          <div class="variable-actions">
            <button @click="editVariable(key)" class="edit-btn">Edit</button>
            <button @click="deleteVariable(key)" class="delete-btn">Delete</button>
          </div>
        </div>

        <div v-else class="variable-edit">
          <span class="variable-name">{{ key }}</span>
          <input v-model="editValue" class="edit-input" />
          <button @click="saveEdit" class="save-btn">Save</button>
          <button @click="selectedVar = ''" class="cancel-btn">Cancel</button>
        </div>
      </div>
    </div>
  </div>
</template>

