<script setup lang="ts">
import { ref, onMounted } from 'vue'
import DocumentList from '../components/DocumentList.vue'
import DatabaseList from '../components/DatabaseList.vue'

const props = defineProps<{
  username: string
}>()

const emit = defineEmits(['logout'])

const currentDatabase = ref('')
const documents = ref<any[]>([])
const databases = ref<string[]>([])
const newDbName = ref('')
const newDocContent = ref('{}')
const query = ref('')

onMounted(() => {
  loadDatabases()
})

const loadDatabases = () => {
  const userDbs = localStorage.getItem(`dbs_${props.username}`)
  databases.value = userDbs ? JSON.parse(userDbs) : []
}

const createDatabase = () => {
  if (newDbName.value.trim()) {
    databases.value.push(newDbName.value)
    localStorage.setItem(`dbs_${props.username}`, JSON.stringify(databases.value))
    newDbName.value = ''
  }
}

const selectDatabase = (dbName: string) => {
  currentDatabase.value = dbName
  loadDocuments()
}

const loadDocuments = () => {
  const dbData = localStorage.getItem(`db_${props.username}_${currentDatabase.value}`)
  documents.value = dbData ? JSON.parse(dbData) : []
}

const createDocument = () => {
  try {
    const doc = JSON.parse(newDocContent.value)
    doc.id = Date.now().toString()
    documents.value.push(doc)
    localStorage.setItem(
      `db_${props.username}_${currentDatabase.value}`,
      JSON.stringify(documents.value)
    )
    newDocContent.value = '{}'
  } catch (e) {
    alert('Invalid JSON')
  }
}

const updateDocument = (id: string, content: string) => {
  try {
    const docIndex = documents.value.findIndex(d => d.id === id)
    if (docIndex !== -1) {
      documents.value[docIndex] = JSON.parse(content)
      localStorage.setItem(
        `db_${props.username}_${currentDatabase.value}`,
        JSON.stringify(documents.value)
      )
    }
  } catch (e) {
    alert('Invalid JSON')
  }
}

const deleteDocument = (id: string) => {
  documents.value = documents.value.filter(d => d.id !== id)
  localStorage.setItem(
    `db_${props.username}_${currentDatabase.value}`,
    JSON.stringify(documents.value)
  )
}

const searchDocuments = () => {
  if (!query.value.trim()) {
    loadDocuments()
    return
  }

  const searchTerm = query.value.toLowerCase()
  documents.value = documents.value.filter(doc => {
    return JSON.stringify(doc).toLowerCase().includes(searchTerm)
  })
}
</script>

<template>
  <div class="db-view">
    <header class="db-header">
      <h2>Welcome, {{ username }}</h2>
      <button @click="emit('logout')" class="logout-button">Logout</button>
    </header>

    <div class="db-container">
      <div class="db-sidebar">
        <DatabaseList 
          :databases="databases"
          @select="selectDatabase"
        />

        <div class="db-create">
          <input v-model="newDbName" placeholder="New database name" />
          <button @click="createDatabase">Create DB</button>
        </div>
      </div>

      <div class="db-content">
        <div v-if="currentDatabase">
          <div class="doc-actions">
            <textarea v-model="newDocContent" placeholder="Document JSON"></textarea>
            <button @click="createDocument">Add Document</button>

            <div class="search-box">
              <input v-model="query" placeholder="Search documents..." />
              <button @click="searchDocuments">Search</button>
            </div>
          </div>

          <DocumentList 
            :documents="documents"
            @update="updateDocument"
            @delete="deleteDocument"
          />
        </div>

        <div v-else class="db-placeholder">
          <p>Select or create a database to get started</p>
        </div>
      </div>
    </div>
  </div>
</template>

