<script setup lang="ts">
import { ref } from 'vue'

const file = ref<File | null>(null)
const encryptionMethod = ref('AES-256-CBC')
const encryptionKey = ref('')
const encryptedContent = ref('')
const fileName = ref('')

const handleFileChange = (e: Event) => {
  const target = e.target as HTMLInputElement
  if (target.files && target.files.length > 0) {
    file.value = target.files[0]
    fileName.value = file.value.name
  }
}

const encryptFile = () => {
  if (!file.value) return

  const reader = new FileReader()
  reader.onload = (e) => {
    const content = e.target?.result as string
    // In a real app, you would use a proper encryption library here
    // This is just a simulation for the demo
    encryptedContent.value = btoa(content)
  }
  reader.readAsText(file.value)
}

const downloadEncryptedFile = () => {
  if (!encryptedContent.value) return

  const blob = new Blob([encryptedContent.value], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
