<script setup lang="ts">
import { ref } from 'vue'

const file = ref<File | null>(null)
const decryptionMethod = ref('AES-256-CBC')
const decryptionKey = ref('')
const decryptedContent = ref('')
const fileName = ref('')

const handleFileChange = (e: Event) => {
  const target = e.target as HTMLInputElement
  if (target.files && target.files.length > 0) {
    file.value = target.files[0]
    fileName.value = file.value.name
  }
}

const decryptFile = () => {
  if (!file.value) return

  const reader = new FileReader()
  reader.onload = (e) => {
    const content = e.target?.result as string
    // In a real app, you would use a proper decryption library here
    // This is just a simulation for the demo
    decryptedContent.value = atob(content)
  }
  reader.readAsText(file.value)
}

const downloadDecryptedFile = () => {
  if (!decryptedContent.value) return

  const blob = new Blob([decryptedContent.value], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `decrypted_${fileName.value}`
  a.click()
  URL.revokeObjectURL(url)
}
</script>

