import axios from 'axios';
import { Client } from '@hubspot/api-client';

const hubspotClient = new Client({
  accessToken: process.env.HUBSPOT_ACCESS_TOKEN
});

export async function handleKlaviyoWebhook(payload: any) {
  try {
    // Process subscriber data
    const { email, properties } = payload.data;

    // Update HubSpot contact
    const contact = await hubspotClient.crm.contacts.basicApi.update(email, {
      properties: {
        ...properties,
        klaviyo_subscriber: true
      }
    });

    // Create timeline event
    await hubspotClient.crm.timeline.eventsApi.create({
      eventTemplateId: process.env.HUBSPOT_EVENT_TEMPLATE_ID,
      email,
      extraData: {
        klaviyo_event: payload.event_type
      }
    });

    return { success: true, contact };
  } catch (error) {
    console.error('Webhook processing failed:', error);
    throw error;
  }
}
