<script setup lang="ts">
import { ref } from 'vue'

const url = ref('')
const selector = ref('')
const extractedData = ref('')
const isLoading = ref(false)
const error = ref('')

async function extractData() {
  if (!url.value) {
    error.value = 'Please enter a URL'
    return
  }

  isLoading.value = true
  error.value = ''

  try {
    const response = await fetch(`https://api.allorigins.win/get?url=${encodeURIComponent(url.value)}`)
    const data = await response.json()

    if (data.contents) {
      const parser = new DOMParser()
      const doc = parser.parseFromString(data.contents, 'text/html')

      if (selector.value) {
        const elements = doc.querySelectorAll(selector.value)
        extractedData.value = Array.from(elements).map(el => el.textContent).join('\n')
      } else {
        extractedData.value = doc.body?.textContent || 'No content found'
      }
    } else {
      error.value = 'Failed to fetch page content'
    }
  } catch (err) {
    error.value = 'An error occurred while scraping'
    console.error(err)
  } finally {
    isLoading.value = false
  }
}

function saveData() {
  if (!extractedData.value) return

  const blob = new Blob([extractedData.value], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'scraped_data.txt'
  a.click()
  URL.revokeObjectURL(url)
}
</script>

