<script setup lang="ts">
import { ref, computed } from 'vue'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['logout'])

const contractType = ref('procurement')
const logo = ref(null)
const amount = ref(0)
const copies = ref(1)
const taxCode = ref('')

const amountInWords = computed(() => {
  // Simplified Chinese number to words conversion
  const units = ['', '十', '百', '千']
  const digits = ['零', '壹', '贰', '叁', '肆', '伍', '陆', '柒', '捌', '玖']

  let num = Math.floor(amount.value)
  if (num === 0) return '零元整'

  let result = ''
  let unitPos = 0

  while (num > 0) {
    const digit = num % 10
    if (digit !== 0) {
      result = digits[digit] + units[unitPos] + result
    } else {
      if (result[0] !== '零') {
        result = '零' + result
      }
    }
    num = Math.floor(num / 10)
    unitPos++
  }

  return result + '元整'
})

const handleLogoUpload = (event: Event) => {
  const target = event.target as HTMLInputElement
  if (target.files && target.files[0]) {
    const reader = new FileReader()
    reader.onload = (e) => {
      logo.value = e.target?.result
    }
    reader.readAsDataURL(target.files[0])
  }
}

const generateTaxCode = () => {
  // Generate a random tax code (simplified)
  taxCode.value = 'TAX-' + Math.floor(Math.random() * 1000000).toString().padStart(6, '0')
}

const printContract = () => {
  // In a real app, this would open print dialog
  alert(`Printing ${copies.value} copies of ${contractType.value} contract`)
}
</script>

