<script setup lang="ts">
import { ref } from 'vue'

const emit = defineEmits(['login'])

const username = ref('')
const password = ref('')
const isRegistering = ref(false)
const name = ref('')
const email = ref('')
const error = ref('')

// Mock users database
const users = ref([
  { id: 1, username: 'user1', password: 'pass1', name: 'John Doe', email: 'john@example.com', role: 'user' },
  { id: 2, username: 'admin', password: 'admin', name: 'Admin', email: 'admin@example.com', role: 'admin' }
])

const handleSubmit = () => {
  if (isRegistering.value) {
    // Register new user
    const newUser = {
      id: users.value.length + 1,
      username: username.value,
      password: password.value,
      name: name.value,
      email: email.value,
      role: 'user'
    }
    users.value.push(newUser)
    emit('login', newUser)
  } else {
    // Login existing user
    const user = users.value.find(
      u => u.username === username.value && u.password === password.value
    )
    if (user) {
      emit('login', user)
    } else {
      error.value = 'Invalid username or password'
    }
  }
}
</script>

<template>
