<boltAction type="file" filePath="src/App.vue">
<script setup lang="ts">
import { ref } from 'vue'
import LoginForm from './components/LoginForm.vue'
import VehicleRegistration from './components/VehicleRegistration.vue'
import AuditDashboard from './components/AuditDashboard.vue'
import CertificateView from './components/CertificateView.vue'

const currentUser = ref(null)
const currentView = ref('login')
const registeredVehicles = ref([])
const auditedVehicles = ref([])

const handleLogin = (user) => {
  currentUser.value = user
  currentView.value = user.role === 'director' ? 'audit' : 'register'
}

const handleRegister = (vehicle) => {
  registeredVehicles.value.push({
    ...vehicle,
    status: 'pending',
    id: Date.now()
  })
}

const handleAudit = (vehicleId, decision) => {
  const vehicle = registeredVehicles.value.find(v => v.id === vehicleId)
  if (vehicle) {
    vehicle.status = decision ? 'approved' : 'rejected'
    if (decision) {
      auditedVehicles.value.push(vehicle)
    }
  }
}

const handleLogout = () => {
  currentUser.value = null
  currentView.value = 'login'
}
</script>

<template>
  <div class="app-container">
    <header>
      <h1>Vehicle Audit System</h1>
      <button v-if="currentUser" @click="handleLogout">Logout</button>
    </header>

    <main>
      <LoginForm v-if="currentView === 'login'" @login="handleLogin" />
      <VehicleRegistration 
        v-else-if="currentView === 'register'" 
        @register="handleRegister" 
      />
      <AuditDashboard 
        v-else-if="currentView === 'audit'" 
        :vehicles="registeredVehicles.filter(v => v.status === 'pending')"
        @audit="handleAudit"
      />
      <CertificateView 
        v-else-if="currentView === 'certificate'"
        :vehicles="auditedVehicles"
      />
    </main>
  </div>
</template>

