<script setup lang="ts">
import { ref } from 'vue'

const gfwlistContent = ref('')
const customRules = ref('')
const proxyAddress = ref('PROXY 127.0.0.1:1080')
const pacContent = ref('')
const isLoading = ref(false)

const handleFileUpload = (event: Event) => {
  const file = (event.target as HTMLInputElement).files?.[0]
  if (file) {
    const reader = new FileReader()
    reader.onload = (e) => {
      gfwlistContent.value = e.target?.result as string
    }
    reader.readAsText(file)
  }
}

const fetchGFWList = async () => {
  try {
    isLoading.value = true
    const response = await fetch('https://raw.githubusercontent.com/gfwlist/gfwlist/master/gfwlist.txt')
    const data = await response.text()
    gfwlistContent.value = atob(data)
  } catch (error) {
    alert('Error fetching gfwlist.txt')
    console.error(error)
  } finally {
    isLoading.value = false
  }
}

const generatePAC = () => {
  const domains = gfwlistContent.value
    .split('\n')
    .filter(line => line.startsWith('||') && !line.includes('*'))
    .map(line => line.substring(2).replace(/\/.*$/, ''))
    .filter(domain => domain)

  const customDomains = customRules.value
    .split('\n')
    .filter(line => line.trim() !== '')

  const allDomains = [...new Set([...domains, ...customDomains])]

  pacContent.value = `function FindProxyForURL(url, host) {
  // Domains to proxy
  const proxyDomains = [
    ${allDomains.map(d => `"${d}"`).join(',\n    ')}
  ];

  // Check if host matches any proxy domain
  if (proxyDomains.some(domain => host.endsWith(domain))) {
    return "${proxyAddress.value}";
  }

  // Default direct connection
  return "DIRECT";
}`
}

const downloadPAC = () => {
  const blob = new Blob([pacContent.value], { type: 'application/x-ns-proxy-autoconfig' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'proxy.pac'
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}
</script>

<template>
  <div class="container">
    <h1>PAC File Generator</h1>

    <div class="card">
      <h2>GFWList Configuration</h2>
      <div class="button-group">
        <button @click="fetchGFWList" :disabled="isLoading">
          {{ isLoading ? 'Loading...' : 'Fetch GFWList' }}
        </button>
        <label class="upload-btn">
          Upload gfwlist.txt
          <input type="file" @change="handleFileUpload" accept=".txt" hidden>
        </label>
      </div>
      <textarea v-model="gfwlistContent" placeholder="Paste gfwlist.txt content here..."></textarea>
    </div>

    <div class="card">
      <h2>Custom Rules</h2>
      <textarea v-model="customRules" placeholder="Add custom domains (one per line)"></textarea>
    </div>

    <div class="card">
      <h2>Proxy Settings</h2>
      <input type="text" v-model="proxyAddress" placeholder="Enter proxy address (e.g. PROXY 127.0.0.1:1080)">
    </div>

    <div class="button-group">
      <button @click="generatePAC">Generate PAC File</button>
      <button @click="downloadPAC" :disabled="!pacContent">Download PAC File</button>
    </div>

    <div class="card" v-if="pacContent">
