<script setup lang="ts">
import { ref, onMounted } from 'vue'

const scriptContent = ref('print("Hello, World!")')
const output = ref('')
const history = ref<Array<{id: number, script: string, output: string, timestamp: string}>>([])
const selectedScript = ref<number | null>(null)
const isRunning = ref(false)

const runScript = async () => {
  if (isRunning.value) return

  isRunning.value = true
  output.value = 'Running script...'

  try {
    // In a real implementation, this would call a backend API
    // For WebContainer, we'll simulate execution
    const result = await executePython(scriptContent.value)
    output.value = result

    // Add to history
    const newEntry = {
      id: Date.now(),
      script: scriptContent.value,
      output: result,
      timestamp: new Date().toLocaleString()
    }
    history.value.unshift(newEntry)
    selectedScript.value = newEntry.id

  } catch (error) {
    output.value = `Error: ${error instanceof Error ? error.message : String(error)}`
  } finally {
    isRunning.value = false
  }
}

const executePython = (code: string): Promise<string> => {
  return new Promise((resolve) => {
    // Simulate execution delay
    setTimeout(() => {
      try {
        // In a real implementation, this would use a Python interpreter
        // For demo purposes, we'll just return a mock response
        if (code.includes('error')) {
          throw new Error('Simulated Python error')
        }
        resolve(`Execution result for:\n${code}\n\nOutput: Script executed successfully`)
      } catch (error) {
        resolve(`Python Error: ${error instanceof Error ? error.message : String(error)}`)
      }
    }, 1000)
  })
}

const loadFromHistory = (id: number) => {
  const entry = history.value.find(item => item.id === id)
  if (entry) {
    scriptContent.value = entry.script
    output.value = entry.output
    selectedScript.value = id
  }
}

const clearHistory = () => {
  history.value = []
  selectedScript.value = null
}

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (input.files && input.files[0]) {
    const file = input.files[0]
    const reader = new FileReader()
    reader.onload = (e) => {
      scriptContent.value = e.target?.result as string
    }
    reader.readAsText(file)
  }
}
</script>

<template>
  <div class="script-runner">
    <div class="editor-container">
      <h2>Python Script Editor</h2>
      <div class="controls">
        <button @click="runScript" :disabled="isRunning">
          {{ isRunning ? 'Running...' : 'Run Script' }}
        </button>
        <label class="upload-btn">
          Upload Script
          <input type="file" accept=".py,.txt" @change="handleFileUpload" style="display: none;">
        </label>
      </div>
      <textarea v-model="scriptContent" class="script-editor"></textarea>
    </div>

    <div class="output-container">
      <h2>Output</h2>
      <pre class="output">{{ output || 'Output will appear here...' }}</pre>
    </div>

    <div class="history-container" v-if="history.length > 0">
      <h2>Execution History</h2>
      <button @click="clearHistory" class="clear-btn">Clear History</button>
      <ul class="history-list">
        <li 
          v-for="entry in history" 
          :key="entry.id"
          :class="{selected: selectedScript === entry.id}"
          @click="loadFromHistory(entry.id)"
        >
          <div class="history-item">
            <span class="timestamp">{{ entry.timestamp }}</span>
            <span class="script-preview">{{ entry.script.substring(0, 50) }}{{ entry.script.length > 50 ? '...' : '' }}</span>
          </div>
        </li>
      </ul>
    </div>
  </div>
