<script setup lang="ts">
import { ref } from 'vue'
import JSZip from 'jszip'
import { saveAs } from 'file-saver'

const files = ref<File[]>([])
const email = ref('')
const isLoading = ref(false)
const message = ref('')

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (input.files) {
    files.value = Array.from(input.files)
  }
}

const createZip = async () => {
  if (files.value.length === 0) {
    message.value = 'Please upload files first'
    return
  }

  isLoading.value = true
  const zip = new JSZip()

  try {
    for (const file of files.value) {
      zip.file(file.name, file)
    }

    const content = await zip.generateAsync({ type: 'blob' })
    saveAs(content, 'archive.zip')
    message.value = 'Zip created and downloaded successfully!'
  } catch (error) {
    message.value = 'Error creating zip file'
    console.error(error)
  } finally {
    isLoading.value = false
  }
}

const sendZip = () => {
  if (!email.value) {
    message.value = 'Please enter an email address'
    return
  }

  // In a real app, you would send the zip to a server here
  message.value = `Zip would be sent to ${email.value} in a real implementation`
}
</script>

