<script setup lang="ts">
import { ref, computed } from 'vue'

const query = ref('')
const results = ref<any[]>([])
const error = ref('')
const currentDateTime = computed(() => new Date().toLocaleString())

const executeQuery = () => {
  try {
    // Validate query input
    if (!query.value.trim()) {
      throw new Error('Query cannot be empty')
    }
    if (query.value.toLowerCase().includes('drop') || 
        query.value.toLowerCase().includes('delete')) {
      throw new Error('DROP/DELETE commands are not allowed')
    }

    // Simulate query execution (in a real app, this would call an API)
    results.value = [
      { id: 1, name: 'Sample Result 1', value: 100 },
      { id: 2, name: 'Sample Result 2', value: 200 }
    ]
    error.value = ''
  } catch (err) {
    error.value = err instanceof Error ? err.message : 'Query execution failed'
    results.value = []
  }
}
</script>

