  const query = searchQuery.value.toLowerCase()
  return db.tables.filter(table => 
    table.name.toLowerCase().includes(query) ||
    table.comment.toLowerCase().includes(query) ||
    table.fields.some(field => 
      field.name.toLowerCase().includes(query) ||
      field.comment.toLowerCase().includes(query)
    )
  )
})

const updateComment = (tableName: string, fieldName: string, newComment: string) => {
  const db = databases.value.find(db => db.name === selectedDatabase.value)
  if (!db) return

  const table = db.tables.find(t => t.name === tableName)
  if (!table) return

  if (fieldName) {
    const field = table.fields.find(f => f.name === fieldName)
    if (field) field.comment = newComment
  } else {
    table.comment = newComment
  }
}
</script>

<template>
  <div class="database-browser">
    <div class="search-container">
      <input 
        v-model="searchQuery" 
        placeholder="Search tables or fields..." 
        class="search-input"
      />
    </div>

    <div class="database-selector">
      <label>Select Database:</label>
      <select v-model="selectedDatabase">
        <option value="">-- Select --</option>
        <option v-for="db in databases" :key="db.name" :value="db.name">
          {{ db.name }}
        </option>
      </select>
    </div>

    <div class="tables-list">
      <h3>Tables</h3>
      <ul>
        <li 
          v-for="table in filteredTables" 
          :key="table.name"
          @click="selectedTable = table.name"
          :class="{ active: selectedTable === table.name }"
        >
          {{ table.name }}
          <span class="table-comment">{{ table.comment }}</span>
        </li>
      </ul>
    </div>

    <TableDetails 
      v-if="selectedTable" 
      :table="filteredTables.find(t => t.name === selectedTable)" 
      @update-comment="updateComment"
    />
  </div>
</template>

