<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps<{
  table: {
    name: string
    comment: string
    fields: Array<{
      name: string
      type: string
      comment: string
    }>
  }
}>()

const emit = defineEmits(['update-comment'])

const editingField = ref('')
const newComment = ref('')

const startEditing = (fieldName: string, currentComment: string) => {
  editingField.value = fieldName
  newComment.value = currentComment
}

const saveComment = (tableName: string, fieldName: string) => {
  emit('update-comment', tableName, fieldName, newComment.value)
  editingField.value = ''
}
</script>

