<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { mockAlerts } from '../services/financialData'

const alerts = ref<any[]>([])
const newAlert = ref({
  type: 'price',
  symbol: '',
  condition: 'above',
  value: ''
})

onMounted(() => {
  alerts.value = mockAlerts()
})

function addAlert() {
  if (newAlert.value.symbol && newAlert.value.value) {
    alerts.value.unshift({
      id: Date.now(),
      ...newAlert.value,
      active: true,
      timestamp: new Date().toISOString()
    })
    newAlert.value = {
      type: 'price',
      symbol: '',
      condition: 'above',
      value: ''
    }
  }
}

function toggleAlert(id: number) {
  const alert = alerts.value.find(a => a.id === id)
  if (alert) {
    alert.active = !alert.active
  }
}
</script>

<template>
  <div class="alert-center">
    <h2>Alert Center</h2>

    <div class="alert-form">
      <select v-model="newAlert.type">
        <option value="price">Price</option>
        <option value="volume">Volume</option>
        <option value="change">% Change</option>
      </select>

      <input v-model="newAlert.symbol" placeholder="Symbol" />

      <select v-model="newAlert.condition">
        <option value="above">Above</option>
        <option value="below">Below</option>
        <option value="equals">Equals</option>
      </select>

      <input v-model="newAlert.value" placeholder="Value" type="number" />

      <button @click="addAlert" class="add-button">Create Alert</button>
    </div>

    <div class="alert-list">
      <div v-for="alert in alerts" :key="alert.id" class="alert-item" :class="{ active: alert.active }">
        <div class="alert-content">
          <span class="symbol">{{ alert.symbol }}</span>
          <span class="condition">
            {{ alert.type }} {{ alert.condition }} {{ alert.value }}
