          <span class="timestamp">{{ new Date(alert.timestamp).toLocaleString() }}</span>
        </div>
        <button @click="toggleAlert(alert.id)" class="toggle-button">
          {{ alert.active ? 'Disable' : 'Enable' }}
        </button>
      </div>
    </div>
  </div>
</template>

