export function mockHistoricalData(symbol: string, range: string) {
  const basePrice = symbol === 'AAPL' ? 180 : 
                   symbol === 'GOOGL' ? 140 : 
                   symbol === 'MSFT' ? 400 : 
                   symbol === 'AMZN' ? 175 : 170

  const count = range === '1w' ? 7 : 
               range === '1m' ? 30 : 
               range === '3m' ? 90 : 365

  const data = []
  const today = new Date()

  for (let i = count; i >= 0; i--) {
    const date = new Date(today)
    date.setDate(date.getDate() - i)

    const volatility = 0.02
    const open = basePrice * (1 + (Math.random() - 0.5) * volatility)
    const close = open * (1 + (Math.random() - 0.5) * volatility * 2)
    const high = Math.max(open, close) * (1 + Math.random() * volatility)
    const low = Math.min(open, close) * (1 - Math.random() * volatility)
    const volume = Math.floor(10000000 + Math.random() * 50000000)

    data.push({
      date: date.toISOString().split('T')[0],
      open: parseFloat(open.toFixed(2)),
      high: parseFloat(high.toFixed(2)),
      low: parseFloat(low.toFixed(2)),
      close: parseFloat(close.toFixed(2)),
      volume: volume
    })
  }

  return data
}
