<script setup lang="ts">
import { ref } from 'vue'

const inputData = ref('')
const validationMode = ref('email')
const results = ref<string[]>([])
const errorMessage = ref('')

const validationPatterns = {
  email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  phone: /^\+?[\d\s-]{10,15}$/,
  zipcode: /^\d{5}(-\d{4})?$/,
  date: /^\d{4}-\d{2}-\d{2}$/
}

function validateData() {
  errorMessage.value = ''
  const lines = inputData.value.split('\n').filter(line => line.trim())

  if (!lines.length) {
    errorMessage.value = 'Please enter some data to validate'
    return
  }

  const pattern = validationPatterns[validationMode.value as keyof typeof validationPatterns]
  results.value = lines.filter(line => pattern.test(line.trim()))

  if (!results.value.length) {
    errorMessage.value = `No valid ${validationMode.value} patterns found`
  }
}
</script>

<template>
  <div class="validator-container">
    <h1>Data Validator</h1>

    <div class="input-section">
      <label for="validationMode">Validation Mode:</label>
      <select id="validationMode" v-model="validationMode">
        <option value="email">Email</option>
        <option value="phone">Phone Number</option>
        <option value="zipcode">Zip Code</option>
