    cast: ["Marlon Brando", "Al Pacino", "James Caan"],
    genre: ["Crime", "Drama"],
    rating: 9.2,
    year: 1972,
    duration: 175,
    description: "The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant son.",
    posterUrl: "https://images.unsplash.com/photo-1611591437281-460914d22501?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80"
  },
  // More movies...
]

export const getGenres = () => {
  const allGenres = movies.flatMap(movie => movie.genre)
  return [...new Set(allGenres)]
}

export const getRatingDistribution = () => {
  const distribution = [0, 0, 0, 0, 0] // 0-1, 1-2, 2-3, 3-4, 4-5
  movies.forEach(movie => {
    const index = Math.floor(movie.rating / 2)
    distribution[index]++
  })
  return distribution
}

export const getGenreDistribution = () => {
  const genres = getGenres()
  const distribution = genres.map(genre => ({
    genre,
    count: movies.filter(movie => movie.genre.includes(genre)).length
  }))
  return distribution
}
