import { useState, useEffect } from 'react'
import { Activity, Database, LineChart, Plus, Settings, Trash2 } from 'lucide-react'
import EmissionsForm from './components/EmissionsForm'
import EmissionsChart from './components/EmissionsChart'
import DataTable from './components/DataTable'

type EmissionRecord = {
  id: string
  date: string
  source: string
  activity: string
  value: number
  unit: string
}

export default function App() {
  const [records, setRecords] = useState<EmissionRecord[]>([])
  const [activeTab, setActiveTab] = useState<'form' | 'data' | 'chart'>('form')
  const [selectedRecord, setSelectedRecord] = useState<EmissionRecord | null>(null)

  useEffect(() => {
    const savedRecords = localStorage.getItem('emissionRecords')
    if (savedRecords) {
      setRecords(JSON.parse(savedRecords))
    }
  }, [])

  const saveRecords = (newRecords: EmissionRecord[]) => {
    setRecords(newRecords)
    localStorage.setItem('emissionRecords', JSON.stringify(newRecords))
  }

  const addRecord = (record: Omit<EmissionRecord, 'id'>) => {
    const newRecord = { ...record, id: Date.now().toString() }
    saveRecords([...records, newRecord])
  }

  const updateRecord = (id: string, updatedRecord: Omit<EmissionRecord, 'id'>) => {
    const updatedRecords = records.map(record => 
      record.id === id ? { ...updatedRecord, id } : record
    )
    saveRecords(updatedRecords)
    setSelectedRecord(null)
  }

  const deleteRecord = (id: string) => {
    const updatedRecords = records.filter(record => record.id !== id)
    saveRecords(updatedRecords)
    if (selectedRecord?.id === id) {
      setSelectedRecord(null)
    }
  }

  return (
    <div className="min-h-screen bg-aliceblue">
      <header className="bg-cornflowerblue text-white p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Activity className="w-6 h-6" /> Carbon Emissions Tracker
          </h1>
          <button className="p-2 rounded-full hover:bg-blue-700">
            <Settings className="w-5 h-5" />
          </button>
        </div>
      </header>

      <main className="container mx-auto p-4">
        <div className="flex mb-6 border-b border-gray-200">
          <button
            onClick={() => setActiveTab('form')}
            className={`px-4 py-2 font-medium flex items-center gap-2 ${activeTab === 'form' ? 'text-cornflowerblue border-b-2 border-cornflowerblue' : 'text-gray-600'}`}
          >
            <Plus className="w-4 h-4" /> Add Data
          </button>
          <button
            onClick={() => setActiveTab('data')}
            className={`px-4 py-2 font-medium flex items-center gap-2 ${activeTab === 'data' ? 'text-cornflowerblue border-b-2 border-cornflowerblue' : 'text-gray-600'}`}
          >
            <Database className="w-4 h-4" /> View Data
          </button>
          <button
            onClick={() => setActiveTab('chart')}
            className={`px-4 py-2 font-medium flex items-center gap-2 ${activeTab === 'chart' ? 'text-cornflowerblue border-b-2 border-cornflowerblue' : 'text-gray-600'}`}
          >
            <LineChart className="w-4 h-4" /> Visualize
          </button>
        </div>

        {activeTab === 'form' && (
          <EmissionsForm 
            addRecord={addRecord} 
            updateRecord={updateRecord}
            selectedRecord={selectedRecord}
            setSelectedRecord={setSelectedRecord}
          />
        )}

        {activeTab === 'data' && (
          <DataTable 
            records={records} 
            setSelectedRecord={setSelectedRecord}
            deleteRecord={deleteRecord}
            setActiveTab={setActiveTab}
          />
        )}

        {activeTab === 'chart' && <EmissionsChart records={records} />}
      </main>
    </div>
  )
}
