import { useEffect, useState } from 'react'
import { EmissionRecord } from '../App'

type EmissionsFormProps = {
  addRecord: (record: Omit<EmissionRecord, 'id'>) => void
  updateRecord: (id: string, record: Omit<EmissionRecord, 'id'>) => void
  selectedRecord: EmissionRecord | null
  setSelectedRecord: (record: EmissionRecord | null) => void
}

const activityTypes = [
  'Electricity',
  'Natural Gas',
  'Transportation',
  'Waste',
  'Water',
  'Business Travel',
  'Commuting'
]

const units = ['kg CO₂', 'tons CO₂', 'kg CO₂e', 'tons CO₂e']

export default function EmissionsForm({
  addRecord,
  updateRecord,
  selectedRecord,
  setSelectedRecord
}: EmissionsFormProps) {
  const [formData, setFormData] = useState<Omit<EmissionRecord, 'id'>>({
    date: new Date().toISOString().split('T')[0],
    source: '',
    activity: activityTypes[0],
    value: 0,
    unit: units[0]
  })

  useEffect(() => {
    if (selectedRecord) {
      const { id, ...rest } = selectedRecord
      setFormData(rest)
    }
  }, [selectedRecord])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target
    setFormData(prev => ({
      ...prev,
      [name]: name === 'value' ? parseFloat(value) || 0 : value
    }))
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (selectedRecord) {
      updateRecord(selectedRecord.id, formData)
    } else {
      addRecord(formData)
      setFormData({
        date: new Date().toISOString().split('T')[0],
        source: '',
        activity: activityTypes[0],
        value: 0,
        unit: units[0]
      })
    }
  }

  const handleCancel = () => {
    setSelectedRecord(null)
    setFormData({
      date: new Date().toISOString().split('T')[0],
      source: '',
      activity: activityTypes[0],
      value: 0,
      unit: units[0]
    })
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h2 className="text-xl font-semibold mb-4 text-gray-800">
        {selectedRecord ? 'Edit Emission Record' : 'Add New Emission Data'}
      </h2>
      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
            <input
              type="date"
              name="date"
              value={formData.date}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-cornflowerblue focus:border-cornflowerblue"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Source</label>
            <input
              type="text"
              name="source"
              value={formData.source}
              onChange={handleChange}
              placeholder="e.g., Office Building A"
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-cornflowerblue focus:border-cornflowerblue"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Activity Type</label>
            <select
              name="activity"
              value={formData.activity}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-cornflowerblue focus:border-cornflowerblue"
            >
              {activityTypes.map(type => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Emission Value</label>
            <input
              type="number"
              name="value"
              value={formData.value}
              onChange={handleChange}
              min="0"
              step="0.01"
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-cornflowerblue focus:border-cornflowerblue"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Unit</label>
            <select
              name="unit"
              value={formData.unit}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-cornflowerblue focus:border-cornflowerblue"
            >
              {units.map(unit => (
                <option key={unit} value={unit}>{unit}</option>
              ))}
            </select>
          </div>
        </div>
        <div className="flex justify-end gap-2">
          {selectedRecord && (
            <button
              type="button"
              onClick={handleCancel}
              className="px-4 py-2 bg-gray-300 text-gray-800 rounded-md hover:bg-gray-400"
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className="px-4 py-2 bg-cornflowerblue text-white rounded-md hover:bg-blue-700"
          >
            {selectedRecord ? 'Update Record' : 'Add Record'}
          </button>
