import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, BarChart, Bar } from 'recharts'
import { EmissionRecord } from '../App'
import { useState } from 'react'

type ChartData = {
  date: string
  [key: string]: string | number
}

export default function EmissionsChart({ records }: { records: EmissionRecord[] }) {
  const [chartType, setChartType] = useState<'line' | 'bar'>('line')

  // Group data by date and activity type
  const groupedData = records.reduce((acc: Record<string, ChartData>, record) => {
    if (!acc[record.date]) {
      acc[record.date] = { date: record.date }
    }
    acc[record.date][record.activity] = (acc[record.date][record.activity] || 0) + record.value
    return acc
  }, {})

  const chartData = Object.values(groupedData)
  const activities = [...new Set(records.map(r => r.activity))]

  if (records.length === 0) {
    return (
      <div className="bg-white p-6 rounded-lg shadow-md">
        <h2 className="text-xl font-semibold mb-4 text-gray-800">Emission Trends</h2>
        <p className="text-gray-500">No data available for visualization. Add some records first.</p>
      </div>
    )
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-semibold text-gray-800">Emission Trends</h2>
        <div className="flex gap-2">
          <button
            onClick={() => setChartType('line')}
            className={`px-3 py-1 rounded-md ${chartType === 'line' ? 'bg-cornflowerblue text-white' : 'bg-gray-200 text-gray-700'}`}
          >
            Line Chart
          </button>
          <button
            onClick={() => setChartType('bar')}
            className={`px-3 py-1 rounded-md ${chartType === 'bar' ? 'bg-cornflowerblue text-white' : 'bg-gray-200 text-gray-700'}`}
          >
            Bar Chart
          </button>
        </div>
      </div>
      <div className="h-96">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'line' ? (
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />
              {activities.map((activity, idx) => (
                <Line
                  key={activity}
                  type="monotone"
                  dataKey={activity}
                  stroke={`hsl(${(idx * 360) / activities.length}, 70%, 50%)`}
                  activeDot={{ r: 8 }}
                />
              ))}
            </LineChart>
          ) : (
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />
              {activities.map((activity, idx) => (
                <Bar
                  key={activity}
                  dataKey={activity}
                  fill={`hsl(${(idx * 360) / activities.length}, 70%, 50%)`}
                />
              ))}
            </BarChart>
          )}
        </ResponsiveContainer>
      </div>
    </div>
  )
}
