import React, { useState, useRef } from 'react';
import { Download, BarChart2, PieChart, LineChart, Settings, RefreshCw } from 'lucide-react';
import * as htmlToImage from 'html-to-image';

type ChartType = 'bar' | 'pie' | 'line';
type ChartData = {
  labels: string[];
  values: number[];
  colors: string[];
};

const ChartGenerator = () => {
  const [chartType, setChartType] = useState<ChartType>('bar');
  const [title, setTitle] = useState('My Chart');
  const [data, setData] = useState<ChartData>({
    labels: ['Jan', 'Feb', 'Mar', 'Apr'],
    values: [30, 50, 20, 80],
    colors: ['#B88B8B', '#D4A5A5', '#E0B9B9', '#E8CECE']
  });
  const chartRef = useRef<HTMLDivElement>(null);

  const handleAddData = () => {
    const newLabel = `Data ${data.labels.length + 1}`;
    setData({
      ...data,
      labels: [...data.labels, newLabel],
      values: [...data.values, Math.floor(Math.random() * 100)],
      colors: [...data.colors, `#${Math.floor(Math.random()*16777215).toString(16)}`]
    });
  };

  const handleRemoveData = (index: number) => {
    const newData = {...data};
    newData.labels.splice(index, 1);
    newData.values.splice(index, 1);
    newData.colors.splice(index, 1);
    setData(newData);
  };

  const handleDownload = async () => {
    if (chartRef.current) {
      const dataUrl = await htmlToImage.toPng(chartRef.current);
      const link = document.createElement('a');
      link.download = `${title.toLowerCase().replace(/\s+/g, '-')}.png`;
      link.href = dataUrl;
      link.click();
    }
  };

  const renderChart = () => {
    switch (chartType) {
      case 'bar':
        return (
          <div className="h-full w-full flex items-end gap-2">
            {data.values.map((value, i) => (
              <div key={i} className="flex flex-col items-center flex-1">
                <div 
                  className="w-full rounded-t-sm"
                  style={{
                    height: `${value}%`,
                    backgroundColor: data.colors[i]
                  }}
                />
                <span className="text-xs mt-1">{data.labels[i]}</span>
              </div>
            ))}
          </div>
        );
      case 'pie':
        return (
          <div className="relative w-48 h-48 rounded-full overflow-hidden">
            {data.values.map((value, i) => {
              const total = data.values.reduce((a, b) => a + b, 0);
              const percentage = (value / total) * 100;
              const angle = (data.values.slice(0, i).reduce((a, b) => a + b, 0) / total) * 360;

              return (
                <div
                  key={i}
                  className="absolute inset-0 origin-center"
                  style={{
                    transform: `rotate(${angle}deg)`,
                    clipPath: `polygon(50% 50%, 50% 0%, ${percentage > 50 ? '100% 0%, 100% 100%, 50% 50%' : `${50 + Math.cos((percentage * 3.6) * Math.PI / 180) * 50}% ${50 - Math.sin((percentage * 3.6) * Math.PI / 180) * 50}%, 50% 50%`})`,
                    backgroundColor: data.colors[i]
                  }}
                />
              );
            })}
            <div className="absolute inset-4 bg-cornsilk rounded-full flex items-center justify-center">
              <span className="text-xs font-medium">{title}</span>
            </div>
          </div>
        );
      case 'line':
        return (
          <div className="h-full w-full relative">
            <svg viewBox="0 0 100 100" className="w-full h-full">
              <polyline
                fill="none"
                stroke="#B88B8B"
                strokeWidth="2"
                points={data.values.map((v, i) => `${(i * 100) / (data.values.length - 1)},${100 - v}`).join(' ')}
              />
              {data.values.map((v, i) => (
                <circle
                  key={i}
                  cx={`${(i * 100) / (data.values.length - 1)}`}
                  cy={`${100 - v}`}
                  r="3"
                  fill={data.colors[i]}
                />
              ))}
            </svg>
            <div className="absolute bottom-0 left-0 right-0 flex justify-between">
              {data.labels.map((label, i) => (
                <span key={i} className="text-xs">{label}</span>
              ))}
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-cornsilk p-6">
      <div className="max-w-6xl mx-auto">
        <h1 className="text-3xl font-bold text-rosybrown mb-8">Statistical Chart Generator</h1>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Controls */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-xl font-semibold text-rosybrown mb-4 flex items-center gap-2">
              <Settings size={20} /> Chart Settings
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Chart Type</label>
                <div className="flex gap-2">
                  <button
                    onClick={() => setChartType('bar')}
                    className={`flex-1 py-2 px-3 rounded-md flex items-center justify-center gap-2 ${chartType === 'bar' ? 'bg-rosybrown text-white' : 'bg-gray-100'}`}
                  >
                    <BarChart2 size={16} /> Bar
                  </button>
                  <button
                    onClick={() => setChartType('pie')}
                    className={`flex-1 py-2 px-3 rounded-md flex items-center justify-center gap-2 ${chartType === 'pie' ? 'bg-rosybrown text-white' : 'bg-gray-100'}`}
                  >
                    <PieChart size={16} /> Pie
                  </button>
                  <button
                    onClick={() => setChartType('line')}
                    className={`flex-1 py-2 px-3 rounded-md flex items-center justify-center gap-2 ${chartType === 'line' ? 'bg-rosybrown text-white' : 'bg-gray-100'}`}
                  >
                    <LineChart size={16} /> Line
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Chart Title</label>
                <input
                  type="text"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md"
                />
              </div>

              <div>
                <div className="flex justify-between items-center mb-1">
                  <label className="block text-sm font-medium text-gray-700">Data Points</label>
                  <button
                    onClick={handleAddData}
                    className="text-xs bg-rosybrown text-white px-2 py-1 rounded"
                  >
                    Add Data
                  </button>
                </div>

                <div className="space-y-2 max-h-60 overflow-y-auto">
                  {data.labels.map((label, i) => (
                    <div key={i} className="flex items-center gap-2">
                      <input
                        type="text"
                        value={label}
                        onChange={(e) => {
                          const newLabels = [...data.labels];
                          newLabels[i] = e.target.value;
                          setData({...data, labels: newLabels});
                        }}
                        className="flex-1 p-2 border border-gray-300 rounded-md"
                      />
                      <input
                        type="number"
                        value={data.values[i]}
                        onChange={(e) => {
                          const newValues = [...data.values];
                          newValues[i] = Number(e.target.value);
                          setData({...data, values: newValues});
                        }}
                        className="w-16 p-2 border border-gray-300 rounded-md"
                      />
                      <input
                        type="color"
                        value={data.colors[i]}
                        onChange={(e) => {
                          const newColors = [...data.colors];
                          newColors[i] = e.target.value;
                          setData({...data, colors: newColors});
                        }}
                        className="w-8 h-8 cursor-pointer"
                      />
                      <button
                        onClick={() => handleRemoveData(i)}
                        className="text-red-500 hover:text-red-700"
                      >
                        ×
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex gap-2 pt-4">
                <button
                  onClick={() => {
                    setData({
                      labels: ['Jan', 'Feb', 'Mar', 'Apr'],
                      values: [30, 50, 20, 80],
                      colors: ['#B88B8B', '#D4A5A5', '#E0B9B9', '#E8CECE']
                    });
                    setTitle('My Chart');
                  }}
                  className="flex-1 py-2 px-4 bg-gray-100 rounded-md flex items-center justify-center gap-2"
                >
                  <RefreshCw size={16} /> Reset
                </button>
                <button
                  onClick={handleDownload}
                  className="flex-1 py-2 px-4 bg-rosybrown text-white rounded-md flex items-center justify-center gap-2"
                >
                  <Download size={16} /> Download
                </button>
              </div>
            </div>
          </div>

          {/* Chart Preview */}
          <div className="lg:col-span-2">
            <div className="bg-white p-6 rounded-lg shadow-md h-full">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-semibold text-rosybrown">Chart Preview</h2>
                <span className="text-sm text-gray-500">{chartType} chart</span>
              </div>

              <div 
                ref={chartRef}
                className="bg-cornsilk p-6 rounded-md h-96 flex flex-col items-center justify-center"
              >
                <h3 className="text-lg font-medium text-rosybrown mb-4">{title}</h3>
                <div className="w-full h-64">
                  {renderChart()}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChartGenerator;
</boltAction>

