<script setup lang="ts">
import { ref, computed } from 'vue'

// Sample sentiment data
const sentimentData = ref([
  { word: 'happy', value: 0.9 },
  { word: 'sad', value: -0.8 },
  { word: 'angry', value: -0.7 },
  { word: 'joyful', value: 0.8 },
  { word: 'depressed', value: -0.9 },
  { word: 'excited', value: 0.7 },
  { word: 'bored', value: -0.5 },
  { word: 'love', value: 1.0 },
  { word: 'hate', value: -1.0 },
  { word: 'neutral', value: 0.0 }
])

const searchTerm = ref('')
const minSentiment = ref(-1)
const maxSentiment = ref(1)

const filteredWords = computed(() => {
  return sentimentData.value.filter(word => {
    const matchesSearch = word.word.toLowerCase().includes(searchTerm.value.toLowerCase())
    const matchesSentiment = word.value >= minSentiment.value && word.value <= maxSentiment.value
    return matchesSearch && matchesSentiment
  })
})

function getSentimentColor(value: number) {
  if (value > 0) return '#4169E1' // royal blue for positive
  if (value < 0) return '#4169E1' // royal blue for negative
  return '#4169E1' // royal blue for neutral
}
</script>

<template>
  <div class="container">
    <h1>English Word Sentiment Analysis</h1>

    <div class="search-container">
      <input 
        v-model="searchTerm" 
        placeholder="Search for a word..."
        class="search-input"
      />
    </div>

    <div class="filter-container">
      <label>Sentiment Range:</label>
      <div class="range-inputs">
        <input 
          type="range" 
          v-model="minSentiment" 
          min="-1" 
          max="1" 
          step="0.1" 
          class="slider"
        />
        <span>{{ minSentiment }}</span>
        <span>to</span>
        <input 
          type="range" 
          v-model="maxSentiment" 
          min="-1" 
          max="1" 
          step="0.1" 
          class="slider"
        />
        <span>{{ maxSentiment }}</span>
      </div>
    </div>

    <div class="results-container">
      <div v-if="filteredWords.length === 0" class="no-results">
        No words match your search criteria.
      </div>
      <div v-else>
        <div 
          v-for="word in filteredWords" 
          :key="word.word" 
          class="word-card"
          :style="{ backgroundColor: getSentimentColor(word.value) }"
        >
          <span class="word">{{ word.word }}</span>
          <span class="value">{{ word.value.toFixed(2) }}</span>
        </div>
      </div>
    </div>
  </div>
