import React, { useState } from 'react';
import { Header } from './components/Header';
import { SummaryCards } from './components/SummaryCards';
import { PopulationChart } from './components/PopulationChart';
import { CityPopulationTable } from './components/CityPopulationTable';
import { DemographicPieChart } from './components/DemographicPieChart';
import { GenderRatioChart } from './components/GenderRatioChart';
import { SearchFilter } from './components/SearchFilter';
import { sichuanPopulationData } from './data/sichuanPopulation';

function App() {
  const [filteredCities, setFilteredCities] = useState(sichuanPopulationData.cities);

  const handleSearch = (query: string) => {
    if (!query.trim()) {
      setFilteredCities(sichuanPopulationData.cities);
      return;
    }
    const filtered = sichuanPopulationData.cities.filter(city =>
      city.name.toLowerCase().includes(query.toLowerCase())
    );
    setFilteredCities(filtered);
  };

  return (
    <div className="min-h-screen bg-skyblue-100">
      <Header />
      <div className="container mx-auto px-4 py-8">
        <SummaryCards 
          totalPopulation={sichuanPopulationData.totalPopulation} 
          cityCount={sichuanPopulationData.cities.length} 
        />

        <SearchFilter onSearch={handleSearch} />

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          <PopulationChart data={sichuanPopulationData.yearlyTrend} />
          <GenderRatioChart data={sichuanPopulationData.genderRatio} />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          <DemographicPieChart data={sichuanPopulationData.ageDistribution} />
          <CityPopulationTable data={filteredCities} />
        </div>
      </div>
    </div>
  );
}

export default App;
</boltAction>

