<script setup lang="ts">
const alertRules = ref([
  { id: 1, name: 'High Latency', threshold: '>500ms', enabled: true },
  { id: 2, name: 'Error Rate', threshold: '>5%', enabled: true },
  { id: 3, name: 'Downtime', threshold: '>1 minute', enabled: false }
])

const newRule = ref({
  name: '',
  threshold: '',
  enabled: true
})

const addRule = () => {
  if (newRule.value.name && newRule.value.threshold) {
    alertRules.value.push({
      id: alertRules.value.length + 1,
      ...newRule.value
    })
    newRule.value = { name: '', threshold: '', enabled: true }
  }
}

const toggleRule = (id: number) => {
  const rule = alertRules.value.find(r => r.id === id)
  if (rule) rule.enabled = !rule.enabled
}
</script>

<template>
  <div class="alerts-card">
    <h3>Alert Rules</h3>
    <div class="rules-list">
      <div v-for="rule in alertRules" :key="rule.id" class="rule-item">
        <div>
          <strong>{{ rule.name }}</strong>
          <span>Trigger when: {{ rule.threshold }}</span>
        </div>
        <label class="switch">
          <input 
            type="checkbox" 
            :checked="rule.enabled" 
            @change="toggleRule(rule.id)"
          >
          <span class="slider"></span>
        </label>
      </div>
    </div>

    <div class="add-rule">
      <h4>Add New Rule</h4>
      <input v-model="newRule.name" placeholder="Rule name" />
      <input v-model="newRule.threshold" placeholder="Threshold (e.g. >500ms)" />
      <button @click="addRule" class="purple-btn">Add Rule</button>
    </div>
  </div>
</template>

