<script setup lang="ts">
import { onMounted, ref } from 'vue'
import * as d3 from 'd3'
import { useRoute } from 'vue-router'

const route = useRoute()
const graphId = route.params.id
const graphData = ref<any>(null)

// Mock data for visualization
const mockGraph = {
  nodes: [
    { id: 1, label: 'Node 1' },
    { id: 2, label: 'Node 2' },
    { id: 3, label: 'Node 3' }
  ],
  edges: [
    { source: 1, target: 2, label: 'RELATES_TO' },
    { source: 2, target: 3, label: 'CONNECTS' }
  ]
}

onMounted(() => {
  // In a real app, this would fetch from API
  graphData.value = mockGraph
  renderGraph()
})

const renderGraph = () => {
  const svg = d3.select('#graph-container')
    .append('svg')
    .attr('width', 800)
    .attr('height', 600)

  // Create simulation
  const simulation = d3.forceSimulation(mockGraph.nodes)
    .force('link', d3.forceLink(mockGraph.edges).id((d: any) => d.id))
    .force('charge', d3.forceManyBody().strength(-100))
    .force('center', d3.forceCenter(400, 300))

  // Draw links
  const link = svg.append('g')
    .selectAll('line')
    .data(mockGraph.edges)
    .enter().append('line')
    .attr('stroke', '#999')
    .attr('stroke-width', 2)

  // Draw nodes
  const node = svg.append('g')
    .selectAll('circle')
    .data(mockGraph.nodes)
    .enter().append('circle')
    .attr('r', 10)
    .attr('fill', 'darkturquoise')
    .call(d3.drag()
      .on('start', dragstarted)
      .on('drag', dragged)
      .on('end', dragended))

  // Add labels
  const labels = svg.append('g')
    .selectAll('text')
    .data(mockGraph.nodes)
    .enter().append('text')
    .text(d => d.label)
    .attr('font-size', 12)
    .attr('dx', 15)
    .attr('dy', 4)

  // Update positions
  simulation.on('tick', () => {
    link
      .attr('x1', (d: any) => d.source.x)
      .attr('y1', (d: any) => d.source.y)
      .attr('x2', (d: any) => d.target.x)
      .attr('y2', (d: any) => d.target.y)

    node
      .attr('cx', (d: any) => d.x)
      .attr('cy', (d: any) => d.y)

    labels
      .attr('x', (d: any) => d.x)
      .attr('y', (d: any) => d.y)
  })

  function dragstarted(event: any, d: any) {
    if (!event.active) simulation.alphaTarget(0.3).restart()
    d.fx = d.x
    d.fy = d.y
  }

  function dragged(event: any, d: any) {
    d.fx = event.x
    d.fy = event.y
  }

  function dragended(event: any, d: any) {
    if (!event.active) simulation.alphaTarget(0)
    d.fx = null
    d.fy = null
  }
}
</script>

