import { computed } from 'vue'

const props = defineProps<{
  coins: Array<any>
}>()

const totalMarketCap = computed(() => {
  return props.coins.reduce((sum, coin) => sum + coin.market_cap, 0)
})

const totalVolume = computed(() => {
