import { useState } from 'react'
import { Upload, FileText, X } from 'lucide-react'
import Papa from 'papaparse'

interface DataImportProps {
  onDataUpload: (data: any[]) => void
}

export default function DataImport({ onDataUpload }: DataImportProps) {
  const [file, setFile] = useState<File | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0])
    }
  }

  const handleUpload = () => {
    if (!file) return

    setIsLoading(true)

    if (file.name.endsWith('.csv')) {
      Papa.parse(file, {
        header: true,
        complete: (results) => {
          onDataUpload(results.data)
          setIsLoading(false)
        },
        error: () => {
          setIsLoading(false)
        }
      })
    } else {
      const reader = new FileReader()
      reader.onload = (e) => {
        try {
          const data = JSON.parse(e.target?.result as string)
          onDataUpload(data)
        } catch (error) {
          console.error('Error parsing file:', error)
        }
        setIsLoading(false)
      }
      reader.readAsText(file)
    }
  }

  const removeFile = () => {
    setFile(null)
  }

  return (
    <div className="max-w-4xl mx-auto py-8">
      <div className="bg-white rounded-lg shadow-lg p-6">
        <h2 className="text-2xl font-bold text-goldenrod mb-6">Data Import</h2>

        <div className="border-2 border-dashed border-goldenrod rounded-lg p-8 text-center mb-6">
          <div className="flex flex-col items-center justify-center">
            <Upload className="h-12 w-12 text-goldenrod mb-4" />
            <p className="text-gray-600 mb-4">Drag and drop your file here or click to browse</p>
            <input 
              type="file" 
              id="file-upload"
              className="hidden"
              accept=".csv,.json,.xlsx"
              onChange={handleFileChange}
            />
            <label 
              htmlFor="file-upload"
              className="bg-goldenrod text-white px-4 py-2 rounded-md hover:bg-yellow-600 cursor-pointer"
            >
              Select File
            </label>
          </div>
        </div>

        {file && (
          <div className="bg-lightgoldenrodyellow rounded-lg p-4 mb-6 flex items-center justify-between">
            <div className="flex items-center">
              <FileText className="h-5 w-5 text-goldenrod mr-3" />
              <span className="font-medium">{file.name}</span>
            </div>
            <button 
              onClick={removeFile}
              className="text-gray-500 hover:text-gray-700"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        )}

        <button
          onClick={handleUpload}
          disabled={!file || isLoading}
          className={`w-full py-3 rounded-md text-white font-medium ${!file || isLoading ? 'bg-gray-400 cursor-not-allowed' : 'bg-goldenrod hover:bg-yellow-600'}`}
        >
          {isLoading ? 'Processing...' : 'Upload and Process'}
        </button>
      </div>
    </div>
  )
}
