import { useState } from 'react'
import { BarChart2, Clock, Database, Hash, PieChart } from 'lucide-react'

interface AnalysisProps {
  data: any[]
  onAnalysisComplete: (results: any) => void
}

export default function Analysis({ data, onAnalysisComplete }: AnalysisProps) {
  const [selectedAnalysis, setSelectedAnalysis] = useState<string | null>(null)
  const [isAnalyzing, setIsAnalyzing] = useState(false)

  const analysisOptions = [
    {
      id: 'descriptive',
      name: 'Descriptive Statistics',
      description: 'Calculate mean, median, mode, standard deviation, etc.',
      icon: <Database className="h-6 w-6 text-goldenrod" />
    },
    {
      id: 'frequency',
      name: 'Frequency Analysis',
      description: 'Analyze frequency distribution of categorical data',
      icon: <Hash className="h-6 w-6 text-goldenrod" />
    },
    {
      id: 'time-series',
      name: 'Time Series Analysis',
      description: 'Analyze trends and patterns over time',
      icon: <Clock className="h-6 w-6 text-goldenrod" />
    },
    {
      id: 'correlation',
      name: 'Correlation Analysis',
      description: 'Find relationships between variables',
      icon: <BarChart2 className="h-6 w-6 text-goldenrod" />
    },
    {
      id: 'distribution',
      name: 'Distribution Analysis',
      description: 'Analyze data distribution and outliers',
      icon: <PieChart className="h-6 w-6 text-goldenrod" />
    }
  ]

  const performAnalysis = () => {
    if (!selectedAnalysis || data.length === 0) return

    setIsAnalyzing(true)

    // Simulate analysis processing
    setTimeout(() => {
      // In a real app, you would perform actual analysis here
      const results = {
        type: selectedAnalysis,
        summary: `Analysis of ${data.length} records completed`,
        insights: generateMockInsights(selectedAnalysis, data),
        timestamp: new Date().toISOString()
      }

      onAnalysisComplete(results)
      setIsAnalyzing(false)
    }, 1500)
  }

  const generateMockInsights = (type: string, data: any[]) => {
    const insights: any = {}

    if (type === 'descriptive') {
      insights.mean = Math.random() * 100
      insights.median = Math.random() * 100
      insights.mode = Math.random() * 100
      insights.stdDev = Math.random() * 10
    } else if (type === 'frequency') {
      insights.topCategories = [
        { category: 'A', count: Math.floor(Math.random() * 100) },
        { category: 'B', count: Math.floor(Math.random() * 100) },
        { category: 'C', count: Math.floor(Math.random() * 100) }
      ]
    } else if (type === 'time-series') {
      insights.trend = Math.random() > 0.5 ? 'Increasing' : 'Decreasing'
      insights.seasonality = Math.random() > 0.5 ? 'Present' : 'Not significant'
    } else if (type === 'correlation') {
      insights.correlationMatrix = {
        'A vs B': Math.random().toFixed(2),
        'A vs C': Math.random().toFixed(2),
        'B vs C': Math.random().toFixed(2)
      }
    } else if (type === 'distribution') {
      insights.skewness = (Math.random() * 2 - 1).toFixed(2)
      insights.kurtosis = (Math.random() * 4).toFixed(2)
    }

    return insights
  }

  return (
    <div className="max-w-4xl mx-auto py-8">
      <div className="bg-white rounded-lg shadow-lg p-6">
        <h2 className="text-2xl font-bold text-goldenrod mb-6">Data Analysis</h2>

        {data.length === 0 ? (
          <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-6">
            <p className="text-yellow-700">No data available. Please import data first.</p>
          </div>
        ) : (
          <div className="mb-6">
            <p className="text-gray-600 mb-4">
              Select an analysis model to apply to your {data.length} records of data.
