                  onClick={() => setSelectedAnalysis(option.id)}
                  className={`border rounded-lg p-4 cursor-pointer transition-colors ${selectedAnalysis === option.id ? 'border-goldenrod bg-lightgoldenrodyellow' : 'border-gray-200 hover:border-goldenrod'}`}
                >
                  <div className="flex items-start">
                    <div className="mr-3 mt-1">
                      {option.icon}
                    </div>
                    <div>
                      <h3 className="font-medium text-gray-800">{option.name}</h3>
                      <p className="text-sm text-gray-600">{option.description}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        <button
          onClick={performAnalysis}
          disabled={!selectedAnalysis || data.length === 0 || isAnalyzing}
          className={`w-full py-3 rounded-md text-white font-medium ${!selectedAnalysis || data.length === 0 || isAnalyzing ? 'bg-gray-400 cursor-not-allowed' : 'bg-goldenrod hover:bg-yellow-600'}`}
        >
          {isAnalyzing ? 'Analyzing...' : 'Run Analysis'}
        </button>
      </div>
