import { Bar, Line, Pie } from 'react-chartjs-2'
import { 
  Chart as ChartJS, 
  CategoryScale, 
  LinearScale, 
  BarElement, 
  LineElement, 
  PointElement, 
  ArcElement,
  Title, 
  Tooltip, 
  Legend 
} from 'chart.js'

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
)

interface VisualizationProps {
  results: any
}

export default function Visualization({ results }: VisualizationProps) {
  if (!results) {
    return (
      <div className="max-w-4xl mx-auto py-8">
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-2xl font-bold text-goldenrod mb-4">Data Visualization</h2>
          <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4">
            <p className="text-yellow-700">No analysis results available. Please run an analysis first.</p>
          </div>
        </div>
      </div>
    )
  }

  // Generate mock chart data based on analysis type
  const generateChartData = () => {
    const labels = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul']

    if (results.type === 'descriptive') {
      return {
        labels: ['Mean', 'Median', 'Mode', 'Std Dev'],
        datasets: [
          {
            label: 'Values',
            data: [
              results.insights.mean,
              results.insights.median,
              results.insights.mode,
              results.insights.stdDev
            ],
            backgroundColor: 'rgba(218, 165, 32, 0.6)',
            borderColor: 'rgba(218, 165, 32, 1)',
            borderWidth: 1
          }
        ]
      }
    } else if (results.type === 'frequency') {
      return {
        labels: results.insights.topCategories.map((c: any) => c.category),
        datasets: [
          {
            label: 'Frequency',
            data: results.insights.topCategories.map((c: any) => c.count),
            backgroundColor: [
              'rgba(218, 165, 32, 0.6)',
              'rgba(184, 134, 11, 0.6)',
              'rgba(139, 101, 8, 0.6)'
            ],
            borderColor: [
              'rgba(218, 165, 32, 1)',
              'rgba(184, 134, 11, 1)',
              'rgba(139, 101, 8, 1)'
            ],
            borderWidth: 1
          }
        ]
      }
    } else if (results.type === 'time-series') {
      return {
        labels,
        datasets: [
          {
            label: 'Trend',
            data: labels.map(() => Math.random() * 100),
            borderColor: 'rgba(218, 165, 32, 1)',
            backgroundColor: 'rgba(218, 165, 32, 0.1)',
            tension: 0.3
          }
        ]
      }
    } else if (results.type === 'correlation') {
      return {
        labels: Object.keys(results.insights.correlationMatrix),
        datasets: [
          {
            label: 'Correlation',
            data: Object.values(results.insights.correlationMatrix),
            backgroundColor: 'rgba(218, 165, 32, 0.6)',
            borderColor: 'rgba(218, 165, 32, 1)',
            borderWidth: 1
          }
        ]
      }
    } else {
      // Default case
