import React, { useState, useEffect } from 'react';
import DatasetSelector from './components/DatasetSelector';
import ChartControls from './components/ChartControls';
import DataVisualizer from './components/DataVisualizer';
import StatsPanel from './components/StatsPanel';
import { datasets } from './data/datasets';

function App() {
  const [selectedDataset, setSelectedDataset] = useState('iris');
  const [chartType, setChartType] = useState('line');
  const [filters, setFilters] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [data, setData] = useState([]);

  useEffect(() => {
    setIsLoading(true);
    // Simulate loading data
    setTimeout(() => {
      setData(datasets[selectedDataset]);
      setIsLoading(false);
    }, 500);
  }, [selectedDataset]);

  return (
    <div className="min-h-screen bg-[#FFE5B4] p-4 md:p-8">
      <header className="mb-8">
        <h1 className="text-3xl font-bold text-orange-600">Data Visualization Dashboard</h1>
        <p className="text-orange-800">Explore and analyze datasets with interactive charts</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="lg:col-span-1 space-y-6">
          <DatasetSelector 
            selectedDataset={selectedDataset} 
            setSelectedDataset={setSelectedDataset} 
            isLoading={isLoading}
          />
          <ChartControls 
            chartType={chartType} 
            setChartType={setChartType}
            filters={filters}
            setFilters={setFilters}
          />
        </div>
        <div className="lg:col-span-3 space-y-6">
          <StatsPanel data={data} />
          <DataVisualizer data={data} chartType={chartType} />
        </div>
      </div>
    </div>
  );
}

export default App;
</boltAction>

