const comics = ref([
  // Sample data
  {
    id: 1,
    title: 'Sample Comic 1',
    author: 'Author A',
    cover: 'https://via.placeholder.com/150x200',
    status: 'Ongoing',
    categories: ['action', 'adventure']
  },
  {
    id: 2,
    title: 'Sample Comic 2',
    author: 'Author B',
    cover: 'https://via.placeholder.com/150x200',
    status: 'Completed',
    categories: ['romance']
  }
])

const filteredComics = computed(() => {
  return comics.value.filter(comic => {
    const matchesSearch = comic.title.toLowerCase().includes(searchQuery.value.toLowerCase())
    const matchesCategory = selectedCategory.value === 'all' || 
      comic.categories.includes(selectedCategory.value)
    return matchesSearch && matchesCategory
  })
})
