<boltAction type="file" filePath="src/components/Pagination.vue">
<script setup lang="ts">
import { ref, computed } from 'vue'

const props = defineProps({
  totalItems: {
    type: Number,
    required: true
  },
  itemsPerPage: {
    type: Number,
    default: 10
  }
})

const emit = defineEmits(['page-changed'])

const currentPage = ref(1)
const perPageOptions = [5, 10, 20, 50]
const itemsPerPage = ref(props.itemsPerPage)

const totalPages = computed(() => Math.ceil(props.totalItems / itemsPerPage.value))
const visiblePages = computed(() => {
  const pages = []
  const maxVisible = 5
  let start = Math.max(1, currentPage.value - Math.floor(maxVisible / 2))
  let end = Math.min(totalPages.value, start + maxVisible - 1)

  if (end - start + 1 < maxVisible) {
    start = Math.max(1, end - maxVisible + 1)
  }

  for (let i = start; i <= end; i++) {
    pages.push(i)
  }

  return pages
})

function goToPage(page: number) {
  if (page < 1 || page > totalPages.value || page === currentPage.value) return
  currentPage.value = page
  emit('page-changed', { currentPage: page, itemsPerPage: itemsPerPage.value })
}

function changeItemsPerPage(value: number) {
  itemsPerPage.value = value
  currentPage.value = 1
  emit('page-changed', { currentPage: 1, itemsPerPage: value })
}
</script>

<template>
  <div class="pagination-container">
    <div class="pagination-controls">
      <button 
        @click="goToPage(1)" 
        :disabled="currentPage === 1"
      >
        First
      </button>
      <button 
        @click="goToPage(currentPage - 1)" 
        :disabled="currentPage === 1"
      >
        Previous
      </button>

      <button 
        v-for="page in visiblePages" 
        :key="page"
        @click="goToPage(page)"
        :class="{ active: page === currentPage }"
      >
        {{ page }}
      </button>

      <button 
        @click="goToPage(currentPage + 1)" 
        :disabled="currentPage === totalPages"
      >
        Next
      </button>
      <button 
        @click="goToPage(totalPages)" 
        :disabled="currentPage === totalPages"
      >
        Last
      </button>
    </div>

    <div class="page-info">
      Page {{ currentPage }} of {{ totalPages }}
    </div>

    <div class="per-page-selector">
      <label for="items-per-page">Items per page:</label>
      <select 
        id="items-per-page" 
        v-model="itemsPerPage" 
        @change="changeItemsPerPage(Number($event.target.value))"
      >
        <option v-for="option in perPageOptions" :key="option" :value="option">
          {{ option }}
        </option>
      </select>
    </div>
  </div>
</template>

