import { ref } from 'vue'
import Pagination from './components/Pagination.vue'

const sampleItems = Array.from({ length: 100 }, (_, i) => `Item ${i + 1}`)
const displayedItems = ref<string[]>([])
const currentPage = ref(1)
const itemsPerPage = ref(10)

function handlePageChange({ currentPage: page, itemsPerPage: perPage }: { currentPage: number, itemsPerPage: number }) {
  currentPage.value = page
  itemsPerPage.value = perPage
  updateDisplayedItems()
}

function updateDisplayedItems() {
  const start = (currentPage.value - 1) * itemsPerPage.value
  const end = start + itemsPerPage.value
  displayedItems.value = sampleItems.slice(start, end)
}

updateDisplayedItems()
</script>

