<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  websiteData: {
    type: Object,
    required: true
  }
})

const pages = ref([
  { id: 1, title: 'Home', slug: 'home', content: 'Home page content' },
  { id: 2, title: 'About', slug: 'about', content: 'About page content' },
  { id: 3, title: 'Contact', slug: 'contact', content: 'Contact page content' }
])

const activePage = ref(pages.value[0])
const newPageTitle = ref('')

const addPage = () => {
  if (!newPageTitle.value) return

  const slug = newPageTitle.value.toLowerCase().replace(/\s+/g, '-')
  const newPage = {
    id: Date.now(),
    title: newPageTitle.value,
    slug,
    content: ''
  }

  pages.value.push(newPage)
  newPageTitle.value = ''
}

const updatePageContent = (content: string) => {
  activePage.value.content = content
}
</script>

<template>
  <div class="content-manager">
    <h2>Content Manager</h2>
    <p>Website: {{ websiteData.title }}</p>

    <div class="content-layout">
      <div class="page-list">
        <h3>Pages</h3>
        <ul>
          <li
            v-for="page in pages"
            :key="page.id"
            :class="{ active: activePage.id === page.id }"
            @click="activePage = page"
          >
            {{ page.title }}
          </li>
        </ul>

        <div class="add-page">
          <input v-model="newPageTitle" placeholder="New page title">
          <button @click="addPage">Add Page</button>
        </div>
      </div>

      <div class="page-editor">
        <h3>{{ activePage.title }}</h3>
        <textarea 
          v-model="activePage.content" 
          @input="updatePageContent($event.target.value)"
        ></textarea>
      </div>
    </div>
  </div>
</template>

