export class AppComponent {
  apps: App[] = [
    { id: 1, name: 'Terminal Calculator', version: '1.0.0', category: 'Utilities', 
      description: 'A simple calculator for terminal', downloads: 150, installs: 120, avgUsage: 15, published: true },
    { id: 2, name: 'File Manager', version: '2.1.3', category: 'System', 
      description: 'Manage your files in terminal', downloads: 320, installs: 280, avgUsage: 25, published: true },
    { id: 3, name: 'Text Editor', version: '0.9.5', category: 'Development', 
      description: 'Lightweight terminal text editor', downloads: 210, installs: 180, avgUsage: 45, published: false }
  ];

  categories = ['Utilities', 'System', 'Development', 'Games', 'Network'];
  searchTerm = '';
  selectedCategory = '';

  newApp: Omit<App, 'id' | 'downloads' | 'installs' | 'avgUsage' | 'published'> = {
    name: '',
    version: '',
    category: '',
    description: ''
  };

  get filteredApps(): App[] {
    return this.apps.filter(app => 
      app.name.toLowerCase().includes(this.searchTerm.toLowerCase()) &&
      (this.selectedCategory === '' || app.category === this.selectedCategory)
    );
  }

  addApp() {
    const newId = Math.max(...this.apps.map(a => a.id), 0) + 1;
    this.apps.push({
      ...this.newApp,
      id: newId,
      downloads: 0,
      installs: 0,
      avgUsage: 0,
      published: false
    });
    this.newApp = { name: '', version: '', category: '', description: '' };
  }

  publishApp(id: number) {
    const app = this.apps.find(a => a.id === id);
    if (app) app.published = true;
  }

  updateApp(id: number) {
    const app = this.apps.find(a => a.id === id);
    if (app) {
      const newVersion = prompt('Enter new version:', app.version);
      if (newVersion) app.version = newVersion;
    }
  }

  removeApp(id: number) {
    this.apps = this.apps.filter(a => a.id !== id);
  }
}
