    title: "Welcome to our Wiki",
    content: "<p>This is the home page of our wiki platform.</p>",
    infobox: {
      title: "Quick Facts",
      fields: [
        {label: "Created", value: "Today"},
        {label: "Pages", value: "1"}
      ]
    }
  }
};

export async function getPage(slug: string): Promise<Page | null> {
  return pages[slug] || null;
}

export async function savePage(slug: string, page: Page): Promise<void> {
  pages[slug] = page;
}

export async function searchPages(query: string): Promise<Array<{slug: string, title: string}>> {
  return Object.entries(pages)
    .filter(([_, page]) => 
      page.title.toLowerCase().includes(query.toLowerCase()) ||
      page.content.toLowerCase().includes(query.toLowerCase())
    )
    .map(([slug, page]) => ({slug, title: page.title}));
}
