<script setup lang="ts">
import { ref } from 'vue'

const files = ref<File[]>([])
const isDragging = ref(false)
const selectedFiles = ref<number[]>([])

const handleDragOver = (e: DragEvent) => {
  e.preventDefault()
  isDragging.value = true
}

const handleDragLeave = () => {
  isDragging.value = false
}

const handleDrop = (e: DragEvent) => {
  e.preventDefault()
  isDragging.value = false
  if (e.dataTransfer?.files) {
    addFiles(Array.from(e.dataTransfer.files))
  }
}

const handleFileInput = (e: Event) => {
  const input = e.target as HTMLInputElement
  if (input.files) {
    addFiles(Array.from(input.files))
    input.value = ''
  }
}

const addFiles = (newFiles: File[]) => {
  const validFiles = newFiles.filter(file => file.type.startsWith('image/'))
  files.value = [...files.value, ...validFiles]
}

const removeFile = (index: number) => {
  files.value.splice(index, 1)
  selectedFiles.value = selectedFiles.value.filter(i => i !== index)
}

const toggleSelect = (index: number) => {
  const idx = selectedFiles.value.indexOf(index)
  if (idx === -1) {
    selectedFiles.value.push(index)
  } else {
    selectedFiles.value.splice(idx, 1)
  }
}

const removeSelected = () => {
  files.value = files.value.filter((_, index) => !selectedFiles.value.includes(index))
  selectedFiles.value = []
}
</script>

<template>
  <div class="uploader-container">
    <div 
      class="drop-zone"
      :class="{ 'dragging': isDragging }"
      @dragover="handleDragOver"
      @dragleave="handleDragLeave"
      @drop="handleDrop"
    >
      <div class="drop-content">
        <p>Drag & Drop images here</p>
        <p>or</p>
        <label for="file-input" class="upload-btn">Select Files</label>
        <input 
          id="file-input" 
          type="file" 
          multiple 
          accept="image/*" 
          @change="handleFileInput"
          style="display: none"
        />
      </div>
    </div>

    <div class="preview-container">
      <div v-if="files.length > 0" class="actions">
        <button 
          v-if="selectedFiles.length > 0" 
          @click="removeSelected"
          class="action-btn"
        >
          Delete Selected ({{ selectedFiles.length }})
        </button>
      </div>

      <div class="image-grid">
        <div 
          v-for="(file, index) in files" 
          :key="index" 
          class="image-item"
          :class="{ 'selected': selectedFiles.includes(index) }"
          @click="toggleSelect(index)"
        >
          <img :src="URL.createObjectURL(file)" :alt="file.name" />
          <button @click.stop="removeFile(index)" class="delete-btn">×</button>
          <div class="file-info">{{ file.name }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

