<script setup lang="ts">
import { ref } from 'vue'
import TemplateSelector from './components/TemplateSelector.vue'
import ContentEditor from './components/ContentEditor.vue'
import PagePreview from './components/PagePreview.vue'
import UserManagement from './components/UserManagement.vue'
import TemplateManagement from './components/TemplateManagement.vue'
import HistoryView from './components/HistoryView.vue'

const activeTab = ref('template')
const currentTemplate = ref(null)
const editedContent = ref({})
const generatedPages = ref([])
const users = ref([
  { id: 1, username: 'admin', role: 'admin' },
  { id: 2, username: 'editor', role: 'editor' }
])
const templates = ref([
  { id: 1, name: 'Basic', content: '<div><h1>{{title}}</h1><p>{{content}}</p></div>' },
  { id: 2, name: 'Blog', content: '<div class="blog"><h1>{{title}}</h1><div class="meta">By {{author}}</div><article>{{content}}</article></div>' }
])
const history = ref([])

const selectTemplate = (template) => {
  currentTemplate.value = template
  activeTab.value = 'editor'
}

const updateContent = (content) => {
  editedContent.value = content
}

const generatePage = () => {
  const html = currentTemplate.value.content
    .replace(/{{(\w+)}}/g, (_, key) => editedContent.value[key] || '')
  generatedPages.value.push({
    id: Date.now(),
    templateId: currentTemplate.value.id,
    content: editedContent.value,
    html,
    timestamp: new Date()
  })
  history.value.push({
    action: 'generate',
    pageId: Date.now(),
    timestamp: new Date()
  })
  activeTab.value = 'preview'
}

const addTemplate = (template) => {
  templates.value.push(template)
}

const addUser = (user) => {
  users.value.push(user)
}
</script>

<template>
  <div class="app-container">
    <nav>
      <button @click="activeTab = 'template'" :class="{ active: activeTab === 'template' }">Templates</button>
      <button @click="activeTab = 'editor'" :class="{ active: activeTab === 'editor' }">Editor</button>
      <button @click="activeTab = 'preview'" :class="{ active: activeTab === 'preview' }">Preview</button>
      <button @click="activeTab = 'users'" :class="{ active: activeTab === 'users' }">Users</button>
      <button @click="activeTab = 'manage-templates'" :class="{ active: activeTab === 'manage-templates' }">Manage Templates</button>
      <button @click="activeTab = 'history'" :class="{ active: activeTab === 'history' }">History</button>
    </nav>

