<script setup lang="ts">
import { ref, watch } from 'vue'

const props = defineProps<{
  template: {
    id: number
    name: string
    content: string
  }
}>()

const emit = defineEmits(['update', 'generate'])

const contentFields = ref({})
const extractedFields = ref([])

watch(() => props.template, (newTemplate) => {
  const fields = new Set()
  const regex = /{{(\w+)}}/g
  let match
  while ((match = regex.exec(newTemplate.content)) !== null) {
    fields.add(match[1])
  }
  extractedFields.value = Array.from(fields)
  contentFields.value = extractedFields.value.reduce((acc, field) => {
    acc[field] = ''
    return acc
  }, {})
}, { immediate: true })

const updateField = (field, value) => {
  contentFields.value[field] = value
  emit('update', contentFields.value)
}
</script>

<template>
  <div class="content-editor">
    <h2>Editing: {{ template.name }}</h2>

    <div class="form-group" v-for="field in extractedFields" :key="field">
      <label :for="field">{{ field }}</label>
      <input
        type="text"
        :id="field"
        v-model="contentFields[field]"
        @input="updateField(field, $event.target.value)"
      />
    </div>

    <button @click="emit('generate')" class="generate-btn">Generate Page</button>
  </div>
</template>

