import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

interface User {
  id: number;
  username: string;
  roles: string[];
}

@Component({
  selector: 'app-user-management',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="user-management">
      <h2>User Management</h2>
      <table>
        <thead>
          <tr>
            <th>Username</th>
            <th>Roles</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let user of users">
            <td>{{user.username}}</td>
            <td>{{user.roles.join(', ')}}</td>
            <td>
              <button (click)="editUser(user)">Edit</button>
              <button (click)="deleteUser(user.id)">Delete</button>
            </td>
          </tr>
        </tbody>
      </table>
      <div *ngIf="editingUser" class="edit-form">
        <h3>Edit User</h3>
        <form (ngSubmit)="saveUser()">
          <div>
            <label>Username:</label>
            <input type="text" [(ngModel)]="editingUser.username" name="username" required>
          </div>
          <div>
            <label>Roles:</label>
            <div *ngFor="let role of availableRoles">
              <input type="checkbox" 
                     [id]="role" 
                     [value]="role" 
                     [checked]="editingUser.roles.includes(role)"
                     (change)="toggleRole(role)">
              <label [for]="role">{{role}}</label>
            </div>
          </div>
          <button type="submit">Save</button>
          <button type="button" (click)="cancelEdit()">Cancel</button>
        </form>
      </div>
    </div>
  `,
  styles: [`
    .user-management {
      background-color: white;
      padding: 20px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
    }
    th, td {
      padding: 8px;
      text-align: left;
      border-bottom: 1px solid #ddd;
    }
    .edit-form {
      margin-top: 20px;
      padding: 20px;
      background-color: #f5f5f5;
    }
  `]
})
export class UserManagementComponent {
  users: User[] = [
    { id: 1, username: 'admin', roles: ['admin'] },
    { id: 2, username: 'editor', roles: ['editor'] },
    { id: 3, username: 'viewer', roles: ['viewer'] }
  ];
  availableRoles = ['admin', 'editor', 'viewer'];
  editingUser: User | null = null;

  editUser(user: User): void {
    this.editingUser = { ...user };
  }

  deleteUser(id: number): void {
    this.users = this.users.filter(user => user.id !== id);
  }

  toggleRole(role: string): void {
    if (!this.editingUser) return;

    const index = this.editingUser.roles.indexOf(role);
    if (index === -1) {
      this.editingUser.roles.push(role);
    } else {
      this.editingUser.roles.splice(index, 1);
    }
  }

  saveUser(): void {
    if (!this.editingUser) return;

    const index = this.users.findIndex(u => u.id === this.editingUser!.id);
    if (index !== -1) {
      this.users[index] = this.editingUser;
    }
    this.cancelEdit();
  }

  cancelEdit(): void {
    this.editingUser = null;
  }
}
</boltAction>

