  return resources.filter(resource => 
    resource.title.toLowerCase().includes(props.searchQuery.toLowerCase()) ||
    resource.description.toLowerCase().includes(props.searchQuery.toLowerCase()) ||
    resource.tags.some(tag => tag.toLowerCase().includes(props.searchQuery.toLowerCase()))
  )
})
</script>

<template>
  <div class="gallery">
    <div v-if="filteredResources.length === 0">
      No resources found
    </div>
    <ResourceCard 
      v-for="resource in filteredResources"
      :key="resource.id"
      :resource="resource"
      :current-user="user"
    />
  </div>
</template>

<style>
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
  margin-top: 20px;
}
</style>
