<script setup lang="ts">
import { ref } from 'vue'
import NavBar from './components/NavBar.vue'
import CourseBrowser from './components/CourseBrowser.vue'
import AuthModal from './components/AuthModal.vue'
import VideoPlayer from './components/VideoPlayer.vue'

const showAuthModal = ref(false)
const currentVideo = ref(null)
const isAuthenticated = ref(false)
const userSubscriptions = ref([])

const courses = ref([
  {
    id: 1,
    title: 'Landscape Photography Masterclass',
    instructor: 'Jane Smith',
    thumbnail: '/placeholder-landscape.jpg',
    duration: '4h 30m',
    level: 'Intermediate',
    price: 49.99,
    subscribed: false
  },
  {
    id: 2,
    title: 'Portrait Lighting Techniques',
    instructor: 'Mike Johnson',
    thumbnail: '/placeholder-portrait.jpg',
    duration: '3h 15m',
    level: 'Beginner',
    price: 39.99,
    subscribed: false
  }
])

const toggleAuthModal = () => {
  showAuthModal.value = !showAuthModal.value
}

const handleLogin = () => {
  isAuthenticated.value = true
  showAuthModal.value = false
}

const handleSubscribe = (courseId: number) => {
  const course = courses.value.find(c => c.id === courseId)
  if (course) {
    course.subscribed = true
    userSubscriptions.value.push(course)
  }
}

const playVideo = (courseId: number) => {
  const course = courses.value.find(c => c.id === courseId)
  if (course && course.subscribed) {
    currentVideo.value = course
  }
}
</script>

<template>
  <div class="app-container">
    <NavBar 
      :is-authenticated="isAuthenticated" 
      @toggle-auth="toggleAuthModal"
    />

    <main class="main-content">
      <CourseBrowser 
        :courses="courses" 
        :is-authenticated="isAuthenticated"
        @subscribe="handleSubscribe"
        @play="playVideo"
      />
    </main>

    <AuthModal 
      v-if="showAuthModal" 
      @close="toggleAuthModal"
      @login="handleLogin"
    />

    <VideoPlayer 
      v-if="currentVideo" 
      :course="currentVideo"
      @close="currentVideo = null"
    />
  </div>
</template>

