const courses = ref([
  { id: 1, title: 'Stock Market Basics', type: 'video', duration: '2h 30m', progress: 25 },
  { id: 2, title: 'Personal Finance 101', type: 'text', duration: '45m', progress: 100 },
  { id: 3, title: 'Real Estate Investing', type: 'audio', duration: '1h 15m', progress: 0 },
  { id: 4, title: 'Cryptocurrency Fundamentals', type: 'video', duration: '3h', progress: 50 },
  { id: 5, title: 'Retirement Planning', type: 'text', duration: '1h', progress: 0 },
  { id: 6, title: 'Technical Analysis', type: 'video', duration: '4h', progress: 75 }
])

const filter = ref('all')

const filteredCourses = computed(() => {
  if (filter.value === 'all') return courses.value
  return courses.value.filter(course => {
    if (filter.value === 'completed') return course.progress === 100
    if (filter.value === 'in-progress') return course.progress > 0 && course.progress < 100
    if (filter.value === 'not-started') return course.progress === 0
    return true
  })
})
</script>

