<script setup lang="ts">
defineProps<{
  teacher: {
    id: number
    name: string
    specialty: string
    rating: number
    courses?: number
  }
  showCourses?: boolean
}>()

const getRatingStars = (rating: number) => {
  const fullStars = Math.floor(rating)
  const hasHalfStar = rating % 1 >= 0.5
  const emptyStars = 5 - fullStars - (hasHalfStar ? 1 : 0)

  return {
    fullStars,
    hasHalfStar,
    emptyStars
  }
}
