<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps(['course'])
const emit = defineEmits(['navigate'])

const currentQuestion = ref(0)
const score = ref(0)
const examCompleted = ref(false)

const questions = ref([
  {
    question: 'What is the first rule of industrial safety?',
    options: ['Wear PPE', 'Hurry up', 'Ignore warnings', 'Work alone'],
    answer: 0
  },
  {
    question: 'What should you do before operating machinery?',
    options: ['Read manual', 'Ask a friend', 'Guess', 'Just start'],
    answer: 0
  }
])

function answerQuestion(selected: number) {
  if (selected === questions.value[currentQuestion.value].answer) {
    score.value++
  }

  if (currentQuestion.value < questions.value.length - 1) {
    currentQuestion.value++
  } else {
    examCompleted.value = true
  }
}
</script>

<template>
  <div>
    <h2>{{ course.title }} Exam</h2>
    <div v-if="!examCompleted" class="question-card card">
      <h3>Question {{ currentQuestion + 1 }} of {{ questions.length }}</h3>
      <p>{{ questions[currentQuestion].question }}</p>
      <div v-for="(option, index) in questions[currentQuestion].options" :key="index">
        <button @click="answerQuestion(index)">{{ option }}</button>
      </div>
    </div>
    <div v-if="examCompleted" class="results-card card">
      <h3>Exam Completed!</h3>
      <p>Your score: {{ score }}/{{ questions.length }}</p>
      <button @click="emit('navigate', 'certificate')">Get Certificate</button>
    </div>
    <button @click="emit('navigate', 'learning')">Back to Learning</button>
  </div>
</template>
</boltAction>

