<script setup lang="ts">
import { ref, onMounted } from 'vue'

const emit = defineEmits(['submit-recording', 'cancel'])

const practiceQuestions = [
  "Describe your favorite holiday destination",
  "Talk about your daily routine",
  "Explain your favorite book or movie",
  "Discuss your future goals"
]

const selectedQuestion = ref('')
const isRecording = ref(false)
const mediaRecorder = ref(null)
const audioChunks = ref([])
const audioUrl = ref('')

const startRecording = async () => {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
    mediaRecorder.value = new MediaRecorder(stream)
    audioChunks.value = []

    mediaRecorder.value.ondataavailable = (e) => {
      audioChunks.value.push(e.data)
    }

    mediaRecorder.value.onstop = () => {
      const audioBlob = new Blob(audioChunks.value)
      audioUrl.value = URL.createObjectURL(audioBlob)
    }

    mediaRecorder.value.start()
    isRecording.value = true
  } catch (err) {
    console.error('Error accessing microphone:', err)
  }
}

const stopRecording = () => {
  if (mediaRecorder.value) {
    mediaRecorder.value.stop()
    mediaRecorder.value.stream.getTracks().forEach(track => track.stop())
    isRecording.value = false
  }
}

const submitRecording = () => {
  // In a real app, this would send to backend for analysis
  const mockResults = {
    pronunciation: 82,
    fluency: 75,
    intonation: 88,
    feedback: [
      "Good overall pronunciation",
      "Work on ending consonants",
      "Improve sentence rhythm"
    ]
  }
  emit('submit-recording', mockResults)
}
</script>

<template>
