    <h2>Practice Session</h2>
    <div class="question-selector">
      <label>Select a practice question:</label>
      <select v-model="selectedQuestion">
        <option v-for="(question, index) in practiceQuestions" :key="index" :value="question">
          {{ question }}
        </option>
      </select>
    </div>

    <div v-if="selectedQuestion" class="question-display">
      <h3>{{ selectedQuestion }}</h3>
      <div class="recording-controls">
        <button 
          @click="isRecording ? stopRecording() : startRecording()"
          :style="{backgroundColor: isRecording ? '#ff4444' : 'var(--component-color)'}"
        >
          {{ isRecording ? 'Stop Recording' : 'Start Recording' }}
        </button>
      </div>

      <audio v-if="audioUrl" controls :src="audioUrl"></audio>

      <div class="action-buttons">
        <button @click="emit('cancel')">Cancel</button>
        <button @click="submitRecording" :disabled="!audioUrl">Submit for Assessment</button>
      </div>
