import { ref } from 'vue'
import LoginPage from './components/LoginPage.vue'
import CourseList from './components/CourseList.vue'
import ExamPage from './components/ExamPage.vue'
import AdminPanel from './components/AdminPanel.vue'

const currentUser = ref(null)
const currentView = ref('login')
const selectedCourse = ref(null)
const examResults = ref([])

const courses = ref([
  {
    id: 1,
    title: 'Introduction to Programming',
    description: 'Learn basic programming concepts',
    content: 'This course covers variables, loops, and functions...',
    questions: [
      {
        id: 1,
        text: 'What is a variable?',
        options: ['A data type', 'A storage location', 'A function', 'A loop'],
        answer: 1
      },
      {
        id: 2,
        text: 'Which keyword declares a variable?',
        options: ['var', 'let', 'const', 'All of the above'],
        answer: 3
      }
    ]
  },
  {
    id: 2,
    title: 'Web Development Basics',
    description: 'Learn HTML, CSS and JavaScript',
    content: 'This course covers web development fundamentals...',
    questions: [
      {
        id: 1,
        text: 'What does HTML stand for?',
        options: [
          'Hyper Text Markup Language',
          'Home Tool Markup Language',
          'Hyperlinks and Text Markup Language',
          'None of the above'
        ],
        answer: 0
      }
    ]
  }
])

const login = (username, password) => {
  currentUser.value = { username, isAdmin: username === 'admin' }
  currentView.value = currentUser.value.isAdmin ? 'admin' : 'courses'
}

const logout = () => {
  currentUser.value = null
  currentView.value = 'login'
}

const startExam = (course) => {
  selectedCourse.value = course
  currentView.value = 'exam'
}

const submitExam = (answers) => {
  const course = selectedCourse.value
  let score = 0

  answers.forEach((answer, index) => {
    if (answer === course.questions[index].answer) {
      score++
    }
  })

  const result = {
    courseId: course.id,
    courseTitle: course.title,
    score,
    total: course.questions.length,
    date: new Date().toLocaleDateString()
  }

  examResults.value.push(result)
  currentView.value = 'courses'
}

const addCourse = (course) => {
  courses.value.push(course)
}

const addQuestion = (courseId, question) => {
  const course = courses.value.find(c => c.id === courseId)
  if (course) {
    question.id = course.questions.length + 1
    course.questions.push(question)
  }
}
</script>

