<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  course: Object
})

const emit = defineEmits(['submitExam'])

const answers = ref([])
const currentQuestion = ref(0)

const selectAnswer = (index) => {
  answers.value[currentQuestion.value] = index
}

const nextQuestion = () => {
  if (currentQuestion.value < props.course.questions.length - 1) {
    currentQuestion.value++
  }
}

const prevQuestion = () => {
  if (currentQuestion.value > 0) {
    currentQuestion.value--
  }
}

const submit = () => {
  emit('submitExam', answers.value)
}
</script>

<template>
  <div class="exam-container">
    <h2>{{ course.title }} Exam</h2>

    <div class="question-container">
      <div class="question">
        <h3>Question {{ currentQuestion + 1 }} of {{ course.questions.length }}</h3>
        <p>{{ course.questions[currentQuestion].text }}</p>

        <div class="options">
          <div 
            v-for="(option, index) in course.questions[currentQuestion].options" 
            :key="index"
            class="option"
            :class="{ selected: answers[currentQuestion] === index }"
            @click="selectAnswer(index)"
          >
            {{ String.fromCharCode(65 + index) }}) {{ option }}
          </div>
        </div>
      </div>

      <div class="navigation">
        <button @click="prevQuestion" :disabled="currentQuestion === 0">Previous</button>
        <button 
          @click="nextQuestion" 
          :disabled="currentQuestion === course.questions.length - 1"
        >
          Next
        </button>
        <button 
          v-if="currentQuestion === course.questions.length - 1"
          @click="submit"
        >
          Submit Exam
        </button>
      </div>
    </div>
  </div>
</template>

