<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  courses: Array
})

const emit = defineEmits(['addCourse', 'addQuestion'])

const newCourse = ref({
  title: '',
  description: '',
  content: ''
})

const newQuestion = ref({
  courseId: null,
  text: '',
  options: ['', '', '', ''],
  answer: null
})

const addNewCourse = () => {
  const course = {
    ...newCourse.value,
    id: props.courses.length + 1,
    questions: []
  }
  emit('addCourse', course)
  newCourse.value = { title: '', description: '', content: '' }
}

const addNewQuestion = () => {
  const question = {
    text: newQuestion.value.text,
    options: newQuestion.value.options,
    answer: newQuestion.value.answer
  }
  emit('addQuestion', newQuestion.value.courseId, question)
  newQuestion.value = {
    courseId: null,
    text: '',
    options: ['', '', '', ''],
    answer: null
  }
}
</script>

