<script setup lang="ts">
import { ref } from 'vue'

const messages = ref([
  { id: 1, sender: 'bot', text: 'Hello! How can I help with your family education today?' }
])
const newMessage = ref('')

const sendMessage = () => {
  if (!newMessage.value.trim()) return

  messages.value.push({
    id: Date.now(),
    sender: 'user',
    text: newMessage.value
  })

  // Simulate bot response
  setTimeout(() => {
    messages.value.push({
      id: Date.now() + 1,
      sender: 'bot',
      text: 'That sounds interesting! Here are some suggestions...'
    })
  }, 1000)

  newMessage.value = ''
}
</script>

<template>
  <div class="gpt-conversation">
    <div class="messages">
      <div 
        v-for="message in messages" 
        :key="message.id" 
        :class="['message', message.sender]"
      >
        {{ message.text }}
