<script setup lang="ts">
import { ref } from 'vue';

const htmlContent = ref('');
const cssContent = ref('');
const unusedSelectors = ref<string[]>([]);
const analysisComplete = ref(false);

const handleHtmlUpload = (event: Event) => {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    htmlContent.value = e.target?.result as string;
  };
  reader.readAsText(file);
};

const handleCssUpload = (event: Event) => {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    cssContent.value = e.target?.result as string;
  };
  reader.readAsText(file);
};

const analyzeCSS = () => {
  if (!htmlContent.value || !cssContent.value) return;

  // Create a temporary DOM to parse HTML
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlContent.value, 'text/html');

  // Extract all CSS selectors
  const cssRules = extractCssRules(cssContent.value);
  const unused: string[] = [];

  // Check each selector against the DOM
  cssRules.forEach(rule => {
    if (!isSelectorUsed(rule.selector, doc)) {
      unused.push(rule.selector);
    }
  });

  unusedSelectors.value = unused;
  analysisComplete.value = true;
};

const extractCssRules = (css: string) => {
  const styleEl = document.createElement('style');
  styleEl.textContent = css;
  document.head.appendChild(styleEl);

  const rules = Array.from(styleEl.sheet?.cssRules || [])
    .map(rule => ({
      selector: (rule as CSSStyleRule).selectorText,
      cssText: (rule as CSSStyleRule).cssText
    }));

  document.head.removeChild(styleEl);
  return rules;
};

const isSelectorUsed = (selector: string, doc: Document) => {
  try {
    return !!doc.querySelector(selector);
  } catch (e) {
    // Skip invalid selectors
    return false;
  }
};

const downloadOptimizedCss = () => {
  const optimizedCss = cssContent.value
    .split('\n')
    .filter(line => {
      return !unusedSelectors.value.some(selector => 
        line.includes(selector)
      );
    })
    .join('\n');

  const blob = new Blob([optimizedCss], { type: 'text/css' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'optimized.css';
  a.click();
  URL.revokeObjectURL(url);
};
</script>

<template>
  <div class="analyzer-container">
    <div class="upload-section">
      <div class="upload-box">
        <h2>Upload HTML File</h2>
        <input type="file" accept=".html,.htm" @change="handleHtmlUpload" />
      </div>

      <div class="upload-box">
        <h2>Upload CSS File</h2>
        <input type="file" accept=".css" @change="handleCssUpload" />
      </div>
    </div>

    <button 
      class="analyze-btn" 
      @click="analyzeCSS"
      :disabled="!htmlContent || !cssContent"
    >
      Analyze CSS
    </button>

    <div v-if="analysisComplete" class="results-section">
      <h2>Unused CSS Selectors</h2>
      <div v-if="unusedSelectors.length" class="unused-list">
        <div v-for="(selector, index) in unusedSelectors" :key="index" class="selector-item">
          {{ selector }}
        </div>
      </div>
      <div v-else class="no-unused">
        No unused selectors found!
      </div>

      <button 
        v-if="unusedSelectors.length" 
        class="download-btn"
        @click="downloadOptimizedCss"
      >
        Download Optimized CSS
      </button>
    </div>
  </div>
</template>

