<script setup lang="ts">
import { ref } from 'vue'

type ConversionType = 'pinyin' | 'segmentation' | 'simplified' | 'traditional'
type HistoryItem = {
  input: string
  output: string
  type: ConversionType
  timestamp: number
}

const inputText = ref('')
const outputText = ref('')
const conversionType = ref<ConversionType>('pinyin')
const history = ref<HistoryItem[]>(JSON.parse(localStorage.getItem('conversionHistory') || '[]'))

// Mock conversion functions (in a real app, these would use actual libraries)
const convertToPinyin = (text: string) => text.split('').map(c => `pīn_${c}`).join(' ')
const segmentPinyin = (text: string) => text.split('').map(c => `seg_${c}`).join(' | ')
const toSimplified = (text: string) => `简_${text}`
const toTraditional = (text: string) => `繁_${text}`

const convertText = () => {
  let result = ''
  switch (conversionType.value) {
    case 'pinyin': result = convertToPinyin(inputText.value); break
    case 'segmentation': result = segmentPinyin(inputText.value); break
    case 'simplified': result = toSimplified(inputText.value); break
    case 'traditional': result = toTraditional(inputText.value); break
  }

  outputText.value = result

  // Add to history
  const newItem: HistoryItem = {
    input: inputText.value,
    output: result,
    type: conversionType.value,
    timestamp: Date.now()
  }

  history.value.unshift(newItem)
  localStorage.setItem('conversionHistory', JSON.stringify(history.value))
}

const clearHistory = () => {
  history.value = []
  localStorage.removeItem('conversionHistory')
}
</script>

