import React, { useState, useRef } from 'react'
import { Upload, Loader2, X } from 'lucide-react'

interface ImageUploaderProps {
  onImageUpload: (file: File) => void
  isLoading: boolean
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ onImageUpload, isLoading }) => {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      const reader = new FileReader()
      reader.onload = () => {
        setPreviewUrl(reader.result as string)
        onImageUpload(file)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    const file = e.dataTransfer.files?.[0]
    if (file && (file.type === 'image/jpeg' || file.type === 'image/png')) {
      const reader = new FileReader()
      reader.onload = () => {
        setPreviewUrl(reader.result as string)
        onImageUpload(file)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault()
  }

  const clearImage = () => {
    setPreviewUrl(null)
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
  }

  return (
    <div 
      className="w-full max-w-2xl mx-auto"
      onDrop={handleDrop}
      onDragOver={handleDragOver}
    >
      <div className={`border-2 border-dashed border-steelblue-500 rounded-lg p-8 text-center transition-all ${previewUrl ? 'bg-moonstone-100' : 'bg-moonstone-50'}`}>
        {previewUrl ? (
          <div className="relative">
            <img 
              src={previewUrl} 
              alt="Preview" 
              className="max-h-80 mx-auto rounded-lg shadow-md"
            />
            <button
              onClick={clearImage}
              className="absolute top-2 right-2 bg-steelblue-600 text-white p-1 rounded-full hover:bg-steelblue-700 transition-colors"
            >
              <X size={20} />
            </button>
          </div>
        ) : (
          <>
            <div className="flex flex-col items-center justify-center space-y-4">
              {isLoading ? (
                <Loader2 className="animate-spin text-steelblue-600" size={48} />
              ) : (
                <>
                  <Upload className="text-steelblue-600" size={48} />
                  <p className="text-steelblue-800 font-medium">Drag & drop your image here</p>
                  <p className="text-steelblue-600 text-sm">or</p>
                  <label className="px-4 py-2 bg-steelblue-600 text-white rounded-md hover:bg-steelblue-700 cursor-pointer transition-colors">
                    Select Image
                    <input
                      type="file"
                      ref={fileInputRef}
                      onChange={handleFileChange}
                      accept="image/jpeg, image/png"
                      className="hidden"
                    />
                  </label>
                  <p className="text-steelblue-500 text-xs">Supports JPG and PNG formats</p>
                </>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

export default ImageUploader
</boltAction>

