import React, { useState, useEffect } from 'react'
import ImageUploader from './components/ImageUploader'
import ImagePreview from './components/ImagePreview'
import HistoryPanel from './components/HistoryPanel'
import { ImagePlus, History } from 'lucide-react'

const App: React.FC = () => {
  const [originalImage, setOriginalImage] = useState<string | null>(null)
  const [processedImage, setProcessedImage] = useState<string | null>(null)
  const [isProcessing, setIsProcessing] = useState(false)
  const [showHistory, setShowHistory] = useState(false)
  const [history, setHistory] = useState<Array<{
    id: string
    thumbnail: string
    date: string
    original: string
    processed: string
  }>>([])

  // Mock background removal function (in a real app, this would call an API)
  const removeBackground = (imageUrl: string): Promise<string> => {
    return new Promise((resolve) => {
      setTimeout(() => {
        // In a real implementation, this would be the processed image URL
        resolve(imageUrl)
      }, 1500)
    })
  }

  const handleImageUpload = async (file: File) => {
    const imageUrl = URL.createObjectURL(file)
    setOriginalImage(imageUrl)
    setIsProcessing(true)

    try {
      const processedUrl = await removeBackground(imageUrl)
      setProcessedImage(processedUrl)

      // Add to history
      const newItem = {
        id: Date.now().toString(),
        thumbnail: imageUrl,
        date: new Date().toLocaleDateString(),
        original: imageUrl,
        processed: processedUrl
      }
      setHistory(prev => [newItem, ...prev.slice(0, 9)])
    } catch (error) {
      console.error('Error processing image:', error)
    } finally {
      setIsProcessing(false)
    }
  }

  const handleProcessAgain = () => {
    setOriginalImage(null)
    setProcessedImage(null)
  }

  const handleDownload = () => {
    if (!processedImage) return

    const link = document.createElement('a')
    link.href = processedImage
    link.download = `background-removed-${Date.now()}.png`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }

  const handleSelectHistoryItem = (id: string) => {
    const item = history.find(item => item.id === id)
    if (item) {
      setOriginalImage(item.original)
      setProcessedImage(item.processed)
      setShowHistory(false)
    }
  }

  const handleDeleteHistoryItem = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id))
  }

  return (
    <div className="min-h-screen bg-moonstone-50">
      <div className="container mx-auto px-4 py-8">
        <header className="flex justify-between items-center mb-8">
          <h1 className="text-2xl font-bold text-steelblue-800 flex items-center">
            <ImagePlus className="mr-2" />
            Background Remover
          </h1>
          <button
            onClick={() => setShowHistory(!showHistory)}
            className="flex items-center px-4 py-2 bg-steelblue-600 text-white rounded-md hover:bg-steelblue-700 transition-colors"
          >
            <History className="mr-2" size={18} />
            {showHistory ? 'Hide History' : 'Show History'}
          </button>
        </header>

        <main className="space-y-8">
          {showHistory ? (
            <HistoryPanel
              historyItems={history}
              onSelectItem={handleSelectHistoryItem}
              onDeleteItem={handleDeleteHistoryItem}
            />
          ) : processedImage && originalImage ? (
            <ImagePreview
              originalUrl={originalImage}
              processedUrl={processedImage}
              onProcessAgain={handleProcessAgain}
              onDownload={handleDownload}
            />
          ) : (
            <ImageUploader
              onImageUpload={handleImageUpload}
              isLoading={isProcessing}
            />
          )}
        </main>
      </div>
    </div>
  )
}

export default App
