export function detectBorders(imageData: ImageData, threshold: number): ImageData {
  // Simple edge detection algorithm
  const { data, width, height } = imageData
  const newData = new Uint8ClampedArray(data.length)

  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      const i = (y * width + x) * 4

      // Simple Sobel operator
      const gx = -data[i - 4] + data[i + 4] - 2 * data[i - 4 + width * 4] + 
                 2 * data[i + 4 + width * 4] - data[i - 4 + width * 8] + data[i + 4 + width * 8]

      const gy = -data[i - 4] - 2 * data[i] - data[i + 4] + data[i - 4 + width * 8] + 
                 2 * data[i + width * 8] + data[i + 4 + width * 8]

      const magnitude = Math.sqrt(gx * gx + gy * gy)

      if (magnitude > threshold) {
        newData[i] = 255
        newData[i + 1] = 255
        newData[i + 2] = 255
        newData[i + 3] = 255
      } else {
        newData[i] = data[i]
        newData[i + 1] = data[i + 1]
        newData[i + 2] = data[i + 2]
        newData[i + 3] = data[i + 3]
      }
    }
  }

  return new ImageData(newData, width, height)
}

export function removeArtifacts(imageData: ImageData, maxSize: number): ImageData {
  // Simple median filter for artifact removal
  const { data, width, height } = imageData
  const newData = new Uint8ClampedArray(data.length)

  const radius = Math.floor(maxSize / 2)

  for (let y = radius; y < height - radius; y++) {
    for (let x = radius; x < width - radius; x++) {
      const i = (y * width + x) * 4

      const rValues = []
      const gValues = []
      const bValues = []

      for (let dy = -radius; dy <= radius; dy++) {
        for (let dx = -radius; dx <= radius; dx++) {
          const di = ((y + dy) * width + (x + dx)) * 4
          rValues.push(data[di])
          gValues.push(data[di + 1])
          bValues.push(data[di + 2])
        }
      }

      // Sort and take median
      rValues.sort((a, b) => a - b)
      gValues.sort((a, b) => a - b)
      bValues.sort((a, b) => a - b)

      const medianIndex = Math.floor(rValues.length / 2)

      newData[i] = rValues[medianIndex]
      newData[i + 1] = gValues[medianIndex]
      newData[i + 2] = bValues[medianIndex]
      newData[i + 3] = data[i + 3]
    }
  }

  return new ImageData(newData, width, height)
}
