<script setup lang="ts">
import { ref } from 'vue'

const formFields = ref<Array<{
  id: string
  label: string
  type: string
  options?: string[]
  required: boolean
}>>([])

const formData = ref<Record<string, any>>({})

const fieldTypes = [
  { value: 'text', label: 'Text' },
  { value: 'number', label: 'Number' },
  { value: 'select', label: 'Dropdown' },
  { value: 'checkbox', label: 'Checkbox' },
  { value: 'date', label: 'Date' }
]

const emit = defineEmits(['form-submitted'])

const addField = () => {
  const fieldId = `field-${Date.now()}`
  formFields.value.push({
    id: fieldId,
    label: 'New Field',
    type: 'text',
    required: false
  })
  formData.value[fieldId] = ''
}

const removeField = (index: number) => {
  const field = formFields.value[index]
  delete formData.value[field.id]
  formFields.value.splice(index, 1)
}

const updateFieldOptions = (index: number, optionsString: string) => {
  formFields.value[index].options = optionsString.split(',').map(opt => opt.trim())
}

const submitForm = () => {
  const submission: Record<string, any> = {}

  formFields.value.forEach(field => {
    submission[field.label] = formData.value[field.id]
  })

  emit('form-submitted', submission)
  formData.value = {}
}
</script>

