import { defineStore } from 'pinia'
import { ref } from 'vue'

interface Citation {
  author: string
  title: string
  year: string
  publisher: string
}

interface CitationStyle {
  name: string
  format: string
}

export const useCitationStore = defineStore('citations', () => {
  const citations = ref<Citation[]>([])
  const styles = ref<CitationStyle[]>([
    { 
      name: 'APA', 
      format: '{author} ({year}). {title}. {publisher}.' 
    },
    { 
      name: 'MLA', 
      format: '{author}. "{title}." {publisher}, {year}.' 
    }
  ])
  const activeStyleIndex = ref(0)

  function addCitation(citation: Citation) {
    citations.value.push(citation)
  }

  function removeCitation(index: number) {
    citations.value.splice(index, 1)
  }

  function addStyle(style: CitationStyle) {
    styles.value.push(style)
    activeStyleIndex.value = styles.value.length - 1
  }

  function removeStyle(index: number) {
    styles.value.splice(index, 1)
    if (activeStyleIndex.value >= index) {
      activeStyleIndex.value = Math.max(0, activeStyleIndex.value - 1)
    }
  }

  function setActiveStyle(index: number) {
    activeStyleIndex.value = index
  }

  function formatCitation(citation: Citation): string {
    const style = styles.value[activeStyleIndex.value]
    if (!style) return ''

    return style.format
      .replace('{author}', citation.author || 'Unknown author')
      .replace('{year}', citation.year || 'n.d.')
      .replace('{title}', citation.title || 'Untitled')
      .replace('{publisher}', citation.publisher || 'Unknown publisher')
  }

  return {
    citations,
    styles,
    activeStyleIndex,
    addCitation,
    removeCitation,
    addStyle,
    removeStyle,
    setActiveStyle,
    formatCitation
  }
})
