import { ref, onMounted } from 'vue'
import WordCloud from './components/WordCloud.vue'
import UploadArea from './components/UploadArea.vue'
import ControlsPanel from './components/ControlsPanel.vue'

const text = ref('')
const words = ref([])
const cloudSettings = ref({
  fontFamily: 'Arial',
  colorScheme: 'maroon',
  width: 800,
  height: 600,
  padding: 5,
  rotation: 0,
  spiral: 'archimedean'
})

function processText(inputText) {
  text.value = inputText
  // Simple word processing - in a real app you'd want more sophisticated processing
  const wordArray = inputText.toLowerCase().match(/\b(\w+)\b/g) || []
  const wordCounts = {}

  wordArray.forEach(word => {
    if (word.length > 2) { // Ignore very short words
      wordCounts[word] = (wordCounts[word] || 0) + 1
    }
  })

  words.value = Object.keys(wordCounts).map(word => ({
    text: word,
    size: 10 + wordCounts[word] * 5
  }))
}

function downloadImage() {
  const node = document.getElementById('word-cloud-container')
  htmlToImage.toPng(node)
    .then(dataUrl => {
      const link = document.createElement('a')
      link.download = 'word-cloud.png'
      link.href = dataUrl
      link.click()
    })
}
</script>

