<boltAction type="file" filePath="src/components/WordCloud.vue"><script setup>
import { ref, onMounted, watch } from 'vue'
import * as d3 from 'd3'
import cloud from 'd3-cloud'

const props = defineProps({
  words: Array,
  settings: Object
})

const svgRef = ref(null)

function drawWordCloud() {
  if (!props.words.length) return

  const layout = cloud()
    .size([props.settings.width, props.settings.height])
    .words(props.words)
    .padding(props.settings.padding)
    .rotate(() => props.settings.rotation)
    .font(props.settings.fontFamily)
    .fontSize(d => d.size)
    .spiral(props.settings.spiral)
    .on('end', draw)

  layout.start()

  function draw(words) {
    d3.select(svgRef.value)
      .attr('width', props.settings.width)
      .attr('height', props.settings.height)
      .html('')
      .append('g')
      .attr('transform', `translate(${props.settings.width/2},${props.settings.height/2})`)
      .selectAll('text')
      .data(words)
      .enter()
      .append('text')
      .style('font-size', d => `${d.size}px`)
      .style('font-family', props.settings.fontFamily)
      .style('fill', () => {
        const colors = {
          maroon: ['#800000', '#a00000', '#c00000', '#e00000'],
          default: ['#333', '#666', '#999', '#ccc']
        }
        const scheme = colors[props.settings.colorScheme] || colors.default
        return scheme[Math.floor(Math.random() * scheme.length)]
      })
      .attr('text-anchor', 'middle')
      .attr('transform', d => `translate(${d.x},${d.y})rotate(${d.rotate})`)
      .text(d => d.text)
  }
}

watch(() => [props.words, props.settings], drawWordCloud, { deep: true })
onMounted(drawWordCloud)
</script>

<template>
  <svg ref="svgRef"></svg>
</template></boltAction>

<boltAction type="file" filePath="src/components/UploadArea.vue"><script setup>
const emit = defineEmits(['text-uploaded'])

function handleFileUpload(event) {
  const file = event.target.files[0]
  if (!file) return

  const reader = new FileReader()
  reader.onload = e => emit('text-uploaded', e.target.result)
  reader.readAsText(file)
}

function handlePaste(event) {
  const text = event.clipboardData.getData('text/plain')
  if (text) emit('text-uploaded', text)
}
</script>

