import { useState, useEffect } from 'react'
import { Search, Plus, Trash2, Edit, Tag, LogIn, LogOut, User } from 'lucide-react'
import NoteEditor from './components/NoteEditor'
import NoteList from './components/NoteList'
import LoginModal from './components/LoginModal'
import { Note, Category } from './types'

function App() {
  const [notes, setNotes] = useState<Note[]>([])
  const [filteredNotes, setFilteredNotes] = useState<Note[]>([])
  const [selectedNote, setSelectedNote] = useState<Note | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [categories, setCategories] = useState<Category[]>([])
  const [isLoggedIn, setIsLoggedIn] = useState(false)
  const [showLoginModal, setShowLoginModal] = useState(false)
  const [currentUser, setCurrentUser] = useState('')

  useEffect(() => {
    const savedNotes = localStorage.getItem('notes')
    const savedCategories = localStorage.getItem('categories')
    const savedUser = localStorage.getItem('currentUser')

    if (savedNotes) setNotes(JSON.parse(savedNotes))
    if (savedCategories) setCategories(JSON.parse(savedCategories))
    if (savedUser) {
      setCurrentUser(savedUser)
      setIsLoggedIn(true)
    }
  }, [])

  useEffect(() => {
    localStorage.setItem('notes', JSON.stringify(notes))
    localStorage.setItem('categories', JSON.stringify(categories))
    if (currentUser) localStorage.setItem('currentUser', currentUser)
  }, [notes, categories, currentUser])

  useEffect(() => {
    const filtered = notes.filter(note => 
      note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      note.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
      note.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
    )
    setFilteredNotes(filtered)
  }, [searchTerm, notes])

  const handleLogin = (username: string) => {
    setCurrentUser(username)
    setIsLoggedIn(true)
    setShowLoginModal(false)
  }

  const handleLogout = () => {
    setCurrentUser('')
    setIsLoggedIn(false)
    localStorage.removeItem('currentUser')
  }

  const createNewNote = () => {
    const newNote: Note = {
      id: Date.now(),
      title: 'Untitled Note',
      content: '',
      tags: [],
      category: '',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      createdBy: currentUser
    }
    setNotes([...notes, newNote])
    setSelectedNote(newNote)
  }

  const updateNote = (updatedNote: Note) => {
    setNotes(notes.map(note => 
      note.id === updatedNote.id ? {...updatedNote, updatedAt: new Date().toISOString()} : note
    ))
    setSelectedNote(updatedNote)
  }

  const deleteNote = (id: number) => {
    setNotes(notes.filter(note => note.id !== id))
    if (selectedNote?.id === id) setSelectedNote(null)
  }

  const addCategory = (category: string) => {
    if (!categories.includes(category)) {
      setCategories([...categories, category])
    }
  }

  const addTag = (tag: string) => {
    if (selectedNote && !selectedNote.tags.includes(tag)) {
      const updatedNote = {
        ...selectedNote,
        tags: [...selectedNote.tags, tag]
      }
      updateNote(updatedNote)
    }
  }

  return (
    <div className="min-h-screen bg-whitesmoke">
      <header className="bg-rosybrown text-white p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold">Notes App</h1>
          <div className="flex items-center space-x-4">
            {isLoggedIn ? (
              <>
                <span className="flex items-center">
                  <User className="mr-1" size={18} /> {currentUser}
                </span>
                <button 
                  onClick={handleLogout}
                  className="flex items-center hover:bg-rosybrown-dark p-2 rounded"
                >
                  <LogOut className="mr-1" size={18} /> Logout
                </button>
              </>
            ) : (
              <button 
                onClick={() => setShowLoginModal(true)}
                className="flex items-center hover:bg-rosybrown-dark p-2 rounded"
              >
                <LogIn className="mr-1" size={18} /> Login
              </button>
            )}
          </div>
        </div>
      </header>

      <main className="container mx-auto p-4 grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="md:col-span-1 bg-white p-4 rounded-lg shadow">
          <div className="mb-4">
            <div className="relative">
              <input
                type="text"
                placeholder="Search notes..."
                className="w-full p-2 pl-8 border rounded"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <Search className="absolute left-2 top-3 text-gray-400" size={16} />
            </div>
          </div>

          <div className="mb-4">
            <button
              onClick={createNewNote}
              disabled={!isLoggedIn}
              className={`w-full flex items-center justify-center p-2 rounded ${isLoggedIn ? 'bg-rosybrown text-white hover:bg-rosybrown-dark' : 'bg-gray-300 cursor-not-allowed'}`}
            >
              <Plus className="mr-1" size={16} /> New Note
            </button>
          </div>

          <NoteList 
            notes={filteredNotes} 
            onSelectNote={setSelectedNote} 
            selectedNoteId={selectedNote?.id}
            currentUser={currentUser}
          />
        </div>

        <div className="md:col-span-3">
          {selectedNote ? (
            <NoteEditor 
              note={selectedNote} 
              onUpdate={updateNote} 
              onDelete={deleteNote}
              categories={categories}
              onAddCategory={addCategory}
              onAddTag={addTag}
            />
          ) : (
