import { useState } from 'react'
import { Trash2, Edit, Tag, Save } from 'lucide-react'
import { Note, Category } from '../types'

interface NoteEditorProps {
  note: Note
  onUpdate: (note: Note) => void
  onDelete: (id: number) => void
  categories: Category[]
  onAddCategory: (category: string) => void
  onAddTag: (tag: string) => void
}

export default function NoteEditor({ 
  note, 
  onUpdate, 
  onDelete, 
  categories, 
  onAddCategory, 
  onAddTag 
}: NoteEditorProps) {
  const [editingTitle, setEditingTitle] = useState(false)
  const [newTag, setNewTag] = useState('')
  const [newCategory, setNewCategory] = useState('')

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate({ ...note, title: e.target.value })
  }

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    onUpdate({ ...note, content: e.target.value })
  }

  const handleAddTag = () => {
    if (newTag.trim()) {
      onAddTag(newTag.trim())
      setNewTag('')
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    onUpdate({
      ...note,
      tags: note.tags.filter(tag => tag !== tagToRemove)
    })
  }

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const category = e.target.value
    if (category && !categories.includes(category)) {
      onAddCategory(category)
    }
    onUpdate({ ...note, category })
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow h-full">
      <div className="flex justify-between items-center mb-4">
        {editingTitle ? (
          <input
            type="text"
            value={note.title}
            onChange={handleTitleChange}
            onBlur={() => setEditingTitle(false)}
            className="text-xl font-bold w-full p-1 border-b focus:outline-none focus:border-rosybrown"
            autoFocus
          />
        ) : (
          <h2 
            className="text-xl font-bold cursor-pointer hover:text-rosybrown"
            onClick={() => setEditingTitle(true)}
          >
            {note.title || 'Untitled Note'}
          </h2>
        )}
        <div className="flex space-x-2">
          <button
            onClick={() => onDelete(note.id)}
            className="p-2 text-gray-500 hover:text-red-500"
            title="Delete note"
          >
            <Trash2 size={18} />
          </button>
          <button
            onClick={() => setEditingTitle(true)}
            className="p-2 text-gray-500 hover:text-rosybrown"
            title="Edit title"
          >
            <Edit size={18} />
          </button>
        </div>
      </div>

      <div className="mb-4">
        <textarea
          value={note.content}
          onChange={handleContentChange}
          className="w-full h-64 p-2 border rounded focus:outline-none focus:ring-1 focus:ring-rosybrown"
          placeholder="Write your note here..."
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Tags</label>
          <div className="flex flex-wrap gap-1 mb-2">
            {note.tags.map(tag => (
              <span 
                key={tag} 
                className="flex items-center bg-gray-200 rounded px-2 py-1 text-sm"
              >
                {tag}
                <button 
                  onClick={() => handleRemoveTag(tag)}
                  className="ml-1 text-gray-500 hover:text-red-500"
                >
                  ×
                </button>
              </span>
            ))}
          </div>
          <div className="flex">
            <input
              type="text"
              value={newTag}
              onChange={(e) => setNewTag(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAddTag()}
              placeholder="Add tag..."
              className="flex-1 p-2 border rounded-l focus:outline-none focus:ring-1 focus:ring-rosybrown"
            />
            <button
              onClick={handleAddTag}
              className="bg-rosybrown text-white p-2 rounded-r hover:bg-rosybrown-dark"
            >
              <Tag size={16} />
            </button>
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
          <div className="flex">
            <select
              value={note.category}
              onChange={handleCategoryChange}
              className="flex-1 p-2 border rounded-l focus:outline-none focus:ring-1 focus:ring-rosybrown"
            >
              <option value="">Select a category</option>
              {categories.map(category => (
                <option key={category} value={category}>{category}</option>
              ))}
            </select>
            <input
              type="text"
              value={newCategory}
              onChange={(e) => setNewCategory(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && newCategory.trim()) {
                  onAddCategory(newCategory.trim())
                  onUpdate({ ...note, category: newCategory.trim() })
                  setNewCategory('')
                }
              }}
              placeholder="New category..."
              className="flex-1 p-2 border-t border-b border-r border-l-0 focus:outline-none focus:ring-1 focus:ring-rosybrown"
            />
            <button
              onClick={() => {
                if (newCategory.trim()) {
                  onAddCategory(newCategory.trim())
                  onUpdate({ ...note, category: newCategory.trim() })
                  setNewCategory('')
                }
              }}
              className="bg-rosybrown text-white p-2 rounded-r hover:bg-rosybrown-dark"
            >
              <Save size={16} />
            </button>
          </div>
        </div>
      </div>

      <div className="mt-4 text-xs text-gray-500">
        <p>Created: {new Date(note.createdAt).toLocaleString()}</p>
        <p>Last updated: {new Date(note.updatedAt).toLocaleString()}</p>
      </div>
    </div>
  )
}
</boltAction>

