<script setup lang="ts">
import { ref } from 'vue'
import FormElement from './FormElement.vue'
import FormPreview from './FormPreview.vue'

const formElements = ref([
  { id: 1, type: 'text', label: 'Text Input', required: false },
  { id: 2, type: 'textarea', label: 'Text Area', required: false },
  { id: 3, type: 'checkbox', label: 'Checkbox', required: false },
  { id: 4, type: 'radio', label: 'Radio Buttons', required: false },
  { id: 5, type: 'select', label: 'Dropdown', required: false },
])

const formFields = ref<any[]>([])
const activeField = ref<any>(null)

function handleDragStart(element: any) {
  activeField.value = element
}

function handleDrop() {
  if (activeField.value) {
    formFields.value.push({
      ...activeField.value,
      id: Date.now()
    })
    activeField.value = null
  }
}
</script>

<template>
