    <div class="elements-panel">
      <h3>Form Elements</h3>
      <FormElement 
        v-for="element in formElements" 
        :key="element.id"
        :element="element"
        @drag-start="handleDragStart"
      />
    </div>

    <div 
      class="form-canvas"
      @drop.prevent="handleDrop"
      @dragover.prevent
    >
      <FormPreview :fields="formFields" />
