<script setup lang="ts">
import { ref } from 'vue'
import FormElement from './FormElement.vue'
import FormPreview from './FormPreview.vue'

type FormElementType = 'text' | 'dropdown' | 'checkbox'

interface FormItem {
  id: string
  type: FormElementType
  label: string
  options?: string[]
  required?: boolean
}

const formElements = ref<FormItem[]>([])
const activeElement = ref<FormItem | null>(null)

const addElement = (type: FormElementType) => {
  const newElement: FormItem = {
    id: Date.now().toString(),
    type,
    label: `${type} field`,
    ...(type === 'dropdown' ? { options: ['Option 1', 'Option 2'] } : {})
  }
  formElements.value.push(newElement)
  activeElement.value = newElement
}

const updateElement = (id: string, updates: Partial<FormItem>) => {
  const index = formElements.value.findIndex(el => el.id === id)
  if (index !== -1) {
    formElements.value[index] = { ...formElements.value[index], ...updates }
  }
}

const removeElement = (id: string) => {
  formElements.value = formElements.value.filter(el => el.id !== id)
  if (activeElement.value?.id === id) {
    activeElement.value = null
  }
}
</script>

<template>
  <div class="form-designer">
    <div class="toolbox">
      <h3>Form Elements</h3>
      <button @click="() => addElement('text')">Add Text Field</button>
      <button @click="() => addElement('dropdown')">Add Dropdown</button>
      <button @click="() => addElement('checkbox')">Add Checkbox</button>
    </div>

    <div class="design-area">
      <FormPreview 
        :elements="formElements" 
        :activeElement="activeElement"
        @select="(el) => activeElement = el"
      />
    </div>

    <div class="properties-panel" v-if="activeElement">
      <FormElement 
        :element="activeElement"
        @update="updateElement"
        @remove="removeElement"
      />
    </div>
  </div>
</template>

