<script setup lang="ts">
import { ref, onMounted } from 'vue'

const imageSrc = ref('')
const canvasRef = ref<HTMLCanvasElement | null>(null)
const ctx = ref<CanvasRenderingContext2D | null>(null)
const watermarkText = ref('')
const watermarkColor = ref('#000000')
const watermarkSize = ref(20)
const rotationAngle = ref(0)
const scaleFactor = ref(1)

onMounted(() => {
  if (canvasRef.value) {
    ctx.value = canvasRef.value.getContext('2d')
  }
})

const handleImageUpload = (e: Event) => {
  const input = e.target as HTMLInputElement
  if (input.files && input.files[0]) {
    const reader = new FileReader()
    reader.onload = (event) => {
      imageSrc.value = event.target?.result as string
      drawImage()
    }
    reader.readAsDataURL(input.files[0])
  }
}

const drawImage = () => {
  if (!ctx.value || !imageSrc.value) return

  const img = new Image()
  img.onload = () => {
    if (!canvasRef.value || !ctx.value) return

    canvasRef.value.width = img.width * scaleFactor.value
    canvasRef.value.height = img.height * scaleFactor.value

    ctx.value.save()
    ctx.value.translate(canvasRef.value.width / 2, canvasRef.value.height / 2)
    ctx.value.rotate((rotationAngle.value * Math.PI) / 180)
    ctx.value.scale(scaleFactor.value, scaleFactor.value)
    ctx.value.drawImage(img, -img.width / 2, -img.height / 2)
    ctx.value.restore()

    if (watermarkText.value) {
      addWatermark()
    }
  }
  img.src = imageSrc.value
}

const addWatermark = () => {
  if (!ctx.value || !canvasRef.value || !watermarkText.value) return

  ctx.value.font = `${watermarkSize.value}px Arial`
  ctx.value.fillStyle = watermarkColor.value
  ctx.value.textAlign = 'center'
  ctx.value.fillText(
    watermarkText.value,
    canvasRef.value.width / 2,
    canvasRef.value.height - 20
  )
}

const rotateImage = (angle: number) => {
  rotationAngle.value = angle
  drawImage()
}

const resizeImage = (factor: number) => {
  scaleFactor.value = factor
  drawImage()
}

const downloadImage = () => {
  if (!canvasRef.value) return

  const link = document.createElement('a')
  link.download = 'processed-image.png'
  link.href = canvasRef.value.toDataURL('image/png')
  link.click()
}
</script>

<template>
  <div class="image-editor">
    <div class="upload-section">
      <input type="file" accept="image/*" @change="handleImageUpload">
    </div>

    <div class="editor-container">
      <div class="canvas-container">
        <canvas ref="canvasRef" class="image-canvas"></canvas>
      </div>

      <div class="controls">
        <div class="control-group">
          <h3>Rotation</h3>
          <button @click="rotateImage(90)">90°</button>
          <button @click="rotateImage(180)">180°</button>
          <button @click="rotateImage(270)">270°</button>
        </div>

        <div class="control-group">
          <h3>Resize</h3>
          <button @click="resizeImage(0.5)">50%</button>
          <button @click="resizeImage(1)">100%</button>
          <button @click="resizeImage(1.5)">150%</button>
        </div>

        <div class="control-group">
          <h3>Watermark</h3>
          <input v-model="watermarkText" type="text" placeholder="Watermark text">
          <input v-model="watermarkColor" type="color">
          <input v-model="watermarkSize" type="range" min="10" max="50">
          <button @click="addWatermark">Apply Watermark</button>
        </div>

        <button class="download-btn" @click="downloadImage">Download Image</button>
      </div>
    </div>
  </div>
</template>

