  <boltAction type="file" filePath="main.js">import { Editor } from '@monaco-editor/react';
import prettier from 'prettier';
import phpPlugin from '@prettier/plugin-php';

let editorRef = null;

function handleEditorDidMount(editor, monaco) {
  editorRef = editor;
  monaco.editor.defineTheme('phpTheme', {
    base: 'vs-dark',
    inherit: true,
    rules: [
      { token: 'keyword.php', foreground: '9370db' },
      { token: 'string.php', foreground: 'ffa500' },
      { token: 'number.php', foreground: '98fb98' }
    ],
    colors: {
      'editor.background': '#d8bfd8'
    }
  });
  monaco.editor.setTheme('phpTheme');
}

document.getElementById('format-btn').addEventListener('click', () => {
  if (editorRef) {
    const code = editorRef.getValue();
    const formatted = prettier.format(code, {
      parser: 'php',
      plugins: [phpPlugin],
      tabWidth: 2,
      useTabs: false,
      printWidth: 80
    });
    editorRef.setValue(formatted);
  }
});

document.getElementById('clear-btn').addEventListener('click', () => {
  if (editorRef) {
    editorRef.setValue('');
  }
});

function App() {
  return (
    <Editor
      height="100%"
      defaultLanguage="php"
      defaultValue="<?php\n\n// Enter your PHP code here\n\n?>"
      onMount={handleEditorDidMount}
      options={{
        minimap: { enabled: false },
        fontSize: 14,
        wordWrap: 'on',
        folding: true,
        lineNumbers: 'on',
        automaticLayout: true
      }}
    />
  );
}

document.addEventListener('DOMContentLoaded', () => {
  const editorContainer = document.getElementById('editor');
  const root = document.createElement('div');
  root.style.height = '100%';
  editorContainer.appendChild(root);
  App();
});</boltAction>

