<script setup lang="ts">
import { ref } from 'vue'

interface FormField {
  type: string
  label: string
  name: string
  required?: boolean
  options?: string[]
  default?: any
}

const jsonInput = ref(`{
  "fields": [
    {
      "type": "text",
      "label": "Username",
      "name": "username",
      "required": true
    },
    {
      "type": "email",
      "label": "Email",
      "name": "email",
      "required": true
    },
    {
      "type": "select",
      "label": "Country",
      "name": "country",
      "options": ["USA", "Canada", "UK", "Australia"]
    },
    {
      "type": "checkbox",
      "label": "Subscribe to newsletter",
      "name": "subscribe"
    }
  ]
}`)

const formFields = ref<FormField[]>([])
const formData = ref<Record<string, any>>({})
const error = ref('')

const generateForm = () => {
  try {
    const parsed = JSON.parse(jsonInput.value)
    if (!parsed.fields || !Array.isArray(parsed.fields)) {
      throw new Error('Invalid JSON format. Expected "fields" array.')
    }
    formFields.value = parsed.fields
    formData.value = {}
    error.value = ''
  } catch (err) {
    error.value = 'Invalid JSON: ' + (err as Error).message
  }
}

const handleSubmit = () => {
  alert('Form submitted: ' + JSON.stringify(formData.value))
}
</script>

