<script setup lang="ts">
import { ref } from 'vue'

interface FileInfo {
  name: string
  size: number
  lastModified: number
}

interface ConversionOption {
  id: string
  name: string
  description: string
}

const uploadedFiles = ref<FileInfo[]>([])
const selectedFiles = ref<string[]>([])
const conversionOptions = ref<ConversionOption[]>([
  { id: 'basic', name: 'Basic Structure', description: 'Converts to simple JSON with paragraphs as array items' },
  { id: 'detailed', name: 'Detailed Structure', description: 'Includes formatting, styles, and metadata in output' },
  { id: 'custom', name: 'Custom Structure', description: 'Define your own JSON structure template' }
])
const selectedOption = ref('basic')
const previewJson = ref('')
const customTemplate = ref('')

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (input.files) {
    uploadedFiles.value = Array.from(input.files).map(file => ({
      name: file.name,
      size: file.size,
      lastModified: file.lastModified
    }))
  }
}

const toggleFileSelection = (fileName: string) => {
  const index = selectedFiles.value.indexOf(fileName)
  if (index === -1) {
    selectedFiles.value.push(fileName)
  } else {
    selectedFiles.value.splice(index, 1)
  }
}

const generatePreview = () => {
  // Simulate conversion for demo purposes
  previewJson.value = JSON.stringify({
    files: selectedFiles.value,
    option: selectedOption.value,
    timestamp: new Date().toISOString(),
    content: "This would contain the actual converted content in a real implementation"
  }, null, 2)
}

const downloadJson = () => {
  if (!previewJson.value) return

  const blob = new Blob([previewJson.value], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'converted-document.json'
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}
</script>

