<script setup lang="ts">
import { ref } from 'vue'

interface ChecklistItem {
  id: number
  text: string
  completed: boolean
}

const items = ref<ChecklistItem[]>([])
const newItemText = ref('')
const editingItemId = ref<number | null>(null)
const editText = ref('')

const addItem = () => {
  if (newItemText.value.trim()) {
    items.value.push({
      id: Date.now(),
      text: newItemText.value.trim(),
      completed: false
    })
    newItemText.value = ''
  }
}

const startEdit = (item: ChecklistItem) => {
  editingItemId.value = item.id
  editText.value = item.text
}

const saveEdit = () => {
  const index = items.value.findIndex(item => item.id === editingItemId.value)
  if (index !== -1) {
    items.value[index].text = editText.value
    editingItemId.value = null
  }
}

const deleteItem = (id: number) => {
  items.value = items.value.filter(item => item.id !== id)
}

const toggleComplete = (id: number) => {
  const item = items.value.find(item => item.id === id)
  if (item) {
    item.completed = !item.completed
  }
}

const moveItem = (index: number, direction: 'up' | 'down') => {
  if (
    (direction === 'up' && index > 0) ||
    (direction === 'down' && index < items.value.length - 1)
  ) {
    const newIndex = direction === 'up' ? index - 1 : index + 1
    const temp = items.value[index]
    items.value[index] = items.value[newIndex]
    items.value[newIndex] = temp
  }
}

const exportPDF = () => {
  alert('PDF export functionality would be implemented here')
}

const exportExcel = () => {
  alert('Excel export functionality would be implemented here')
}
</script>

