      <input
        v-model="newItemText"
        @keyup.enter="addItem"
        placeholder="Add new checklist item"
      />
      <button @click="addItem" class="action-button">Add</button>
    </div>

    <ul class="items-list">
      <li v-for="(item, index) in items" :key="item.id" class="item">
        <input
          type="checkbox"
          :checked="item.completed"
          @change="toggleComplete(item.id)"
        />

        <div v-if="editingItemId === item.id" class="edit-mode">
          <input v-model="editText" @keyup.enter="saveEdit" />
          <button @click="saveEdit" class="action-button">Save</button>
        </div>
        <span v-else :class="{ completed: item.completed }">
          {{ item.text }}
        </span>

        <div class="item-actions">
          <button @click="startEdit(item)" class="edit-button">Edit</button>
          <button @click="deleteItem(item.id)" class="delete-button">Delete</button>
          <button @click="moveItem(index, 'up')" class="move-button">↑</button>
          <button @click="moveItem(index, 'down')" class="move-button">↓</button>
        </div>
      </li>
    </ul>

    <div class="export-actions" v-if="items.length > 0">
