<script setup lang="ts">
import { ref, reactive } from 'vue'

type FieldType = 'text' | 'number' | 'select' | 'checkbox' | 'date' | 'radio'
type Field = {
  id: string
  label: string
  type: FieldType
  required: boolean
  options?: string[]
  dependsOn?: string
  showWhen?: string
}

const formFields = reactive<Field[]>([
  {
    id: 'name',
    label: 'Full Name',
    type: 'text',
    required: true
  }
])

const newField = reactive<Omit<Field, 'id'>>({
  label: '',
  type: 'text',
  required: false,
  options: [],
  dependsOn: '',
  showWhen: ''
})

const addField = () => {
  if (!newField.label) return

  const field: Field = {
    id: `field-${Date.now()}`,
    ...newField
  }

  formFields.push(field)
  resetNewField()
}

const resetNewField = () => {
  newField.label = ''
  newField.type = 'text'
  newField.required = false
  newField.options = []
  newField.dependsOn = ''
  newField.showWhen = ''
}

const removeField = (id: string) => {
  const index = formFields.findIndex(f => f.id === id)
  if (index !== -1) {
    formFields.splice(index, 1)
  }
}

const formData = ref<Record<string, any>>({})
const submittedData = ref<Record<string, any> | null>(null)

const submitForm = () => {
  submittedData.value = {...formData.value}
}
</script>

<template>
  <div class="form-builder">
    <div class="builder-section">
      <h2>Form Builder</h2>
      <div class="field-config">
        <div class="form-group">
          <label>Field Label:</label>
          <input v-model="newField.label" placeholder="Enter field label">
        </div>

        <div class="form-group">
          <label>Field Type:</label>
          <select v-model="newField.type">
            <option value="text">Text</option>
            <option value="number">Number</option>
            <option value="select">Dropdown</option>
            <option value="checkbox">Checkbox</option>
            <option value="date">Date</option>
            <option value="radio">Radio</option>
          </select>
        </div>

        <div class="form-group" v-if="['select', 'radio'].includes(newField.type)">
          <label>Options (comma separated):</label>
          <input v-model="newField.options" placeholder="Option 1, Option 2, Option 3">
        </div>

        <div class="form-group">
          <label>
            <input type="checkbox" v-model="newField.required">
            Required Field
          </label>
        </div>

        <div class="form-group">
          <label>Depends On (Field ID):</label>
          <input v-model="newField.dependsOn" placeholder="Enter field ID this depends on">
        </div>

        <div class="form-group" v-if="newField.dependsOn">
          <label>Show When Value Is:</label>
          <input v-model="newField.showWhen" placeholder="Enter value that shows this field">
        </div>

        <button @click="addField" class="add-btn">Add Field</button>
      </div>

      <div class="fields-list">
        <h3>Current Fields</h3>
        <div v-for="field in formFields" :key="field.id" class="field-item">
          <span>{{ field.label }} ({{ field.type }})</span>
          <button @click="removeField(field.id)" class="remove-btn">Remove</button>
        </div>
      </div>
    </div>

    <div class="form-section">
      <h2>Preview Form</h2>
      <form @submit.prevent="submitForm" class="preview-form">
        <div v-for="field in formFields" :key="field.id" class="form-field">
          <label :for="field.id">
            {{ field.label }}
            <span v-if="field.required" class="required">*</span>
          </label>

          <input
            v-if="field.type === 'text' || field.type === 'number'"
            v-model="formData[field.id]"
            :type="field.type"
            :id="field.id"
            :required="field.required"
          >

          <select
            v-else-if="field.type === 'select'"
            v-model="formData[field.id]"
            :id="field.id"
            :required="field.required"
          >
            <option v-for="option in field.options" :key="option" :value="option">
              {{ option }}
            </option>
          </select>

          <div v-else-if="field.type === 'checkbox'">
            <input
              type="checkbox"
              v-model="formData[field.id]"
              :id="field.id"
            >
          </div>

          <input
            v-else-if="field.type === 'date'"
            type="date"
            v-model="formData[field.id]"
            :id="field.id"
            :required="field.required"
          >

