<script setup lang="ts">
import { ref } from 'vue'
import FileUpload from './components/FileUpload.vue'
import FileList from './components/FileList.vue'
import LoginForm from './components/LoginForm.vue'

const isLoggedIn = ref(false)
const files = ref<Array<{name: string, type: string, url: string, previewUrl?: string}>>([])

const handleLogin = () => {
  isLoggedIn.value = true
}

const handleLogout = () => {
  isLoggedIn.value = false
}

const handleFileUpload = (file: File) => {
  const fileObj = {
    name: file.name,
    type: file.type,
    url: URL.createObjectURL(file)
  }

  if (file.type.startsWith('image/') || file.type.startsWith('video/') || file.type === 'application/pdf') {
    fileObj.previewUrl = URL.createObjectURL(file)
  }

  files.value.push(fileObj)
}
</script>

<template>
  <div class="app-container">
    <header class="header">
      <h1>Document Management System</h1>
      <button v-if="isLoggedIn" @click="handleLogout" class="logout-btn">Logout</button>
    </header>

    <main>
      <LoginForm v-if="!isLoggedIn" @login="handleLogin" />
      <div v-else class="content">
        <FileUpload @file-uploaded="handleFileUpload" />
        <FileList :files="files" />
