<script setup lang="ts">
import { ref } from 'vue'

const article1 = ref('')
const article2 = ref('')
const similarityScore = ref<number | null>(null)

const calculateSimilarity = () => {
  if (!article1.value.trim() || !article2.value.trim()) return

  // Simple similarity calculation (for demo purposes)
  const words1 = article1.value.toLowerCase().split(/\s+/)
  const words2 = article2.value.toLowerCase().split(/\s+/)

  const commonWords = words1.filter(word => words2.includes(word))
  const uniqueWords = [...new Set([...words1, ...words2])]

  similarityScore.value = Math.round(
    (commonWords.length / uniqueWords.length) * 100
  )
}
