  const baseClasses = 'rounded-md font-medium transition-all focus:ring-2 focus:ring-offset-2 focus:ring-sienna-500'

  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2 text-base',
