    secondary: 'bg-sienna-100 text-sienna-800 hover:bg-sienna-200',
    outline: 'border border-sienna-300 text-sienna-700 hover:bg-sienna-50'
  }

  return (
    <button
      className={`${baseClasses} ${sizeClasses[size]} ${variantClasses[variant]} ${className}`}
      {...props}
