import React from 'react'

interface BarChartProps {
  data: {
    label: string
    value: number
  }[]
  width?: number
  height?: number
  className?: string
}

const BarChart: React.FC<BarChartProps> = ({
  data,
  width = 600,
  height = 400,
  className = ''
}) => {
  const maxValue = Math.max(...data.map(item => item.value))
  const barWidth = width / data.length - 10

  return (
    <div className={`bg-white p-6 rounded-lg border border-sienna-200 ${className}`}>
      <svg width={width} height={height}>
        {data.map((item, index) => {
          const barHeight = (item.value / maxValue) * (height - 60)
          return (
            <g key={index} transform={`translate(${index * (barWidth + 10) + 5}, ${height - barHeight - 30})`}>
              <rect
                width={barWidth}
                height={barHeight}
                fill="#A0522D" // sienna color
                rx={4}
              />
              <text
                x={barWidth / 2}
                y={barHeight + 20}
                textAnchor="middle"
                fontSize="12"
                fill="#5A3E36" // dark sienna
              >
                {item.label}
              </text>
              <text
                x={barWidth / 2}
                y={-10}
                textAnchor="middle"
                fontSize="12"
                fill="#5A3E36"
              >
                {item.value}
              </text>
            </g>
          )
        })}
      </svg>
    </div>
  )
}

export default BarChart
