import React from 'react'

interface FormField {
  name: string
  label: string
  type: string
  placeholder?: string
  required?: boolean
  options?: { value: string; label: string }[]
}

interface FormProps {
  fields: FormField[]
  onSubmit: (data: Record<string, string>) => void
  submitText?: string
  className?: string
}

const Form: React.FC<FormProps> = ({
  fields,
  onSubmit,
  submitText = 'Submit',
  className = ''
}) => {
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const formData = new FormData(e.target as HTMLFormElement)
    const data: Record<string, string> = {}
    fields.forEach(field => {
      data[field.name] = formData.get(field.name) as string
    })
    onSubmit(data)
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={`bg-white p-6 rounded-lg border border-sienna-200 ${className}`}
    >
      <div className="space-y-4">
        {fields.map((field) => (
          <div key={field.name}>
            <label
              htmlFor={field.name}
              className="block text-sm font-medium text-sienna-700"
            >
              {field.label}
              {field.required && <span className="text-sienna-500 ml-1">*</span>}
            </label>
            {field.type === 'select' ? (
              <select
                id={field.name}
                name={field.name}
                required={field.required}
                className="mt-1 block w-full rounded-md border-sienna-300 shadow-sm focus:border-sienna-500 focus:ring-sienna-500 text-sienna-700"
              >
                {field.options?.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            ) : (
              <input
                type={field.type}
                id={field.name}
                name={field.name}
                placeholder={field.placeholder}
                required={field.required}
                className="mt-1 block w-full rounded-md border-sienna-300 shadow-sm focus:border-sienna-500 focus:ring-sienna-500 text-sienna-700"
              />
            )}
          </div>
        ))}
      </div>
      <div className="mt-6">
        <button
          type="submit"
          className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-sienna-600 hover:bg-sienna-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-sienna-500"
        >
          {submitText}
        </button>
      </div>
    </form>
  )
}

export default Form
</boltAction>

