  <boltAction type="file" filePath="src/utils/reminderScheduler.js">
export function scheduleReminder(reminder) {
  const now = new Date()
  const reminderTime = new Date(reminder.dateTime)
  const timeUntilReminder = reminderTime - now

  if (timeUntilReminder > 0) {
    setTimeout(() => {
      if ('speechSynthesis' in window) {
        const utterance = new SpeechSynthesisUtterance(reminder.message)
        speechSynthesis.speak(utterance)
      } else {
        alert(reminder.message)
      }

      // Handle repeating reminders
      if (reminder.repeat !== 'none') {
        let nextTime = new Date(reminderTime)
        if (reminder.repeat === 'daily') {
          nextTime.setDate(nextTime.getDate() + 1)
        } else if (reminder.repeat === 'weekly') {
          nextTime.setDate(nextTime.getDate() + 7)
        } else if (reminder.repeat === 'monthly') {
          nextTime.setMonth(nextTime.getMonth() + 1)
        }

        const newReminder = {
          ...reminder,
          dateTime: nextTime.toISOString()
        }
        scheduleReminder(newReminder)
      }
    }, timeUntilReminder)
  }
}
