<script setup lang="ts">
import { ref, onMounted } from 'vue'

const canvasRef = ref<HTMLCanvasElement | null>(null)
const ctx = ref<CanvasRenderingContext2D | null>(null)
const isDrawing = ref(false)
const currentTool = ref('select')
const shapes = ref<any[]>([])
const selectedShape = ref<any>(null)

onMounted(() => {
  if (canvasRef.value) {
    ctx.value = canvasRef.value.getContext('2d')
    resizeCanvas()
  }
  window.addEventListener('resize', resizeCanvas)
})

function resizeCanvas() {
  if (canvasRef.value) {
    canvasRef.value.width = window.innerWidth * 0.8
    canvasRef.value.height = window.innerHeight * 0.8
    redrawCanvas()
  }
}

function redrawCanvas() {
  if (!ctx.value) return
  ctx.value.clearRect(0, 0, canvasRef.value?.width || 0, canvasRef.value?.height || 0)
  shapes.value.forEach(shape => {
    drawShape(shape)
  })
}

function drawShape(shape: any) {
  if (!ctx.value) return
  ctx.value.beginPath()

  if (shape.type === 'line') {
    ctx.value.moveTo(shape.x1, shape.y1)
    ctx.value.lineTo(shape.x2, shape.y2)
  } else if (shape.type === 'rect') {
    ctx.value.rect(shape.x, shape.y, shape.width, shape.height)
  }

  ctx.value.strokeStyle = shape.color || 'dimgray'
  ctx.value.lineWidth = shape.width || 2
  ctx.value.stroke()
}

function startDrawing(e: MouseEvent) {
  if (!canvasRef.value) return
  const rect = canvasRef.value.getBoundingClientRect()
  const x = e.clientX - rect.left
  const y = e.clientY - rect.top

  if (currentTool.value === 'select') {
    selectedShape.value = null
    shapes.value.forEach(shape => {
      if (isPointInShape(x, y, shape)) {
        selectedShape.value = shape
      }
    })
    redrawCanvas()
    return
  }

  isDrawing.value = true
  const newShape = {
    type: currentTool.value,
    x1: x,
    y1: y,
    x2: x,
    y2: y,
    color: 'dimgray'
  }
  shapes.value.push(newShape)
}

function isPointInShape(x: number, y: number, shape: any) {
  if (shape.type === 'line') {
    // Simple line hit detection
    const d = distanceToLine(x, y, shape.x1, shape.y1, shape.x2, shape.y2)
    return d < 10
  }
  return false
}

function distanceToLine(x: number, y: number, x1: number, y1: number, x2: number, y2: number) {
  const A = x - x1
  const B = y - y1
  const C = x2 - x1
  const D = y2 - y1

  const dot = A * C + B * D
  const len_sq = C * C + D * D
  let param = -1
  if (len_sq !== 0) param = dot / len_sq

  let xx, yy

  if (param < 0) {
    xx = x1
    yy = y1
  } else if (param > 1) {
    xx = x2
    yy = y2
  } else {
    xx = x1 + param * C
    yy = y1 + param * D
  }

  const dx = x - xx
  const dy = y - yy
  return Math.sqrt(dx * dx + dy * dy)
}

function continueDrawing(e: MouseEvent) {
  if (!isDrawing.value || !canvasRef.value) return
  const rect = canvasRef.value.getBoundingClientRect()
  const x = e.clientX - rect.left
  const y = e.clientY - rect.top

  const currentShape = shapes.value[shapes.value.length - 1]
  currentShape.x2 = x
  currentShape.y2 = y
  redrawCanvas()
}

function stopDrawing() {
  isDrawing.value = false
}

function exportAsSVG() {
  let svg = `<svg width="${canvasRef.value?.width}" height="${canvasRef.value?.height}" xmlns="http://www.w3.org/2000/svg">`

  shapes.value.forEach(shape => {
    if (shape.type === 'line') {
      svg += `<line x1="${shape.x1}" y1="${shape.y1}" x2="${shape.x2}" y2="${shape.y2}" stroke="${shape.color || 'dimgray'}" stroke-width="${shape.width || 2}" />`
    }
  })

  svg += '</svg>'

  const blob = new Blob([svg], { type: 'image/svg+xml' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'drawing.svg'
  a.click()
}

function saveDrawing() {
  localStorage.setItem('vectorDrawing', JSON.stringify(shapes.value))
}

function loadDrawing() {
  const saved = localStorage.getItem('vectorDrawing')
  if (saved) {
    shapes.value = JSON.parse(saved)
    redrawCanvas()
  }
}
</script>

<template>
  <div class="editor-container">
    <div class="toolbar">
      <button @click="currentTool = 'line'" :class="{ active: currentTool === 'line' }">Line</button>
      <button @click="currentTool = 'rect'" :class="{ active: currentTool === 'rect' }">Rectangle</button>
      <button @click="currentTool = 'select'" :class="{ active: currentTool === 'select' }">Select</button>
      <button @click="exportAsSVG">Export SVG</button>
      <button @click="saveDrawing">Save</button>
      <button @click="loadDrawing">Load</button>
    </div>

    <canvas
      ref="canvasRef"
      @mousedown="startDrawing"
      @mousemove="continueDrawing"
      @mouseup="stopDrawing"
      @mouseleave="stopDrawing"
    ></canvas>
  </div>
</template>

