<script setup lang="ts">
import { ref, computed } from 'vue'

const props = defineProps<{
  balance: number
}>()

const emit = defineEmits(['balance-updated'])

const betAmount = ref(10)
const chosenSide = ref<'heads' | 'tails'>('heads')
const isFlipping = ref(false)
const result = ref<'heads' | 'tails' | null>(null)
const winAmount = ref(0)
const customMessage = ref('')
const randomMessages = [
  'Lucky flip!',
  'Nice one!',
  'Try again!',
  'Close call!',
  'Winner winner!'
]

const placeBet = () => {
  if (betAmount.value > props.balance) {
    alert('Insufficient balance')
    return
  }

  isFlipping.value = true
  result.value = null
  winAmount.value = 0

  setTimeout(() => {
    const flipResult = Math.random() > 0.5 ? 'heads' : 'tails'
    result.value = flipResult

    if (flipResult === chosenSide.value) {
      winAmount.value = betAmount.value * 1.95
      emit('balance-updated', winAmount.value - betAmount.value)
    } else {
      emit('balance-updated', -betAmount.value)
    }

    isFlipping.value = false
  }, 2000)
}

const getRandomMessage = () => {
  return randomMessages[Math.floor(Math.random() * randomMessages.length)]
}

const displayMessage = computed(() => {
  if (!result.value) return ''
  return customMessage.value || getRandomMessage()
})
</script>

