<boltAction type="file" filePath="src/App.tsx">
import React, { useRef, useState } from 'react'
import { Move, RotateCw, ZoomIn } from 'lucide-react'

const TouchMotionApp = () => {
  const containerRef = useRef<HTMLDivElement>(null)
  const [transform, setTransform] = useState({
    x: 0,
    y: 0,
    scale: 1,
    rotate: 0,
  })
  const [isDragging, setIsDragging] = useState(false)
  const [startPos, setStartPos] = useState({ x: 0, y: 0 })
  const [startTransform, setStartTransform] = useState({ x: 0, y: 0 })

  // Touch event handlers
  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) {
      setIsDragging(true)
      setStartPos({
        x: e.touches[0].clientX,
        y: e.touches[0].clientY,
      })
      setStartTransform({
        x: transform.x,
        y: transform.y,
      })
    }
  }

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!isDragging) return
    e.preventDefault()

    const currentX = e.touches[0].clientX
    const currentY = e.touches[0].clientY

    setTransform({
      ...transform,
      x: startTransform.x + (currentX - startPos.x),
      y: startTransform.y + (currentY - startPos.y),
    })

    // Use requestAnimationFrame for 60FPS smoothness
    requestAnimationFrame(() => {
      if (containerRef.current) {
        containerRef.current.style.transform = `
          translate(${transform.x}px, ${transform.y}px)
          scale(${transform.scale})
          rotate(${transform.rotate}deg)
        `
      }
    })
  }

  const handleTouchEnd = () => {
    setIsDragging(false)
  }

  const handlePinchZoom = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const touch1 = e.touches[0]
      const touch2 = e.touches[1]

      const distance = Math.hypot(
        touch2.clientX - touch1.clientX,
        touch2.clientY - touch1.clientY
      )

      setTransform({
        ...transform,
        scale: Math.min(Math.max(distance / 200, 0.5), 3)
      })
    }
  }

  const handleRotate = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const touch1 = e.touches[0]
      const touch2 = e.touches[1]

      const angle = Math.atan2(
        touch2.clientY - touch1.clientY,
        touch2.clientX - touch1.clientX
      ) * 180 / Math.PI

      setTransform({
        ...transform,
        rotate: angle
      })
    }
  }

  const resetTransform = () => {
    setTransform({
      x: 0,
      y: 0,
      scale: 1,
      rotate: 0,
    })
  }

  return (
    <div 
      className="min-h-screen bg-moccasin flex flex-col items-center justify-center p-4"
      onTouchStart={handleTouchStart}
      onTouchMove={(e) => {
        handleTouchMove(e)
        handlePinchZoom(e)
        handleRotate(e)
      }}
      onTouchEnd={handleTouchEnd}
    >
      <h1 className="text-3xl font-bold text-burlywood-dark mb-8">
        Touch Motion Experience
      </h1>

      <div className="relative w-full max-w-md h-96 mb-8">
        <div
          ref={containerRef}
          className="absolute w-full h-full bg-burlywood rounded-xl shadow-lg flex flex-col items-center justify-center p-4 touch-none"
          style={{
            transform: `
              translate(${transform.x}px, ${transform.y}px)
              scale(${transform.scale})
              rotate(${transform.rotate}deg)
            `,
            transition: isDragging ? 'none' : 'transform 0.2s ease-out'
          }}
        >
          <img 
            src="https://images.unsplash.com/photo-1519681393784-d120267933ba" 
            alt="Mountain landscape"
            className="w-full h-full object-cover rounded-lg"
          />
        </div>
      </div>

      <div className="flex gap-6">
        <div className="flex items-center gap-2 text-burlywood-dark">
          <Move className="w-5 h-5" />
          <span>Drag</span>
        </div>
        <div className="flex items-center gap-2 text-burlywood-dark">
          <ZoomIn className="w-5 h-5" />
          <span>Pinch to Zoom</span>
        </div>
        <div className="flex items-center gap-2 text-burlywood-dark">
          <RotateCw className="w-5 h-5" />
          <span>Rotate</span>
        </div>
      </div>

      <button
        onClick={resetTransform}
        className="mt-8 px-4 py-2 bg-burlywood text-burlywood-dark rounded-lg font-medium shadow hover:bg-burlywood-light transition-colors"
      >
        Reset Position
      </button>
    </div>
  )
}

export default TouchMotionApp
