import React, { useState, useEffect } from 'react';
import { Box, Hammer, Plus, Trash2, X } from 'lucide-react';

type ScrewColor = 'wheat' | 'chocolate';
type BoxType = { color: ScrewColor; count: number };

const SCREW_COLORS: ScrewColor[] = ['wheat', 'chocolate'];
const MAX_BOX_CAPACITY = 5;
const INITIAL_TEMP_SLOTS = 3;

const ScrewGame: React.FC = () => {
  const [screws, setScrews] = useState<ScrewColor[]>([]);
  const [boxes, setBoxes] = useState<BoxType[]>([]);
  const [tempStorage, setTempStorage] = useState<(ScrewColor | null)[]>(Array(INITIAL_TEMP_SLOTS).fill(null));
  const [score, setScore] = useState(0);
  const [glassBlocks, setGlassBlocks] = useState(3);
  const [tempSlots, setTempSlots] = useState(INITIAL_TEMP_SLOTS);

  // Initialize game
  useEffect(() => {
    generateScrews();
  }, []);

  const generateScrews = () => {
    const newScrews: ScrewColor[] = [];
    for (let i = 0; i < 12; i++) {
      newScrews.push(SCREW_COLORS[Math.floor(Math.random() * SCREW_COLORS.length)]);
    }
    setScrews(newScrews);
  };

  const handleScrewClick = (index: number) => {
    const screwColor = screws[index];

    // Try to find a matching box
    const matchingBoxIndex = boxes.findIndex(box => 
      box.color === screwColor && box.count < MAX_BOX_CAPACITY
    );

    if (matchingBoxIndex !== -1) {
      // Add to box
      const newBoxes = [...boxes];
      newBoxes[matchingBoxIndex].count += 1;

      // Check if box is full
      if (newBoxes[matchingBoxIndex].count === MAX_BOX_CAPACITY) {
        setScore(prev => prev + 10);
        newBoxes.splice(matchingBoxIndex, 1);
      }

      setBoxes(newBoxes);
    } else {
      // Try to add to temp storage
      const emptySlotIndex = tempStorage.findIndex(slot => slot === null);
      if (emptySlotIndex !== -1) {
        const newTempStorage = [...tempStorage];
        newTempStorage[emptySlotIndex] = screwColor;
        setTempStorage(newTempStorage);
      } else {
        alert('No space in temporary storage!');
        return;
      }
    }

    // Remove screw from board
    const newScrews = [...screws];
    newScrews.splice(index, 1);
    setScrews(newScrews);

    // If board is empty, generate new screws
    if (newScrews.length === 0) {
      generateScrews();
    }
  };

  const handleBoxClick = (index: number) => {
    const box = boxes[index];
    const newBoxes = [...boxes];
    newBoxes.splice(index, 1);
    setBoxes(newBoxes);
  };

  const handleTempSlotClick = (index: number) => {
    const screwColor = tempStorage[index];
    if (!screwColor) return;

    // Try to find matching box
    const matchingBoxIndex = boxes.findIndex(box => 
      box.color === screwColor && box.count < MAX_BOX_CAPACITY
    );

    if (matchingBoxIndex !== -1) {
      // Add to box
      const newBoxes = [...boxes];
      newBoxes[matchingBoxIndex].count += 1;

      // Check if box is full
      if (newBoxes[matchingBoxIndex].count === MAX_BOX_CAPACITY) {
        setScore(prev => prev + 10);
        newBoxes.splice(matchingBoxIndex, 1);
      }

      setBoxes(newBoxes);
    } else {
      // Create new box
      setBoxes([...boxes, { color: screwColor, count: 1 }]);
    }

    // Clear temp slot
    const newTempStorage = [...tempStorage];
    newTempStorage[index] = null;
    setTempStorage(newTempStorage);
  };

  const breakGlassBlock = () => {
    if (glassBlocks > 0) {
      setGlassBlocks(prev => prev - 1);
      setTempSlots(prev => prev + 1);
      setTempStorage(prev => [...prev, null]);
    }
  };

  const clearTempStorage = () => {
    setTempStorage(Array(tempSlots).fill(null));
  };

  return (
    <div className="min-h-screen bg-amber-50 p-8">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-amber-900 mb-8 text-center">Screw Matching Game</h1>

        {/* Score and Controls */}
        <div className="flex justify-between items-center mb-8 bg-amber-100 p-4 rounded-lg shadow">
          <div className="text-2xl font-semibold text-amber-800">Score: {score}</div>
          <div className="flex gap-4">
            <button 
              onClick={breakGlassBlock}
              className="flex items-center gap-2 bg-amber-700 hover:bg-amber-800 text-white px-4 py-2 rounded-lg transition"
              disabled={glassBlocks === 0}
            >
              <Hammer size={20} />
              Break Glass ({glassBlocks})
            </button>
            <button 
              onClick={clearTempStorage}
              className="flex items-center gap-2 bg-amber-700 hover:bg-amber-800 text-white px-4 py-2 rounded-lg transition"
            >
              <Trash2 size={20} />
              Clear Storage
            </button>
          </div>
        </div>

        {/* Game Board */}
        <div className="grid grid-cols-4 gap-4 mb-8">
          {screws.map((color, index) => (
            <button
              key={index}
              onClick={() => handleScrewClick(index)}
              className={`h-24 rounded-lg flex items-center justify-center shadow-md transition-transform hover:scale-105 ${
                color === 'wheat' ? 'bg-amber-200' : 'bg-amber-900'
              }`}
            >
              <div className={`w-12 h-12 rounded-full ${
                color === 'wheat' ? 'bg-amber-300' : 'bg-amber-800'
              }`}></div>
            </button>
          ))}
        </div>

        {/* Boxes */}
        <div className="mb-8">
          <h2 className="text-2xl font-semibold text-amber-800 mb-4">Boxes</h2>
          <div className="flex flex-wrap gap-4">
            {boxes.map((box, index) => (
              <div 
                key={index}
                onClick={() => handleBoxClick(index)}
                className={`p-4 rounded-lg shadow-md flex flex-col items-center cursor-pointer ${
                  box.color === 'wheat' ? 'bg-amber-200' : 'bg-amber-900'
                }`}
              >
                <Box size={32} className={box.color === 'wheat' ? 'text-amber-800' : 'text-amber-200'} />
                <div className={`text-lg font-medium mt-2 ${
                  box.color === 'wheat' ? 'text-amber-800' : 'text-amber-200'
                }`}>
                  {box.count}/{MAX_BOX_CAPACITY}
                </div>
              </div>
            ))}
            {boxes.length < 3 && (
              <button 
                onClick={() => setBoxes([...boxes, { color: 'wheat', count: 0 }])}
                className="p-4 rounded-lg bg-amber-100 hover:bg-amber-200 shadow-md flex items-center justify-center transition"
              >
                <Plus size={32} className="text-amber-800" />
              </button>
            )}
          </div>
        </div>

        {/* Temporary Storage */}
        <div>
          <h2 className="text-2xl font-semibold text-amber-800 mb-4">Temporary Storage</h2>
          <div className="flex gap-4">
            {tempStorage.map((screw, index) => (
              <button
                key={index}
                onClick={() => handleTempSlotClick(index)}
                className={`w-16 h-16 rounded-lg flex items-center justify-center shadow-md ${
                  screw === null ? 'bg-amber-100' : screw === 'wheat' ? 'bg-amber-200' : 'bg-amber-900'
                }`}
              >
                {screw === null ? (
                  <X size={24} className="text-amber-400" />
                ) : (
                  <div className={`w-8 h-8 rounded-full ${
                    screw === 'wheat' ? 'bg-amber-300' : 'bg-amber-800'
                  }`}></div>
                )}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScrewGame;
