import React, { useState, useEffect, useRef } from 'react';
import { Pause, Play, RotateCcw, Trophy } from 'lucide-react';

const PingPongGame = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [gameStarted, setGameStarted] = useState(false);
  const [gamePaused, setGamePaused] = useState(false);
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [ballPosition, setBallPosition] = useState({ x: 0, y: 0 });
  const [ballVelocity, setBallVelocity] = useState({ x: 5, y: 5 });
  const [paddlePosition, setPaddlePosition] = useState(0);
  const [opponentPosition, setOpponentPosition] = useState(0);
  const paddleHeight = 100;
  const paddleWidth = 15;
  const ballSize = 15;
  const gameWidth = 800;
  const gameHeight = 500;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Initial setup
    canvas.width = gameWidth;
    canvas.height = gameHeight;
    setBallPosition({ x: gameWidth / 2, y: gameHeight / 2 });

    // Mouse movement handler
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const relativeY = e.clientY - rect.top;
      setPaddlePosition(Math.min(Math.max(relativeY - paddleHeight / 2, 0), gameHeight - paddleHeight));
    };

    canvas.addEventListener('mousemove', handleMouseMove);

    return () => {
      canvas.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  useEffect(() => {
    if (!gameStarted || gamePaused) return;

    const gameLoop = setInterval(() => {
      // Update ball position
      setBallPosition(prev => ({
        x: prev.x + ballVelocity.x,
        y: prev.y + ballVelocity.y
      }));

      // Simple AI for opponent paddle
      setOpponentPosition(prev => {
        const targetY = ballPosition.y - paddleHeight / 2;
        return prev + (targetY - prev) * 0.1;
      });

      // Ball collision with walls
      if (ballPosition.y <= 0 || ballPosition.y >= gameHeight - ballSize) {
        setBallVelocity(prev => ({ ...prev, y: -prev.y }));
      }

      // Ball collision with paddles
      if (
        (ballPosition.x <= paddleWidth && 
         ballPosition.y + ballSize >= paddlePosition && 
         ballPosition.y <= paddlePosition + paddleHeight) ||
        (ballPosition.x >= gameWidth - paddleWidth - ballSize && 
         ballPosition.y + ballSize >= opponentPosition && 
         ballPosition.y <= opponentPosition + paddleHeight)
      ) {
        setBallVelocity(prev => ({ x: -prev.x, y: prev.y }));
        if (ballPosition.x <= paddleWidth) {
          setScore(prev => {
            const newScore = prev + 1;
            if (newScore > highScore) setHighScore(newScore);
            return newScore;
          });
        }
      }

      // Ball out of bounds
      if (ballPosition.x < 0 || ballPosition.x > gameWidth) {
        setGameStarted(false);
        setBallPosition({ x: gameWidth / 2, y: gameHeight / 2 });
        setBallVelocity({ x: 5 * (ballPosition.x < 0 ? 1 : -1), y: 5 });
      }

    }, 16);

    return () => clearInterval(gameLoop);
  }, [gameStarted, gamePaused, ballPosition, ballVelocity, paddlePosition, opponentPosition]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.clearRect(0, 0, gameWidth, gameHeight);

    // Draw background
    ctx.fillStyle = 'peachpuff';
    ctx.fillRect(0, 0, gameWidth, gameHeight);

    // Draw center line
    ctx.strokeStyle = 'firebrick';
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(gameWidth / 2, 0);
    ctx.lineTo(gameWidth / 2, gameHeight);
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw paddles
    ctx.fillStyle = 'firebrick';
    ctx.fillRect(0, paddlePosition, paddleWidth, paddleHeight);
    ctx.fillRect(gameWidth - paddleWidth, opponentPosition, paddleWidth, paddleHeight);

    // Draw ball
    ctx.beginPath();
    ctx.arc(ballPosition.x, ballPosition.y, ballSize, 0, Math.PI * 2);
    ctx.fillStyle = 'firebrick';
    ctx.fill();

    // Draw score
    ctx.font = '30px Arial';
    ctx.fillStyle = 'firebrick';
    ctx.textAlign = 'center';
    ctx.fillText(`${score}`, gameWidth / 4, 50);
    ctx.fillText(`${Math.floor(highScore)}`, (3 * gameWidth) / 4, 50);
  }, [ballPosition, paddlePosition, opponentPosition, score, highScore]);

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === ' ') {
      if (!gameStarted) {
        setGameStarted(true);
      } else {
        setGamePaused(!gamePaused);
      }
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameStarted, gamePaused]);

  const resetGame = () => {
    setGameStarted(false);
    setGamePaused(false);
    setScore(0);
    setBallPosition({ x: gameWidth / 2, y: gameHeight / 2 });
    setBallVelocity({ x: 5, y: 5 });
  };

  return (
    <div className="min-h-screen bg-peachpuff flex flex-col items-center justify-center p-4">
      <div className="flex items-center justify-between w-full max-w-4xl mb-4">
        <div className="flex items-center space-x-4">
          <Trophy className="text-firebrick" size={32} />
          <span className="text-2xl font-bold text-firebrick">High Score: {highScore}</span>
        </div>
        <div className="flex items-center space-x-4">
          {gameStarted ? (
            gamePaused ? (
              <button 
                onClick={() => setGamePaused(false)}
                className="bg-firebrick text-white p-2 rounded-full hover:bg-firebrick/90 transition"
              >
                <Play size={24} />
              </button>
            ) : (
              <button 
                onClick={() => setGamePaused(true)}
                className="bg-firebrick text-white p-2 rounded-full hover:bg-firebrick/90 transition"
              >
                <Pause size={24} />
              </button>
            )
          ) : (
            <button 
              onClick={() => setGameStarted(true)}
              className="bg-firebrick text-white p-2 rounded-full hover:bg-firebrick/90 transition"
            >
              <Play size={24} />
            </button>
          )}
          <button 
            onClick={resetGame}
            className="bg-firebrick text-white p-2 rounded-full hover:bg-firebrick/90 transition"
          >
            <RotateCcw size={24} />
          </button>
        </div>
      </div>

      <div className="relative">
        <canvas 
          ref={canvasRef}
          className="border-4 border-firebrick rounded-lg shadow-lg"
        />
        {!gameStarted && (
          <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-50 rounded-lg">
            <div className="text-white text-center p-4">
              <h2 className="text-3xl font-bold mb-4">Ping Pong Game</h2>
              <p className="mb-6">Use your mouse to move the paddle</p>
              <p className="mb-6">Press SPACE to start/pause</p>
              <button 
                onClick={() => setGameStarted(true)}
                className="bg-firebrick text-white px-6 py-2 rounded-lg hover:bg-firebrick/90 transition"
              >
                Start Game
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="mt-4 text-firebrick">
        <p>Current Score: {score}</p>
      </div>
    </div>
  );
};

export default PingPongGame;
</boltAction>

