<script setup lang="ts">
import { ref, computed } from 'vue'

const props = defineProps({
  quiz: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['quiz-completed'])

const currentQuestionIndex = ref(0)
const answers = ref([])
const totalScore = ref(0)

const currentQuestion = computed(() => {
  return props.quiz.questions[currentQuestionIndex.value]
})

const progress = computed(() => {
  return ((currentQuestionIndex.value + 1) / props.quiz.questions.length) * 100
})

function selectAnswer(option) {
  answers.value.push(option)
  totalScore.value += option.score

  if (currentQuestionIndex.value < props.quiz.questions.length - 1) {
    currentQuestionIndex.value++
  } else {
    emit('quiz-completed', {
      score: totalScore.value,
      answers: answers.value
    })
  }
}
</script>

<template>
  <div class="quiz">
    <div class="progress-bar">
      <div class="progress" :style="{ width: progress + '%' }"></div>
    </div>

    <h2>{{ quiz.title }}</h2>

    <div class="question">
      <h3>{{ currentQuestion.text }}</h3>
      <div class="options">
        <button
          v-for="option in currentQuestion.options"
          :key="option.id"
          @click="selectAnswer(option)"
        >
          {{ option.text }}
        </button>
      </div>
    </div>
  </div>
</template>

