import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xf0f0f0);
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('canvas') });
renderer.setSize(window.innerWidth, window.innerHeight);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
camera.position.set(0, 5, 10);
controls.update();

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040);
scene.add(ambientLight);
const directionalLight = new THREE.DirectionalLight(0xffffff, 0.5);
directionalLight.position.set(0, 1, 0);
scene.add(directionalLight);

// Grid helper
const gridHelper = new THREE.GridHelper(10, 10);
scene.add(gridHelper);

// Mesh collection
const meshes = [];

// Create a default mesh
function createDefaultMesh() {
  const geometry = new THREE.BoxGeometry(1, 1, 1);
  const material = new THREE.MeshStandardMaterial({ 
    color: mediumvioletred,
    metalness: 0.1,
    roughness: 0.5
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0.5, 0);
  scene.add(mesh);
  meshes.push(mesh);
  return mesh;
}

// Import from CSV
document.getElementById('importBtn').addEventListener('click', () => {
  document.getElementById('csvInput').click();
});

document.getElementById('csvInput').addEventListener('change', (event) => {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    const content = e.target.result;
    parseCSV(content);
  };
  reader.readAsText(file);
});

function parseCSV(csvData) {
  // Clear existing meshes
  meshes.forEach(mesh => scene.remove(mesh));
  meshes.length = 0;

  const lines = csvData.split('\n');
  lines.forEach((line, index) => {
    if (index === 0 || !line.trim()) return; // Skip header and empty lines

    const values = line.split(',');
    if (values.length >= 6) {
      const mesh = createDefaultMesh();
      mesh.position.set(
        parseFloat(values[0]),
        parseFloat(values[1]),
        parseFloat(values[2])
      );
      mesh.rotation.set(
        parseFloat(values[3]),
        parseFloat(values[4]),
        parseFloat(values[5])
      );
      if (values.length >= 7) {
        mesh.scale.set(
          parseFloat(values[6]),
          parseFloat(values[7]) || parseFloat(values[6]),
          parseFloat(values[8]) || parseFloat(values[6])
        );
      }
    }
  });
}

// Export to CSV
document.getElementById('exportBtn').addEventListener('click', () => {
  let csvContent = "x,y,z,rotationX,rotationY,rotationZ,scaleX,scaleY,scaleZ\n";

  meshes.forEach(mesh => {
    csvContent += `${mesh.position.x},${mesh.position.y},${mesh.position.z},`;
    csvContent += `${mesh.rotation.x},${mesh.rotation.y},${mesh.rotation.z},`;
    csvContent += `${mesh.scale.x},${mesh.scale.y},${mesh.scale.z}\n`;
  });

  const blob = new Blob([csvContent], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.setAttribute('hidden', '');
  a.setAttribute('href', url);
  a.setAttribute('download', 'mesh_data.csv');
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();

// Handle window resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// Create initial mesh
createDefaultMesh();
</boltAction>

