      title: "Cosmic Awakening",
      description: "The orb begins pulsating with energy",
      color: "bg-purple-700",
      image: "https://images.unsplash.com/photo-1534447677768-be436bb09401?w=800"
    },
    {
      title: "Galactic Expansion",
      description: "Energy waves ripple through the universe",
      color: "bg-purple-800",
      image: "https://images.unsplash.com/photo-1462331940025-496dfbfc7564?w=800"
    },
    {
      title: "New Worlds Form",
      description: "Planets begin to take shape from the energy",
      color: "bg-purple-900",
      image: "https://images.unsplash.com/photo-1454789548928-9a92b84a407d?w=800"
    },
    {
      title: "Life Emerges",
      description: "The first signs of life appear on the new worlds",
      color: "bg-fuchsia-900",
      image: "https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800"
    }
  ];

  const currentFrame = storyFrames[Math.floor(progress * (storyFrames.length - 1))];

  const animate = (timestamp: number) => {
    if (!startTimeRef.current) {
      startTimeRef.current = timestamp;
      lastTimeRef.current = timestamp;
    }

    const deltaTime = timestamp - lastTimeRef.current;
    lastTimeRef.current = timestamp;

    if (isPlaying) {
      setProgress(prev => {
        const newProgress = prev + (deltaTime * 0.0005 * speed);
        return newProgress > 1 ? 0 : newProgress;
      });
    }

    animationRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    animationRef.current = requestAnimationFrame(animate);
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, speed]);

  const togglePlayPause = () => setIsPlaying(!isPlaying);
  const increaseSpeed = () => setSpeed(prev => Math.min(prev + 0.5, 3));
  const decreaseSpeed = () => setSpeed(prev => Math.max(prev - 0.5, 0.5));

  return (
    <div className="min-h-screen bg-gradient-to-br from-orchid-300 to-orchid-500 p-8">
