          {/* Animation Display */}
          <div className="relative h-96">
            <div className={`absolute inset-0 ${currentFrame.color} transition-all duration-500 flex items-center justify-center`}>
              <img 
                src={currentFrame.image} 
                alt={currentFrame.title}
                className="w-full h-full object-cover opacity-70"
              />
              <div className="absolute inset-0 bg-black bg-opacity-40 flex flex-col items-center justify-center p-8 text-center">
                <h2 className="text-3xl font-bold text-white mb-2">{currentFrame.title}</h2>
                <p className="text-xl text-purple-100">{currentFrame.description}</p>
              </div>
            </div>
          </div>

          {/* Progress Bar */}
          <div className="h-2 bg-purple-200 relative">
            <div 
              className="h-full bg-purple-600 transition-all duration-300"
              style={{ width: `${progress * 100}%` }}
            />
          </div>

          {/* Controls */}
          <div className="p-6 flex items-center justify-between bg-purple-100">
            <div className="flex items-center space-x-4">
              <button 
                onClick={decreaseSpeed}
                className="p-2 rounded-full bg-purple-700 text-white hover:bg-purple-800 transition-colors"
              >
                <Rewind size={24} />
              </button>
              <button 
                onClick={togglePlayPause}
                className="p-4 rounded-full bg-purple-800 text-white hover:bg-purple-900 transition-colors"
              >
                {isPlaying ? <Pause size={32} /> : <Play size={32} />}
              </button>
              <button 
                onClick={increaseSpeed}
                className="p-2 rounded-full bg-purple-700 text-white hover:bg-purple-800 transition-colors"
              >
                <FastForward size={24} />
              </button>
            </div>
            <div className="text-purple-900 font-medium">
              Speed: {speed}x
            </div>
          </div>
        </div>

        <div className="mt-8 grid grid-cols-1 md:grid-cols-5 gap-4">
          {storyFrames.map((frame, index) => (
            <button
              key={index}
              onClick={() => setProgress(index / (storyFrames.length - 1))}
              className={`p-4 rounded-lg ${frame.color} text-white text-center hover:opacity-90 transition-opacity`}
            >
              {frame.title}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default MotionGraphicsPlayer;
