import { useState, useRef, useEffect } from 'react';
import { generatePlatforms, PlatformType } from './platformUtils';
import { generatePowerUps, PowerUpType } from './powerUpUtils';
import { playJumpSound, playPowerUpSound, playGameOverSound } from './sounds';

const GRAVITY = 0.2;
const JUMP_FORCE = 10;
const SCROLL_THRESHOLD = 200;

export const useGame = () => {
  const [playerY, setPlayerY] = useState(400);
  const [playerVelocity, setPlayerVelocity] = useState(0);
  const [platforms, setPlatforms] = useState<PlatformType[]>([]);
  const [powerUps, setPowerUps] = useState<PowerUpType[]>([]);
  const [score, setScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [gameOver, setGameOver] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [leaderboard, setLeaderboard] = useState<{name: string, score: number}[]>([]);

  const playerRef = useRef<HTMLDivElement>(null);
  const gameAreaRef = useRef<HTMLDivElement>(null);
  const animationFrameId = useRef<number>();

  const startGame = () => {
    setPlayerY(400);
    setPlayerVelocity(0);
    setScore(0);
    setLevel(1);
    setGameOver(false);
    setPlatforms(generatePlatforms(10, 800, 1));
    setPowerUps(generatePowerUps(3, 800, 1));
  };

  const jump = () => {
    if (gameOver || isPaused) return;
    setPlayerVelocity(-JUMP_FORCE);
    playJumpSound();
  };

  const togglePause = () => {
    setIsPaused(!isPaused);
  };

  const checkCollisions = () => {
    // Platform collisions
    platforms.forEach(platform => {
      if (
        playerY + 50 >= platform.y &&
        playerY + 50 <= platform.y + 15 &&
        playerVelocity > 0 &&
        playerRef.current &&
        playerRef.current.offsetLeft + 30 >= platform.x &&
        playerRef.current.offsetLeft <= platform.x + 70
      ) {
        setPlayerVelocity(-JUMP_FORCE);
        playJumpSound();

        if (platform.isBreakable) {
          setPlatforms(prev => prev.filter(p => p !== platform));
        }
      }
    });

    // Power-up collisions
    powerUps.forEach(powerUp => {
      if (
        playerRef.current &&
        playerRef.current.offsetLeft + 30 >= powerUp.x &&
        playerRef.current.offsetLeft <= powerUp.x + 30 &&
        playerY + 50 >= powerUp.y &&
        playerY <= powerUp.y + 30
      ) {
        setPowerUps(prev => prev.filter(p => p !== powerUp));
        playPowerUpSound();

        switch(powerUp.type) {
          case 'spring':
            setPlayerVelocity(-JUMP_FORCE * 1.5);
            break;
          case 'rocket':
            setPlayerVelocity(-JUMP_FORCE * 2);
            break;
          case 'score':
            setScore(prev => prev + 500);
            break;
        }
      }
    });
  };

  const updateGame = () => {
    if (isPaused) return;

    // Apply gravity
    setPlayerVelocity(prev => prev + GRAVITY);
    setPlayerY(prev => prev + playerVelocity);

    // Check if player fell off screen
    if (playerY > 800) {
      setGameOver(true);
      playGameOverSound();
      setLeaderboard(prev => [...prev, {name: 'Player', score}].sort((a,b) => b.score - a.score).slice(0,5));
      return;
    }

    // Scroll screen up when player reaches threshold
    if (playerY < SCROLL_THRESHOLD) {
      const scrollAmount = SCROLL_THRESHOLD - playerY;
      setPlayerY(SCROLL_THRESHOLD);
      setScore(prev => prev + Math.floor(scrollAmount));

      // Move platforms down
      setPlatforms(prev => 
        prev.map(platform => ({
          ...platform,
          y: platform.y + scrollAmount
        })).filter(platform => platform.y < 800)
      );

      // Move power-ups down
      setPowerUps(prev => 
        prev.map(powerUp => ({
          ...powerUp,
          y: powerUp.y + scrollAmount
        })).filter(powerUp => powerUp.y < 800)
      );

      // Add new platforms and power-ups
      if (platforms.length < 8) {
        setPlatforms(prev => [...prev, ...generatePlatforms(2, 800, level)]);
      }
      if (powerUps.length < 2) {
        setPowerUps(prev => [...prev, ...generatePowerUps(1, 800, level)]);
      }
    }

    checkCollisions();
    animationFrameId.current = requestAnimationFrame(updateGame);
  };

  useEffect(() => {
    startGame();
    return () => {
      if (animationFrameId.current) {
        cancelAnimationFrame(animationFrameId.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!gameOver && !isPaused) {
      animationFrameId.current = requestAnimationFrame(updateGame);
    }
    return () => {
      if (animationFrameId.current) {
        cancelAnimationFrame(animationFrameId.current);
      }
    };
  }, [gameOver, isPaused]);

  // Level progression
  useEffect(() => {
    if (score > level * 2000) {
      setLevel(prev => prev + 1);
    }
  }, [score]);

  return {
    playerRef,
    platforms,
    powerUps,
    score,
    level,
    gameOver,
    jump,
    startGame,
    isPaused,
    togglePause,
    leaderboard
  };
};
