export interface PowerUpType {
  x: number;
  y: number;
  type: 'spring' | 'rocket' | 'score';
}

export const generatePowerUps = (count: number, maxY: number, level: number): PowerUpType[] => {
  const powerUps: PowerUpType[] = [];
  const types: ('spring' | 'rocket' | 'score')[] = ['spring', 'rocket', 'score'];

  for (let i = 0; i < count; i++) {
    const x = Math.random() * 300 + 50;
    const y = Math.random() * (maxY - 100) + 50;
    const type = types[Math.floor(Math.random() * types.length)];

    // Increase chance of power-ups at higher levels
    if (Math.random() < 0.3 + (level * 0.05)) {
      powerUps.push({ x, y, type });
    }
  }

  return powerUps;
};
