export const generatePlatforms = (count: number, maxY: number, level: number) => {
  const platforms = [];
  const platformTypes = ['normal', 'moving', 'breakable'];

  // Starting platform
  platforms.push({
    x: 150,
    y: maxY - 100,
    width: 100,
    type: 'normal'
  });

  for (let i = 0; i < count; i++) {
    const x = Math.random() * 300;
    const y = Math.random() * (maxY - 200) + 50;
    const width = Math.random() * 50 + 70;

    // Higher levels have more moving and breakable platforms
    let typeIndex = 0;
    const rand = Math.random();
    if (rand < 0.1 + (level * 0.05)) typeIndex = 2;
    else if (rand < 0.3 + (level * 0.05)) typeIndex = 1;

    platforms.push({
      x,
      y,
      width,
      type: platformTypes[typeIndex] as 'normal' | 'moving' | 'breakable'
    });
  }

  return platforms;
};
