import React, { createContext, useContext, useState, useEffect } from 'react';

type Player = {
  id: string;
  name: string;
  health: number;
  score: number;
  level: number;
  position: { x: number; y: number };
};

type GameState = {
  players: Player[];
  currentLevel: number;
  gameStarted: boolean;
  winner: Player | null;
};

type GameContextType = {
  gameState: GameState;
  joinGame: (name: string) => void;
  attack: (targetId: string) => void;
  move: (direction: 'up'|'down'|'left'|'right') => void;
  startGame: () => void;
  nextLevel: () => void;
};

const GameContext = createContext<GameContextType | undefined>(undefined);

export const GameProvider: React.FC<{children: React.ReactNode}> = ({ children }) => {
  const [gameState, setGameState] = useState<GameState>({
    players: [],
    currentLevel: 1,
    gameStarted: false,
    winner: null
  });

  const joinGame = (name: string) => {
    const newPlayer: Player = {
      id: Math.random().toString(36).substring(7),
      name,
      health: 100,
      score: 0,
      level: 1,
      position: { x: Math.floor(Math.random() * 5), y: Math.floor(Math.random() * 5) }
    };
    setGameState(prev => ({
      ...prev,
      players: [...prev.players, newPlayer]
    }));
  };

  const attack = (targetId: string) => {
    setGameState(prev => {
      const updatedPlayers = [...prev.players];
      const targetIndex = updatedPlayers.findIndex(p => p.id === targetId);

      if (targetIndex !== -1) {
        updatedPlayers[targetIndex].health -= 10;

        // Find attacker (first player for simplicity)
        if (updatedPlayers[0]) {
          updatedPlayers[0].score += 10;

          // Check if target is defeated
          if (updatedPlayers[targetIndex].health <= 0) {
            updatedPlayers[0].score += 50;
            updatedPlayers.splice(targetIndex, 1);

            // Check if game is won
            if (updatedPlayers.length === 1) {
              return {
                ...prev,
                players: updatedPlayers,
                winner: updatedPlayers[0]
              };
            }
          }
        }
      }

      return { ...prev, players: updatedPlayers };
    });
  };

  const move = (direction: 'up'|'down'|'left'|'right') => {
    setGameState(prev => {
      if (!prev.players.length) return prev;

      const updatedPlayers = [...prev.players];
      const player = updatedPlayers[0];

      switch (direction) {
        case 'up': player.position.y = Math.max(0, player.position.y - 1); break;
        case 'down': player.position.y = Math.min(4, player.position.y + 1); break;
        case 'left': player.position.x = Math.max(0, player.position.x - 1); break;
        case 'right': player.position.x = Math.min(4, player.position.x + 1); break;
      }

      return { ...prev, players: updatedPlayers };
    });
  };

  const startGame = () => {
    setGameState(prev => ({ ...prev, gameStarted: true }));
  };

  const nextLevel = () => {
    setGameState(prev => {
      const newLevel = prev.currentLevel + 1;
      const leveledPlayers = prev.players.map(p => ({
        ...p,
        level: newLevel,
        health: 100,
        position: { x: Math.floor(Math.random() * 5), y: Math.floor(Math.random() * 5) }
      }));

      return {
        ...prev,
        currentLevel: newLevel,
        players: leveledPlayers,
        winner: null
      };
    });
  };

  return (
    <GameContext.Provider value={{ gameState, joinGame, attack, move, startGame, nextLevel }}>
      {children}
    </GameContext.Provider>
  );
};

export const useGame = () => {
  const context = useContext(GameContext);
  if (!context) {
    throw new Error('useGame must be used within a GameProvider');
  }
  return context;
};
