      if (gameState !== 'playing') return;

      if (e.key === 'ArrowUp') {
        setPlane(prev => ({ ...prev, y: Math.max(prev.y - 15, 0) }));
      } else if (e.key === 'ArrowDown') {
        setPlane(prev => ({ ...prev, y: Math.min(prev.y + 15, 500 - prev.height) }));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState]);

  // Game loop
  useEffect(() => {
    if (gameState !== 'playing') return;

    const gameLoop = setInterval(() => {
      // Move background
      setBackgroundPos(prev => (prev + 1) % 800);

      // Generate obstacles
      if (Math.random() < 0.02) {
        const height = Math.floor(Math.random() * 150) + 50;
        setObstacles(prev => [
          ...prev,
          { x: 800, y: Math.random() > 0.5 ? 0 : 500 - height, width: 30, height }
        ]);
      }

      // Move obstacles
      setObstacles(prev => 
        prev.map(obs => ({ ...obs, x: obs.x - 3 }))
          .filter(obs => obs.x > -30)
      );

      // Check collisions
      const collision = obstacles.some(obs => 
        plane.x < obs.x + obs.width &&
        plane.x + plane.width > obs.x &&
        plane.y < obs.y + obs.height &&
        plane.y + plane.height > obs.y
      );

      if (collision) {
        setGameState('gameover');
        setLeaderboard(prev => [...prev, { username, score }].sort((a, b) => b.score - a.score).slice(0, 10));
      } else {
        setScore(prev => prev + 1);
      }
    }, 30);

    return () => clearInterval(gameLoop);
  }, [gameState, obstacles, plane]);

  // Draw game
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, 800, 500);

    // Draw melon background
    ctx.fillStyle = '#f0f7d4';
    ctx.fillRect(0, 0, 800, 500);

    // Draw clouds
    ctx.fillStyle = '#ffffff80';
    for (let i = 0; i < 5; i++) {
      const x = (backgroundPos + i * 200) % 800;
      ctx.beginPath();
      ctx.arc(x, 100, 30, 0, Math.PI * 2);
      ctx.arc(x + 20, 90, 25, 0, Math.PI * 2);
      ctx.arc(x + 40, 100, 30, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw tomato-colored plane
    ctx.fillStyle = '#ff6347';
    ctx.beginPath();
    ctx.moveTo(plane.x, plane.y + plane.height / 2);
    ctx.lineTo(plane.x + plane.width, plane.y);
    ctx.lineTo(plane.x + plane.width, plane.y + plane.height);
    ctx.closePath();
    ctx.fill();

    // Draw tomato-colored obstacles
    ctx.fillStyle = '#ff6347';
    obstacles.forEach(obs => {
      ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
    });

    // Draw score
    ctx.fillStyle = '#333';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 20, 30);
  }, [plane, obstacles, backgroundPos, score]);

  const handleLogin = (e) => {
    e.preventDefault();
    if (username.trim()) {
      setGameState('playing');
    }
  };

  const resetGame = () => {
    setScore(0);
    setPlane({ x: 50, y: 250, width: 60, height: 30 });
    setObstacles([]);
    setGameState('playing');
  };

  return (
    <div className="min-h-screen bg-[#f0f7d4] flex flex-col items-center justify-center p-4">
      {gameState === 'login' && (
        <div className="bg-white p-8 rounded-lg shadow-lg max-w-md w-full">
          <h1 className="text-3xl font-bold text-[#ff6347] mb-6">Aviator Game</h1>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label htmlFor="username" className="block text-sm font-medium text-gray-700">
                Enter your name
              </label>
              <input
                type="text"
                id="username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#ff6347] focus:border-[#ff6347]"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full flex justify-center items-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-[#ff6347] hover:bg-[#e55337] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#ff6347]"
            >
              <LogIn size={16} /> Start Game
            </button>
          </form>
        </div>
      )}

      {gameState !== 'login' && (
        <div className="flex flex-col items-center">
          <canvas
            ref={canvasRef}
            width={800}
            height={500}
            className="border-4 border-[#ff6347] rounded-lg shadow-lg mb-4"
          />

          <div className="flex gap-4 mt-4">
            {gameState === 'playing' && (
              <button
                onClick={() => setGameState('paused')}
                className="flex items-center gap-2 px-4 py-2 bg-[#ff6347] text-white rounded-lg shadow hover:bg-[#e55337]"
              >
                <Pause size={16} /> Pause
              </button>
            )}

            {gameState === 'paused' && (
