import { useState, useEffect } from 'react'
import { Trophy, Clock, RotateCw, Home } from 'lucide-react'
import GameBoard from './components/GameBoard'
import Leaderboard from './components/Leaderboard'

type GameState = 'menu' | 'playing' | 'gameOver'

const CARD_PAIRS = 8
const SYMBOLS = ['🍎', '🍊', '🍋', '🍉', '🍇', '🍓', '🍒', '🍑']

function App() {
  const [gameState, setGameState] = useState<GameState>('menu')
  const [score, setScore] = useState(0)
  const [time, setTime] = useState(0)
  const [leaderboard, setLeaderboard] = useState<{name: string, score: number, time: number}[]>([])

  useEffect(() => {
    let interval: NodeJS.Timeout
    if (gameState === 'playing') {
      interval = setInterval(() => {
        setTime(prev => prev + 1)
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [gameState])

  const startGame = () => {
    setGameState('playing')
    setScore(0)
    setTime(0)
  }

  const endGame = (finalScore: number) => {
    setGameState('gameOver')
    setScore(finalScore)
  }

  const addToLeaderboard = (name: string) => {
    const newEntry = { name, score, time }
    setLeaderboard(prev => [...prev, newEntry].sort((a, b) => b.score - a.score || a.time - b.time).slice(0, 10))
    setGameState('menu')
  }

  return (
    <div className="min-h-screen bg-[#F7E7CE] flex flex-col items-center justify-center p-4">
      <h1 className="text-4xl font-bold mb-8 text-firebrick">Memory Match</h1>

      {gameState === 'menu' && (
        <div className="flex flex-col items-center gap-6">
          <button 
            onClick={startGame}
            className="px-6 py-3 bg-firebrick text-white rounded-lg font-bold text-lg hover:bg-[#B22222] transition"
          >
            Start Game
          </button>
          {leaderboard.length > 0 && <Leaderboard entries={leaderboard} />}
        </div>
      )}

      {gameState === 'playing' && (
        <div className="flex flex-col items-center gap-4">
          <div className="flex gap-8 mb-4">
            <div className="flex items-center gap-2 text-firebrick">
              <Trophy size={24} />
              <span className="font-bold">Score: {score}</span>
            </div>
            <div className="flex items-center gap-2 text-firebrick">
              <Clock size={24} />
              <span className="font-bold">Time: {time}s</span>
            </div>
          </div>
          <GameBoard 
            pairs={CARD_PAIRS} 
            symbols={SYMBOLS} 
            onScoreUpdate={setScore}
            onGameEnd={endGame}
          />
        </div>
      )}

      {gameState === 'gameOver' && (
        <div className="flex flex-col items-center gap-6">
          <h2 className="text-2xl font-bold text-firebrick">Game Over!</h2>
          <p className="text-lg">Your score: {score}</p>
          <p className="text-lg">Time: {time} seconds</p>
          <form 
            onSubmit={(e) => {
              e.preventDefault()
              const name = (e.currentTarget.elements.namedItem('name') as HTMLInputElement).value
              addToLeaderboard(name)
            }}
            className="flex flex-col gap-4 items-center"
          >
            <input
              type="text"
              name="name"
              placeholder="Your name"
              required
              className="px-4 py-2 rounded border border-firebrick"
            />
            <button 
              type="submit"
              className="px-6 py-2 bg-firebrick text-white rounded-lg font-bold hover:bg-[#B22222] transition"
            >
              Save Score
            </button>
          </form>
        </div>
      )}

      {(gameState === 'playing' || gameState === 'gameOver') && (
        <button 
          onClick={() => setGameState('menu')}
          className="mt-6 flex items-center gap-2 text-firebrick hover:underline"
        >
          <Home size={18} />
          Back to Menu
        </button>
      )}
    </div>
  )
}

export default App
