<boltAction type="file" filePath="src/components/GameBoard.tsx">
import { useState, useEffect } from 'react'

type Card = {
  id: number
  symbol: string
  isFlipped: boolean
  isMatched: boolean
}

type GameBoardProps = {
  pairs: number
  symbols: string[]
  onScoreUpdate: (score: number) => void
  onGameEnd: (score: number) => void
}

export default function GameBoard({ pairs, symbols, onScoreUpdate, onGameEnd }: GameBoardProps) {
  const [cards, setCards] = useState<Card[]>([])
  const [flippedCards, setFlippedCards] = useState<number[]>([])
  const [moves, setMoves] = useState(0)
  const [matchedPairs, setMatchedPairs] = useState(0)

  useEffect(() => {
    initializeGame()
  }, [])

  const initializeGame = () => {
    const selectedSymbols = symbols.slice(0, pairs)
    const cardPairs = [...selectedSymbols, ...selectedSymbols]
    const shuffledCards = shuffleArray(cardPairs)

    setCards(shuffledCards.map((symbol, index) => ({
      id: index,
      symbol,
      isFlipped: false,
      isMatched: false
    })))
    setFlippedCards([])
    setMoves(0)
    setMatchedPairs(0)
    onScoreUpdate(0)
  }

  const shuffleArray = (array: string[]) => {
    const newArray = [...array]
    for (let i = newArray.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[newArray[i], newArray[j]] = [newArray[j], newArray[i]]
    }
    return newArray
  }

  const flipCard = (id: number) => {
    if (flippedCards.length >= 2 || cards.find(card => card.id === id)?.isFlipped) return

    const newCards = cards.map(card => 
      card.id === id ? { ...card, isFlipped: true } : card
    )
    setCards(newCards)
    setFlippedCards(prev => [...prev, id])
    setMoves(prev => prev + 1)
  }

  useEffect(() => {
    if (flippedCards.length === 2) {
      const [firstId, secondId] = flippedCards
      const firstCard = cards.find(card => card.id === firstId)
      const secondCard = cards.find(card => card.id === secondId)

      if (firstCard?.symbol === secondCard?.symbol) {
        const newCards = cards.map(card => 
          card.id === firstId || card.id === secondId 
            ? { ...card, isMatched: true } 
            : card
        )
        setCards(newCards)
        setMatchedPairs(prev => prev + 1)
        onScoreUpdate(matchedPairs + 1)
      }

      setTimeout(() => {
        const newCards = cards.map(card => 
          !card.isMatched && (card.id === firstId || card.id === secondId)
            ? { ...card, isFlipped: false }
            : card
        )
        setCards(newCards)
        setFlippedCards([])
      }, 1000)
    }
  }, [flippedCards])

  useEffect(() => {
    if (matchedPairs === pairs) {
      setTimeout(() => {
        onGameEnd(matchedPairs * 100 - moves * 2)
      }, 500)
    }
  }, [matchedPairs])

  return (
    <div className="grid grid-cols-4 gap-4">
      {cards.map(card => (
        <div 
          key={card.id}
          onClick={() => flipCard(card.id)}
          className={`w-20 h-20 flex items-center justify-center text-4xl cursor-pointer rounded-lg transition-all duration-300 transform ${card.isFlipped ? 'rotate-y-180' : ''} ${
            card.isFlipped || card.isMatched 
              ? 'bg-white shadow-md' 
              : 'bg-firebrick hover:bg-[#B22222]'
          }`}
          style={{
            transform: card.isFlipped ? 'rotateY(180deg)' : 'rotateY(0deg)',
            backfaceVisibility: 'hidden'
          }}
        >
          {(card.isFlipped || card.isMatched) && card.symbol}
        </div>
      ))}
    </div>
  )
}
