<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { io } from 'socket.io-client'

const socket = io('http://localhost:3000')
const messages = ref<Array<{user: string, text: string, timestamp: Date}>>([])
const newMessage = ref('')
const currentUser = localStorage.getItem('username') || 'Anonymous'
const activeUsers = ref<string[]>([])
const groups = ref<Array<{id: string, name: string}>>([])
const currentGroup = ref('general')

onMounted(() => {
  socket.emit('join', { user: currentUser, group: currentGroup.value })

  socket.on('message', (message) => {
    messages.value.push(message)
  })

  socket.on('activeUsers', (users) => {
    activeUsers.value = users
  })

  socket.on('groups', (groupList) => {
    groups.value = groupList
  })
})

onUnmounted(() => {
  socket.off('message')
  socket.off('activeUsers')
  socket.off('groups')
})

const sendMessage = () => {
  if (newMessage.value.trim()) {
    socket.emit('message', {
      user: currentUser,
      text: newMessage.value,
      group: currentGroup.value
    })
    newMessage.value = ''
  }
}

const createGroup = (groupName: string) => {
  if (groupName.trim()) {
    socket.emit('createGroup', groupName)
  }
}

const joinGroup = (groupId: string) => {
  socket.emit('joinGroup', { user: currentUser, groupId })
  currentGroup.value = groupId
  messages.value = []
}
</script>

