<boltAction type="file" filePath="server.js">
import { Server } from 'socket.io'

const io = new Server(3000, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
})

const groups = [
  { id: 'general', name: 'General Chat' },
  { id: 'random', name: 'Random' }
]

io.on('connection', (socket) => {
  let currentUser = ''
  let currentGroup = 'general'

  socket.on('join', ({ user, group }) => {
    currentUser = user
    currentGroup = group
    socket.join(group)
    updateActiveUsers()
    socket.emit('groups', groups)
  })

  socket.on('message', (message) => {
    io.to(currentGroup).emit('message', {
      user: currentUser,
      text: message.text,
      timestamp: new Date()
    })
  })

  socket.on('createGroup', (groupName) => {
    const newGroup = {
      id: groupName.toLowerCase().replace(/\s+/g, '-'),
      name: groupName
    }
    groups.push(newGroup)
    io.emit('groups', groups)
  })

  socket.on('joinGroup', ({ user, groupId }) => {
    socket.leave(currentGroup)
    currentGroup = groupId
    socket.join(groupId)
    updateActiveUsers()
  })

  socket.on('disconnect', () => {
    updateActiveUsers()
  })

  function updateActiveUsers() {
    const room = io.sockets.adapter.rooms.get(currentGroup)
    const users = []
    if (room) {
      for (const socketId of room) {
        const socket = io.sockets.sockets.get(socketId)
        if (socket && socket.handshake.query.user) {
          users.push(socket.handshake.query.user)
        }
      }
    }
    io.to(currentGroup).emit('activeUsers', users)
  }
})
</boltAction>

