import { defineStore } from 'pinia'
import { ref } from 'vue'

interface Message {
  id: string
  chatId: string
  content: string
  type: 'text' | 'image' | 'video'
  timestamp: Date
}

export const useMessageStore = defineStore('messages', () => {
  const messages = ref<Record<string, Message[]>>({})
  const ws = ref<WebSocket | null>(null)

  function connect() {
    ws.value = new WebSocket('wss://echo.websocket.org')

    ws.value.onmessage = (event) => {
      const message = JSON.parse(event.data)
      if (!messages.value[message.chatId]) {
        messages.value[message.chatId] = []
      }
      messages.value[message.chatId].push(message)
    }
  }

  function sendMessage(message: Omit<Message, 'id'>) {
    if (ws.value) {
      const msgWithId = {
        ...message,
        id: Date.now().toString()
      }
      ws.value.send(JSON.stringify(msgWithId))

      // Add to local state immediately
      if (!messages.value[message.chatId]) {
        messages.value[message.chatId] = []
      }
      messages.value[message.chatId].push(msgWithId)
    }
  }

  function loadMessages(chatId: string) {
    // In a real app, this would load from IndexedDB or API
    if (!messages.value[chatId]) {
      messages.value[chatId] = []
    }
  }

  return {
    messages,
    connect,
    sendMessage,
    loadMessages
  }
})
