<script setup lang="ts">
import { ref } from 'vue'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const friends = ref([...props.user.friends])
const selectedFriends = ref<string[]>([])

const toggleFriendSelection = (friendId: string) => {
  const index = selectedFriends.value.indexOf(friendId)
  if (index === -1) {
    selectedFriends.value.push(friendId)
  } else {
    selectedFriends.value.splice(index, 1)
  }
}

const unfriendSelected = () => {
  if (confirm(`Are you sure you want to unfriend ${selectedFriends.value.length} friends?`)) {
    friends.value = friends.value.filter(friend => !selectedFriends.value.includes(friend.id))
    selectedFriends.value = []
  }
}
</script>

<template>
