<script setup>
import { ref, onMounted } from 'vue'
import { db } from '../firebase'
import { ref as dbRef, onValue, push, set } from 'firebase/database'

const messages = ref([])
const newMessage = ref('')
const groups = ref([])
const selectedGroup = ref('general')

const sendMessage = () => {
  if (!newMessage.value.trim()) return

  const messagesRef = dbRef(db, `groups/${selectedGroup.value}/messages`)
  const newMessageRef = push(messagesRef)
  set(newMessageRef, {
    text: newMessage.value,
    timestamp: Date.now(),
    sender: 'User'
  })

  newMessage.value = ''
}

onMounted(() => {
  const groupsRef = dbRef(db, 'groups')
  onValue(groupsRef, (snapshot) => {
    groups.value = Object.keys(snapshot.val() || {})
  })

  const messagesRef = dbRef(db, `groups/${selectedGroup.value}/messages`)
  onValue(messagesRef, (snapshot) => {
    const data = snapshot.val() || {}
    messages.value = Object.values(data)
  })
})
</script>

<template>
