<script setup lang="ts">
import { ref, onMounted } from 'vue'
import NoteComposer from './NoteComposer.vue'
import NotesList from './NotesList.vue'

const props = defineProps<{
  currentUser: string
}>()

const activeTab = ref('received')
const showComposer = ref(false)

const notes = ref<{
  id: string
  sender: string
  recipient: string
  message: string
  date: string
  read: boolean
}[]>([])

onMounted(() => {
  const savedNotes = localStorage.getItem('loveNotes')
  if (savedNotes) {
    notes.value = JSON.parse(savedNotes)
  }
})

const saveNote = (recipient: string, message: string) => {
  const newNote = {
    id: Date.now().toString(),
    sender: props.currentUser,
    recipient,
    message,
    date: new Date().toLocaleString(),
    read: false
  }

  notes.value.push(newNote)
  localStorage.setItem('loveNotes', JSON.stringify(notes.value))
  showComposer.value = false
}

const markAsRead = (id: string) => {
  const note = notes.value.find(n => n.id === id)
  if (note) note.read = true
  localStorage.setItem('loveNotes', JSON.stringify(notes.value))
}
</script>

<template>
  <div class="dashboard">
    <div class="header">
      <h2>Welcome, {{ currentUser }}!</h2>
      <button @click="showComposer = true">New Love Note</button>
    </div>

    <div class="tabs">
      <button 
        @click="activeTab = 'received'" 
        :class="{ active: activeTab === 'received' }"
      >
        Received
      </button>
      <button 
        @click="activeTab = 'sent'" 
        :class="{ active: activeTab === 'sent' }"
      >
        Sent
      </button>
    </div>

    <NoteComposer 
      v-if="showComposer" 
      @save="saveNote" 
      @cancel="showComposer = false"
    />

    <NotesList 
      :notes="activeTab === 'received' 
        ? notes.filter(n => n.recipient === currentUser) 
        : notes.filter(n => n.sender === currentUser)"
      :type="activeTab"
      @read="markAsRead"
    />
  </div>
</template>

