<boltAction type="file" filePath="server.js">import { Server } from 'socket.io'

const io = new Server(3000, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"]
  }
})

const users = {}

io.on('connection', (socket) => {
  console.log('a user connected')

  socket.on('join', ({ user, room }) => {
    socket.join(room)
    users[socket.id] = { user, room }
    socket.to(room).emit('message', { user: 'System', text: `${user} has joined` })
  })

  socket.on('message', ({ user, text, room }) => {
    io.to(room).emit('message', { user, text })
  })

  socket.on('disconnect', () => {
    const userData = users[socket.id]
    if (userData) {
      io.to(userData.room).emit('message', { 
        user: 'System', 
        text: `${userData.user} has left` 
      })
      delete users[socket.id]
    }
  })
})

console.log('Socket.IO server running on port 3000')</boltAction>

