<boltArtifact id="real-time-chat-app" title="Real-time Chat Application">
<boltAction type="file" filePath="src/App.tsx">
import React, { useState, useEffect, useRef } from 'react'
import { Send, AlertCircle, Loader2 } from 'lucide-react'
import { toast, Toaster } from 'react-hot-toast'

interface Message {
  id: string
  text: string
  sender: 'user' | 'other'
  timestamp: Date
}

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([])
  const [inputValue, setInputValue] = useState('')
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const ws = useRef<WebSocket | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    // Simulate WebSocket connection
    const connect = () => {
      setIsLoading(true)
      try {
        // In a real app, this would be your WebSocket server URL
        ws.current = new WebSocket('wss://echo.websocket.org')

        ws.current.onopen = () => {
          setIsConnected(true)
          setIsLoading(false)
          toast.success('Connected to chat server')
        }

        ws.current.onmessage = (event) => {
          const newMessage: Message = {
            id: Date.now().toString(),
            text: event.data,
            sender: 'other',
            timestamp: new Date()
          }
          setMessages(prev => [...prev, newMessage])
        }

        ws.current.onerror = (error) => {
          console.error('WebSocket error:', error)
          toast.error('Connection error occurred')
          setIsConnected(false)
          setIsLoading(false)
        }

        ws.current.onclose = () => {
          setIsConnected(false)
          toast.error('Disconnected from server')
          // Attempt to reconnect after 3 seconds
          setTimeout(connect, 3000)
        }

      } catch (error) {
        console.error('WebSocket connection error:', error)
        toast.error('Failed to connect to server')
        setIsConnected(false)
        setIsLoading(false)
      }
    }

    connect()

    return () => {
      if (ws.current) {
        ws.current.close()
      }
    }
  }, [])

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSendMessage = () => {
    if (!inputValue.trim()) return

    if (!isConnected) {
      toast.error('Not connected to server')
      return
    }

    try {
      const newMessage: Message = {
        id: Date.now().toString(),
        text: inputValue,
        sender: 'user',
        timestamp: new Date()
      }

      setMessages(prev => [...prev, newMessage])
      ws.current?.send(inputValue)
      setInputValue('')
    } catch (error) {
      console.error('Error sending message:', error)
      toast.error('Failed to send message')
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  return (
    <div className="min-h-screen bg-pale-goldenrod flex flex-col">
      <Toaster position="top-right" />
      <header className="bg-dark-khaki p-4 shadow-md">
        <div className="container mx-auto flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Real-Time Chat</h1>
          <div className="flex items-center gap-2">
            <div className={`w-3 h-3 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}></div>
            <span className="text-white">
              {isConnected ? 'Connected' : 'Disconnected'}
            </span>
            {isLoading && <Loader2 className="animate-spin text-white" />}
          </div>
        </div>
      </header>

      <main className="flex-1 container mx-auto p-4 overflow-hidden flex flex-col">
        <div className="flex-1 overflow-y-auto mb-4 rounded-lg bg-white bg-opacity-80 p-4 shadow-inner">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-500">
              <AlertCircle size={48} className="mb-4" />
              <p>No messages yet. Start chatting!</p>
            </div>
          ) : (
            messages.map((message) => (
              <div
                key={message.id}
                className={`mb-3 flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-xs md:max-w-md lg:max-w-lg rounded-lg p-3 ${message.sender === 'user' ? 'bg-dark-khaki text-white' : 'bg-gray-200 text-gray-800'}`}
                >
                  <p>{message.text}</p>
                  <p className={`text-xs mt-1 ${message.sender === 'user' ? 'text-white text-opacity-70' : 'text-gray-500'}`}>
                    {message.timestamp.toLocaleTimeString()}
                  </p>
                </div>
              </div>
            ))
          )}
          <div ref={messagesEndRef} />
        </div>

        <div className="flex gap-2">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message..."
            className="flex-1 p-3 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-dark-khaki"
            disabled={!isConnected}
          />
          <button
            onClick={handleSendMessage}
            disabled={!inputValue.trim() || !isConnected}
            className="bg-dark-khaki text-white p-3 rounded-lg hover:bg-opacity-90 disabled:opacity-50 flex items-center justify-center"
          >
            <Send size={20} />
          </button>
        </div>
      </main>
    </div>
  )
}

export default App
</boltAction>

