<script setup lang="ts">
import { ref, onMounted } from 'vue'

const videoRef = ref<HTMLVideoElement | null>(null)
const audioRef = ref<HTMLAudioElement | null>(null)
const currentVideo = ref('')
const currentAudio = ref('')
const isPlaying = ref(false)
const volume = ref(0.7)

const videos = [
  { title: 'Sample Video 1', src: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4' },
  { title: 'Sample Video 2', src: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4' }
]

const audios = [
  { title: 'Sample Audio 1', src: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3' },
  { title: 'Sample Audio 2', src: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3' }
]

onMounted(() => {
  if (videos.length > 0) currentVideo.value = videos[0].src
  if (audios.length > 0) currentAudio.value = audios[0].src
})

const togglePlay = () => {
  if (videoRef.value && audioRef.value) {
    if (isPlaying.value) {
      videoRef.value.pause()
      audioRef.value.pause()
    } else {
      videoRef.value.play()
      audioRef.value.play()
    }
    isPlaying.value = !isPlaying.value
  }
}

const stopMedia = () => {
  if (videoRef.value && audioRef.value) {
    videoRef.value.pause()
    videoRef.value.currentTime = 0
    audioRef.value.pause()
    audioRef.value.currentTime = 0
    isPlaying.value = false
  }
}

const setVolume = (newVolume: number) => {
  volume.value = newVolume
  if (videoRef.value) videoRef.value.volume = newVolume
  if (audioRef.value) audioRef.value.volume = newVolume
}

const selectVideo = (src: string) => {
  currentVideo.value = src
  if (isPlaying.value && videoRef.value) {
    videoRef.value.play()
  }
}

const selectAudio = (src: string) => {
  currentAudio.value = src
  if (isPlaying.value && audioRef.value) {
    audioRef.value.play()
  }
}
</script>

<template>
  <div class="media-container">
    <div class="video-container">
      <video 
        ref="videoRef" 
        :src="currentVideo" 
        autoplay 
        loop
        @play="isPlaying = true"
        @pause="isPlaying = false"
      ></video>
    </div>

    <div class="audio-container">
      <audio 
        ref="audioRef" 
        :src="currentAudio" 
        autoplay 
        loop
        @play="isPlaying = true"
        @pause="isPlaying = false"
      ></audio>
    </div>

    <div class="controls">
      <button @click="togglePlay" class="control-btn">
        {{ isPlaying ? 'Pause' : 'Play' }}
      </button>
      <button @click="stopMedia" class="control-btn">Stop</button>

      <div class="volume-control">
        <label>Volume:</label>
        <input 
          type="range" 
          min="0" 
          max="1" 
          step="0.1" 
          v-model.number="volume"
          @input="setVolume(volume)"
          class="volume-slider"
        >
      </div>
    </div>

    <div class="media-selection">
      <div class="video-selection">
        <h3>Videos</h3>
        <ul>
          <li 
