<script setup lang="ts">
import { ref, onMounted } from 'vue'

const canvasRef = ref<HTMLCanvasElement | null>(null)
const ctx = ref<CanvasRenderingContext2D | null>(null)
const isDrawing = ref(false)
const fileInputRef = ref<HTMLInputElement | null>(null)

const emit = defineEmits(['submit'])

onMounted(() => {
  if (canvasRef.value) {
    ctx.value = canvasRef.value.getContext('2d')
    if (ctx.value) {
      ctx.value.lineWidth = 2
      ctx.value.lineCap = 'round'
      ctx.value.strokeStyle = '#000000'
    }
  }
})

function startDrawing(e: MouseEvent) {
  if (!ctx.value || !canvasRef.value) return
  isDrawing.value = true
  const rect = canvasRef.value.getBoundingClientRect()
  ctx.value.beginPath()
  ctx.value.moveTo(e.clientX - rect.left, e.clientY - rect.top)
}

function draw(e: MouseEvent) {
  if (!isDrawing.value || !ctx.value || !canvasRef.value) return
  const rect = canvasRef.value.getBoundingClientRect()
  ctx.value.lineTo(e.clientX - rect.left, e.clientY - rect.top)
  ctx.value.stroke()
}

function stopDrawing() {
  isDrawing.value = false
}

function clearCanvas() {
  if (!ctx.value || !canvasRef.value) return
  ctx.value.clearRect(0, 0, canvasRef.value.width, canvasRef.value.height)
}

function handleFileUpload(e: Event) {
  const input = e.target as HTMLInputElement
  if (!input.files?.length || !canvasRef.value || !ctx.value) return

  const file = input.files[0]
  const reader = new FileReader()

  reader.onload = (event) => {
    const img = new Image()
    img.onload = () => {
      canvasRef.value!.width = img.width
      canvasRef.value!.height = img.height
      ctx.value!.drawImage(img, 0, 0)
    }
    img.src = event.target!.result as string
  }

  reader.readAsDataURL(file)
}

function submitSketch() {
  if (!canvasRef.value) return
  const dataUrl = canvasRef.value.toDataURL('image/png')
  emit('submit', dataUrl)
}
</script>

<template>
  <div class="sketch-container">
    <canvas
      ref="canvasRef"
      width="500"
      height="500"
      @mousedown="startDrawing"
      @mousemove="draw"
      @mouseup="stopDrawing"
      @mouseleave="stopDrawing"
    ></canvas>
    <div class="controls">
      <input
        ref="fileInputRef"
        type="file"
        accept="image/*"
        @change="handleFileUpload"
        style="display: none"
      />
      <button @click="fileInputRef?.click()">Upload Sketch</button>
      <button @click="clearCanvas">Clear</button>
      <button @click="submitSketch">Generate Image</button>
    </div>
  </div>
</template>

<style scoped>
