  'sample2.jpg',
  'sample3.jpg'
]

function zoomIn() {
  zoomLevel.value = Math.min(zoomLevel.value + 0.1, 3)
}

function zoomOut() {
  zoomLevel.value = Math.max(zoomLevel.value - 0.1, 0.5)
}

function handleDrag(e: MouseEvent) {
  if (e.buttons === 1) {
    position.value = {
      x: position.value.x + e.movementX,
      y: position.value.y + e.movementY
    }
  }
}
