  0% { transform: rotate(0deg) }
  100% { transform: rotate(360deg) }
}

@keyframes slideIn {
  from { transform: translateX(-100%) }
  to { transform: translateX(0) }
}

@keyframes zoomIn {
  to { transform: scale(1) }
}

@keyframes typing {
  from { width: 0 }
  to { width: 100% }
}
