<script setup lang="ts">
import { ref, onMounted } from 'vue'

const audioFiles = ref<{name: string, url: string, audio?: HTMLAudioElement}[]>([])
const currentFile = ref<number | null>(null)
const isPlaying = ref(false)
const progress = ref(0)
const audioContext = ref<AudioContext | null>(null)

const handleFileUpload = (e: Event) => {
  const files = (e.target as HTMLInputElement).files
  if (!files) return

  Array.from(files).forEach(file => {
    if (!file.type.startsWith('audio/')) return

    const url = URL.createObjectURL(file)
    const audio = new Audio(url)
    audio.preload = 'auto'

    audioFiles.value.push({
      name: file.name,
      url,
      audio
    })
  })
}

const playAudio = (index: number) => {
  if (currentFile.value !== null) {
    const prevAudio = audioFiles.value[currentFile.value].audio
    if (prevAudio) {
      prevAudio.pause()
      prevAudio.currentTime = 0
    }
  }

  currentFile.value = index
  const audio = audioFiles.value[index].audio
  if (!audio) return

  if (!audioContext.value) {
    audioContext.value = new (window.AudioContext || (window as any).webkitAudioContext)()
  }

  audio.play()
    .then(() => {
      isPlaying.value = true
      updateProgress()
    })
    .catch(err => console.error('Playback failed:', err))
}

const togglePlayPause = () => {
  if (currentFile.value === null) return

  const audio = audioFiles.value[currentFile.value].audio
  if (!audio) return

  if (isPlaying.value) {
    audio.pause()
  } else {
    audio.play()
      .then(() => {
        isPlaying.value = true
        updateProgress()
      })
  }
  isPlaying.value = !isPlaying.value
}

const stopAudio = () => {
  if (currentFile.value === null) return

  const audio = audioFiles.value[currentFile.value].audio
  if (!audio) return

  audio.pause()
  audio.currentTime = 0
  isPlaying.value = false
  progress.value = 0
}

const updateProgress = () => {
  if (currentFile.value === null) return

  const audio = audioFiles.value[currentFile.value].audio
  if (!audio) return

  progress.value = (audio.currentTime / audio.duration) * 100

  if (isPlaying.value) {
    requestAnimationFrame(updateProgress)
  }
}

const seek = (e: MouseEvent) => {
  if (currentFile.value === null) return

  const audio = audioFiles.value[currentFile.value].audio
  if (!audio) return

  const rect = (e.target as HTMLElement).getBoundingClientRect()
  const seekPercent = (e.clientX - rect.left) / rect.width
  audio.currentTime = seekPercent * audio.duration
  progress.value = seekPercent * 100
}

onMounted(() => {
  // Preload any existing audio files when component mounts
  audioFiles.value.forEach(file => {
    if (file.audio) {
      file.audio.load()
    }
  })
})
</script>

<template>
  <div class="audio-player">
    <h1>Audio Preloader</h1>

    <div class="upload-section">
      <input 
        type="file" 
        accept="audio/*" 
        multiple 
        @change="handleFileUpload"
        class="upload-input"
      >
    </div>

    <div class="audio-list">
      <div 
        v-for="(file, index) in audioFiles" 
        :key="index" 
        @click="playAudio(index)"
        :class="{active: currentFile === index}"
        class="audio-item"
      >
        {{ file.name }}
      </div>
    </div>

    <div class="player-controls" v-if="currentFile !== null">
      <button @click="togglePlayPause" class="control-btn">
        {{ isPlaying ? 'Pause' : 'Play' }}
      </button>
      <button @click="stopAudio" class="control-btn">Stop</button>

      <div class="progress-bar" @click="seek">
        <div class="progress" :style="{width: progress + '%'}"></div>
      </div>
    </div>
  </div>
</template>

