<script setup lang="ts">
import { ref, computed } from 'vue'
import VideoLibrary from './VideoLibrary.vue'
import MusicLibrary from './MusicLibrary.vue'
import ImageLibrary from './ImageLibrary.vue'

const props = defineProps(['activeTab'])
const emit = defineEmits(['play', 'add-to-playlist'])

const searchQuery = ref('')
const filterOptions = ref({
  date: '',
  type: '',
  duration: ''
})

// Sample media data
const videos = ref([
  { id: 1, title: 'Nature Documentary', duration: '1:23:45', thumbnail: 'nature.jpg' },
  { id: 2, title: 'Travel Vlog', duration: '15:30', thumbnail: 'travel.jpg' }
])

const music = ref([
  { id: 1, title: 'Relaxing Piano', artist: 'John Smith', duration: '3:45' },
  { id: 2, title: 'Upbeat Rock', artist: 'The Band', duration: '4:20' }
])

const images = ref([
  { id: 1, title: 'Mountain View', date: '2023-05-15' },
  { id: 2, title: 'Beach Sunset', date: '2023-06-20' }
])

const filteredMedia = computed(() => {
  let media = []
  switch(props.activeTab) {
    case 'videos': media = videos.value; break
    case 'music': media = music.value; break
    case 'images': media = images.value; break
  }

  if (searchQuery.value) {
    media = media.filter(item => 
      item.title.toLowerCase().includes(searchQuery.value.toLowerCase())
    )
  }

  return media
})

function handlePlay(media) {
  emit('play', { ...media, type: props.activeTab })
}

function handleAddToPlaylist(media) {
  const playlistName = prompt('Enter playlist name:')
  if (playlistName) {
    emit('add-to-playlist', playlistName, { ...media, type: props.activeTab })
  }
}
</script>

<template>
  <div class="media-library">
    <div class="search-filter">
      <input 
        v-model="searchQuery" 
        placeholder="Search media..." 
        class="search-input"
      />
      <select v-model="filterOptions.type" class="filter-select">
        <option value="">All Types</option>
        <option value="video">Video</option>
        <option value="music">Music</option>
        <option value="image">Image</option>
      </select>
    </div>

    <VideoLibrary 
      v-if="activeTab === 'videos'" 
      :videos="filteredMedia"
      @play="handlePlay"
      @add-to-playlist="handleAddToPlaylist"
    />
    <MusicLibrary 
      v-else-if="activeTab === 'music'" 
      :tracks="filteredMedia"
      @play="handlePlay"
      @add-to-playlist="handleAddToPlaylist"
    />
    <ImageLibrary 
