<script setup lang="ts">
import { ref, computed } from 'vue'
import OverlayPreview from './OverlayPreview.vue'
import ControlsPanel from './ControlsPanel.vue'

type MediaItem = {
  type: 'video' | 'image' | 'text'
  src: string
  text?: string
  position: { x: number; y: number }
  size: { width: number; height: number }
  style: {
    color: string
    fontSize: string
    fontFamily: string
    backgroundColor: string
  }
}

const mediaItems = ref<MediaItem[]>([])
const selectedItem = ref<MediaItem | null>(null)
const previewMode = ref(false)

const addMedia = (type: 'video' | 'image' | 'text') => {
  const newItem: MediaItem = {
    type,
    src: '',
    text: type === 'text' ? 'New Text' : '',
    position: { x: 50, y: 50 },
    size: { width: 200, height: type === 'text' ? 50 : 200 },
    style: {
      color: '#000000',
      fontSize: '16px',
      fontFamily: 'Arial',
      backgroundColor: 'transparent'
    }
  }
  mediaItems.value.push(newItem)
  selectedItem.value = newItem
}

const handleFileUpload = (event: Event, item: MediaItem) => {
  const input = event.target as HTMLInputElement
  if (input.files && input.files[0]) {
    const file = input.files[0]
    const reader = new FileReader()
    reader.onload = (e) => {
      item.src = e.target?.result as string
    }
    reader.readAsDataURL(file)
  }
}
</script>

<template>
  <div class="editor-container">
    <div class="toolbar">
      <button @click="addMedia('image')" class="sea-green">Add Image</button>
      <button @click="addMedia('video')" class="sea-green">Add Video</button>
      <button @click="addMedia('text')" class="sea-green">Add Text</button>
      <button @click="previewMode = !previewMode" class="sea-green">
        {{ previewMode ? 'Exit Preview' : 'Preview' }}
      </button>
    </div>

    <div class="editor-content">
      <OverlayPreview 
        :mediaItems="mediaItems" 
        :selectedItem="selectedItem"
        :previewMode="previewMode"
        @select="selectedItem = $event"
      />

      <ControlsPanel 
        v-if="selectedItem && !previewMode"
        :item="selectedItem"
        @update:item="selectedItem = $event"
        @file-upload="handleFileUpload"
      />
