<script setup lang="ts">
import { ref } from 'vue'

const fileInput = ref<HTMLInputElement | null>(null)
const uploadedFile = ref<File | null>(null)
const processedFile = ref<string | null>(null)
const scaleFactor = ref(2)
const processing = ref(false)

const handleFileUpload = (e: Event) => {
  const files = (e.target as HTMLInputElement).files
  if (files && files.length > 0) {
    uploadedFile.value = files[0]
    processedFile.value = null
  }
}

const processMedia = async () => {
  if (!uploadedFile.value) return

  processing.value = true

  // In a real app, this would use a proper ML model
  // Here we simulate processing with a timeout
  await new Promise(resolve => setTimeout(resolve, 1500))

  processedFile.value = URL.createObjectURL(uploadedFile.value)
  processing.value = false
}

const downloadProcessed = () => {
  if (!processedFile.value) return
  const a = document.createElement('a')
  a.href = processedFile.value
  a.download = `processed_${uploadedFile.value?.name || 'file'}`
  a.click()
}
</script>

<template>
  <div class="processor-container">
    <h1>Media Super-Resolution Processor</h1>

    <div class="upload-section">
      <input 
        ref="fileInput"
        type="file" 
        accept="image/*,video/*,.gif"
        @change="handleFileUpload"
      />
      <div v-if="uploadedFile" class="file-info">
        Selected: {{ uploadedFile.name }}
      </div>
    </div>

    <div class="controls">
      <label>
        Scale Factor:
        <select v-model="scaleFactor">
          <option value="2">2x</option>
          <option value="4">4x</option>
        </select>
      </label>

      <button 
        :disabled="!uploadedFile || processing"
        @click="processMedia"
      >
        {{ processing ? 'Processing...' : 'Enhance Media' }}
      </button>
    </div>

    <div v-if="processedFile" class="results">
      <h3>Processed Result:</h3>
      <div class="preview">
        <img v-if="uploadedFile?.type.includes('image')" :src="processedFile" />
        <video v-else-if="uploadedFile?.type.includes('video')" controls>
          <source :src="processedFile" :type="uploadedFile.type">
        </video>
      </div>
      <button @click="downloadProcessed">Download</button>
    </div>
  </div>
</template>

