<script setup lang="ts">
import { ref } from 'vue'

const activeTab = ref('video')
const uploadedFile = ref<File | null>(null)
const processedFile = ref<string | null>(null)
const effects = ref<string[]>([])
const format = ref('mp4')
const showProgress = ref(false)
const progress = ref(0)

const handleFileUpload = (event: Event) => {
  const input = event.target as HTMLInputElement
  if (input.files?.length) {
    uploadedFile.value = input.files[0]
    processedFile.value = URL.createObjectURL(input.files[0])
  }
}

const processFile = () => {
  showProgress.value = true
  progress.value = 0

  const interval = setInterval(() => {
    progress.value += 10
    if (progress.value >= 100) {
      clearInterval(interval)
      showProgress.value = false
      // Simulate processing completion
      processedFile.value = URL.createObjectURL(uploadedFile.value!)
    }
  }, 300)
}

const downloadFile = () => {
  if (!processedFile.value) return

  const a = document.createElement('a')
  a.href = processedFile.value
  a.download = `processed.${format.value}`
  a.click()
}
</script>

