<script setup lang="ts">
import { defineProps, ref } from 'vue'

const props = defineProps({
  stream: {
    type: Object as () => MediaStream | null,
    required: true
  }
})

const audioEnabled = ref(true)
const videoEnabled = ref(true)

const toggleAudio = () => {
  if (props.stream) {
    audioEnabled.value = !audioEnabled.value
    props.stream.getAudioTracks().forEach(track => {
      track.enabled = audioEnabled.value
    })
  }
}

const toggleVideo = () => {
  if (props.stream) {
    videoEnabled.value = !videoEnabled.value
    props.stream.getVideoTracks().forEach(track => {
      track.enabled = videoEnabled.value
    })
  }
}

const shareScreen = async () => {
  try {
    const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true })
    if (props.stream) {
      props.stream.getVideoTracks().forEach(track => track.stop())
      screenStream.getVideoTracks().forEach(track => {
        props.stream?.addTrack(track)
      })
    }
  } catch (err) {
    console.error('Error sharing screen:', err)
  }
}
</script>

<template>
  <div class="controls">
    <button @click="toggleAudio" :class="{ active: audioEnabled }">
      {{ audioEnabled ? 'Mute' : 'Unmute' }}
    </button>
    <button @click="toggleVideo" :class="{ active: videoEnabled }">
      {{ videoEnabled ? 'Stop Video' : 'Start Video' }}
