<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'

interface Song {
  id: number
  title: string
  artist: string
  src: string
  lyrics: string
}

const songs: Song[] = [
  {
    id: 1,
    title: 'Sample Song 1',
    artist: 'Artist A',
    src: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
    lyrics: 'These are sample lyrics for song 1\nLine two of lyrics\nLine three of lyrics'
  },
  {
    id: 2,
    title: 'Sample Song 2',
    artist: 'Artist B',
    src: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
    lyrics: 'Different lyrics for song 2\nSecond line here\nThird line here'
  }
]

const audioRef = ref<HTMLAudioElement | null>(null)
const currentSongIndex = ref(0)
const isPlaying = ref(false)
const currentTime = ref(0)
const duration = ref(0)
const volume = ref(0.7)
const searchQuery = ref('')
const showLyrics = ref(false)

const currentSong = computed(() => songs[currentSongIndex.value])

const filteredSongs = computed(() => {
  return songs.filter(song => 
    song.title.toLowerCase().includes(searchQuery.value.toLowerCase()) ||
    song.artist.toLowerCase().includes(searchQuery.value.toLowerCase())
  )
})

const progress = computed(() => {
  return duration.value ? (currentTime.value / duration.value) * 100 : 0
})

function togglePlay() {
  if (isPlaying.value) {
    audioRef.value?.pause()
  } else {
    audioRef.value?.play()
  }
  isPlaying.value = !isPlaying.value
}

function playSong(index: number) {
  currentSongIndex.value = index
  isPlaying.value = true
  nextTick(() => {
    audioRef.value?.play()
  })
}

function nextSong() {
  currentSongIndex.value = (currentSongIndex.value + 1) % songs.length
  if (isPlaying.value) {
    nextTick(() => {
      audioRef.value?.play()
    })
  }
}

function prevSong() {
  currentSongIndex.value = (currentSongIndex.value - 1 + songs.length) % songs.length
  if (isPlaying.value) {
    nextTick(() => {
      audioRef.value?.play()
    })
  }
}

function handleTimeUpdate() {
  if (audioRef.value) {
    currentTime.value = audioRef.value.currentTime
    duration.value = audioRef.value.duration
  }
}

function handleProgressClick(e: MouseEvent) {
  if (!audioRef.value) return
  const progressBar = e.currentTarget as HTMLElement
  const clickPosition = e.offsetX / progressBar.clientWidth
  audioRef.value.currentTime = clickPosition * audioRef.value.duration
}

function handleVolumeChange() {
  if (audioRef.value) {
    audioRef.value.volume = volume.value
  }
}

function toggleLyrics() {
  showLyrics.value = !showLyrics.value
}

onMounted(() => {
  if (audioRef.value) {
    audioRef.value.volume = volume.value
  }
})
</script>

<template>
  <div class="music-player">
    <div class="player-header">
      <h1>Music Player</h1>
      <div class="search-box">
        <input 
          v-model="searchQuery" 
          type="text" 
          placeholder="Search songs..."
        />
      </div>
    </div>

    <div class="player-main">
      <div class="song-list">
        <div 
          v-for="(song, index) in filteredSongs" 
          :key="song.id" 
          class="song-item" 
          :class="{ active: currentSongIndex === index }"
          @click="playSong(index)"
        >
          <div class="song-info">
            <span class="song-title">{{ song.title }}</span>
            <span class="song-artist">{{ song.artist }}</span>
          </div>
        </div>
      </div>

      <div class="player-controls">
        <div class="now-playing">
          <h2>{{ currentSong.title }}</h2>
          <p>{{ currentSong.artist }}</p>
        </div>

        <div class="progress-bar" @click="handleProgressClick">
          <div class="progress" :style="{ width: `${progress}%` }"></div>
        </div>

        <div class="time-display">
          <span>{{ new Date(currentTime * 1000).toISOString().substr(14, 5) }}</span>
          <span>{{ new Date(duration * 1000).toISOString().substr(14, 5) }}</span>
        </div>

        <div class="controls">
          <button @click="prevSong">⏮</button>
          <button @click="togglePlay">{{ isPlaying ? '⏸' : '▶' }}</button>
          <button @click="nextSong">⏭</button>
          <button @click="toggleLyrics">📜</button>
        </div>

        <div class="volume-control">
          <span>🔈</span>
          <input 
            type="range" 
            min="0" 
            max="1" 
            step="0.01" 
            v-model="volume" 
            @input="handleVolumeChange"
          />
        </div>
      </div>

      <div class="lyrics-container" v-if="showLyrics">
        <h3>Lyrics</h3>
        <pre>{{ currentSong.lyrics }}</pre>
      </div>
    </div>

    <audio 
      ref="audioRef" 
      :src="currentSong.src" 
      @timeupdate="handleTimeUpdate"
      @ended="nextSong"
    />
  </div>
