<script setup lang="ts">
import { ref } from 'vue'

const menuOptions = ref([
  { id: 1, text: 'Press 1 for account balance', action: () => speak('Your balance is $1,234.56') },
  { id: 2, text: 'Press 2 for recent transactions', action: () => speak('Your last 3 transactions were...') },
  { id: 3, text: 'Press 3 to speak with an agent', action: () => speak('Connecting you to an agent...') }
])

const currentMessage = ref('Welcome to our service. Please say or select an option.')
const isListening = ref(false)

function speak(text: string) {
  if ('speechSynthesis' in window) {
    const utterance = new SpeechSynthesisUtterance(text)
    window.speechSynthesis.speak(utterance)
    currentMessage.value = text
  }
}

function startListening() {
  isListening.value = true
  if ('webkitSpeechRecognition' in window) {
    const recognition = new webkitSpeechRecognition()
    recognition.continuous = false
    recognition.interimResults = false

    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript.toLowerCase()
      handleVoiceCommand(transcript)
    }

    recognition.onerror = () => {
      isListening.value = false
    }

    recognition.start()
  }
}

function handleVoiceCommand(command: string) {
  isListening.value = false
  const option = menuOptions.value.find(opt => 
    command.includes(opt.id.toString()) || 
    command.includes(opt.text.toLowerCase())
  )

  if (option) {
    option.action()
  } else {
    speak("Sorry, I didn't understand. Please try again.")
  }
}
</script>

<template>
  <div class="ivr-container">
    <h1>Interactive Voice Response</h1>
    <div class="ivr-message">{{ currentMessage }}</div>

    <div class="ivr-menu">
      <div 
        v-for="option in menuOptions" 
        :key="option.id" 
        class="ivr-option"
        @click="option.action()"
      >
        {{ option.text }}
      </div>
    </div>

    <button 
      class="ivr-button" 
      @click="startListening"
      :disabled="isListening"
    >
      {{ isListening ? 'Listening...' : 'Speak Command' }}
    </button>
