<script setup lang="ts">
import { ref, computed } from 'vue'
import VideoCard from './VideoCard.vue'

const props = defineProps(['searchQuery'])

const videos = ref([
  { id: 1, title: 'Nature Documentary', views: 1200, author: 'naturelover', tags: ['nature', 'documentary'] },
  { id: 2, title: 'Coding Tutorial', views: 450, author: 'devguru', tags: ['coding', 'tutorial'] }
])

const filteredVideos = computed(() => {
  if (!props.searchQuery) return videos.value
  return videos.value.filter(video => 
    video.title.toLowerCase().includes(props.searchQuery.toLowerCase()) ||
    video.tags.some(tag => tag.toLowerCase().includes(props.searchQuery.toLowerCase()))
  )
})
</script>

<template>
  <div class="video-list">
    <VideoCard 
      v-for="video in filteredVideos"
      :key="video.id"
      :video="video"
    />
  </div>
</template>

