// WebRTC configuration and utilities
export const rtcConfig = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' }
  ]
}

export class VoIPManager {
  constructor() {
    this.peerConnection = null
    this.localStream = null
    this.remoteStream = null
  }

  async startCall() {
    try {
      this.peerConnection = new RTCPeerConnection(rtcConfig)

      // Get local media stream
      this.localStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: false
      })

      // Add local stream to connection
      this.localStream.getTracks().forEach(track => {
        this.peerConnection.addTrack(track, this.localStream)
      })

      // Set up remote stream
      this.remoteStream = new MediaStream()
      this.peerConnection.ontrack = event => {
        event.streams[0].getTracks().forEach(track => {
          this.remoteStream.addTrack(track)
        })
      }

      // ICE candidate handling
      this.peerConnection.onicecandidate = event => {
        if (event.candidate) {
          // Send candidate to remote peer
          console.log('New ICE candidate:', event.candidate)
        }
      }

      // Create offer
      const offer = await this.peerConnection.createOffer()
      await this.peerConnection.setLocalDescription(offer)

      // Send offer to remote peer
      return offer

    } catch (error) {
      console.error('Error starting call:', error)
      throw error
    }
  }

  async answerCall(offer) {
    try {
      this.peerConnection = new RTCPeerConnection(rtcConfig)

      // Get local media stream
      this.localStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: false
      })

      // Add local stream to connection
      this.localStream.getTracks().forEach(track => {
        this.peerConnection.addTrack(track, this.localStream)
      })

      // Set up remote stream
      this.remoteStream = new MediaStream()
      this.peerConnection.ontrack = event => {
        event.streams[0].getTracks().forEach(track => {
          this.remoteStream.addTrack(track)
        })
      }

      // ICE candidate handling
      this.peerConnection.onicecandidate = event => {
        if (event.candidate) {
          // Send candidate to remote peer
          console.log('New ICE candidate:', event.candidate)
        }
      }

      // Set remote description
      await this.peerConnection.setRemoteDescription(offer)

      // Create answer
      const answer = await this.peerConnection.createAnswer()
      await this.peerConnection.setLocalDescription(answer)

      return answer

    } catch (error) {
      console.error('Error answering call:', error)
      throw error
    }
  }

  endCall() {
    if (this.peerConnection) {
      this.peerConnection.close()
      this.peerConnection = null
    }

    if (this.localStream) {
      this.localStream.getTracks().forEach(track => track.stop())
      this.localStream = null
    }

    this.remoteStream = null
  }

  async forwardCall(targetPeerId) {
    // Implementation for call forwarding
    console.log(`Call forwarded to ${targetPeerId}`)
  }

  async startConference(peerIds) {
    // Implementation for conference calling
    console.log(`Starting conference with ${peerIds.join(', ')}`)
  }
}
