<script setup lang="ts">
import { ref, computed } from 'vue'
import DownloadItem from './DownloadItem.vue'

interface Download {
  id: string
  url: string
  type: 'video' | 'audio' | 'image'
  format: string
  quality: string
  status: 'queued' | 'downloading' | 'paused' | 'completed' | 'failed'
  progress: number
  filePath?: string
}

const inputUrl = ref('')
const selectedType = ref<'video' | 'audio' | 'image'>('video')
const selectedFormat = ref('mp4')
const selectedQuality = ref('720p')
const downloads = ref<Download[]>([])
const activeTab = ref('download')

const formatOptions = computed(() => {
  return {
    video: ['mp4', 'webm', 'mkv'],
    audio: ['mp3', 'wav', 'ogg'],
    image: ['jpg', 'png', 'webp']
  }[selectedType.value]
})

const qualityOptions = computed(() => {
  return {
    video: ['144p', '240p', '360p', '480p', '720p', '1080p', '4K'],
    audio: ['64kbps', '128kbps', '192kbps', '256kbps', '320kbps'],
    image: ['original', 'small', 'medium', 'large']
  }[selectedType.value]
})

const addDownload = () => {
  if (!inputUrl.value) return

  const newDownload: Download = {
    id: Date.now().toString(),
    url: inputUrl.value,
    type: selectedType.value,
    format: selectedFormat.value,
    quality: selectedQuality.value,
    status: 'queued',
    progress: 0
  }

  downloads.value.unshift(newDownload)
  inputUrl.value = ''

  // Simulate download progress
  simulateDownload(newDownload.id)
}

const simulateDownload = (id: string) => {
  const download = downloads.value.find(d => d.id === id)
  if (!download) return

  download.status = 'downloading'

  const interval = setInterval(() => {
    download.progress += Math.random() * 10
    if (download.progress >= 100) {
      download.progress = 100
      download.status = 'completed'
      download.filePath = `/downloads/${download.id}.${download.format}`
      clearInterval(interval)
    }
  }, 500)
}

const pauseDownload = (id: string) => {
  const download = downloads.value.find(d => d.id === id)
  if (download) {
    download.status = download.status === 'paused' ? 'downloading' : 'paused'
  }
}

const removeDownload = (id: string) => {
  downloads.value = downloads.value.filter(d => d.id !== id)
}

const completedDownloads = computed(() => 
  downloads.value.filter(d => d.status === 'completed')
)
</script>

<template>
  <div class="app-container">
    <header class="header">
      <h1>Multimedia Download Manager</h1>
    </header>

    <div class="tabs">
      <button 
        :class="{ active: activeTab === 'download' }"
        @click="activeTab = 'download'"
      >
        Download
      </button>
      <button 
        :class="{ active: activeTab === 'library' }"
        @click="activeTab = 'library'"
      >
        Library
      </button>
    </div>

    <div v-if="activeTab === 'download'" class="download-section">
      <div class="input-group">
        <input 
          v-model="inputUrl" 
          type="text" 
          placeholder="Enter or paste URL here..."
          class="url-input"
        >
        <button @click="addDownload" class="add-button">Add</button>
      </div>

      <div class="options">
        <div class="option">
          <label>Type:</label>
          <select v-model="selectedType">
            <option value="video">Video</option>
            <option value="audio">Audio</option>
            <option value="image">Image</option>
          </select>
        </div>

        <div class="option">
          <label>Format:</label>
          <select v-model="selectedFormat">
            <option v-for="format in formatOptions" :value="format" :key="format">
              {{ format.toUpperCase() }}
            </option>
          </select>
        </div>

        <div class="option">
          <label>Quality:</label>
          <select v-model="selectedQuality">
            <option v-for="quality in qualityOptions" :value="quality" :key="quality">
              {{ quality }}
            </option>
          </select>
        </div>
      </div>

      <div class="download-list">
        <h2>Active Downloads</h2>
        <DownloadItem
          v-for="download in downloads.filter(d => d.status !== 'completed')"
          :key="download.id"
          :download="download"
          @pause="pauseDownload(download.id)"
          @remove="removeDownload(download.id)"
        />
      </div>
    </div>

    <div v-else class="library-section">
      <h2>Downloaded Files</h2>
      <div v-if="completedDownloads.length === 0" class="empty-library">
        No downloaded files yet
      </div>
      <div v-else class="file-grid">
        <div v-for="download in completedDownloads" :key="download.id" class="file-card">
          <div class="file-preview">
