  { id: 2, name: 'Sarah Johnson', role: 'manager', email: 'sarah@example.com', permissions: ['view_sales', 'generate_codes', 'manage_team'] },
  { id: 3, name: 'Mike Brown', role: 'agent', email: 'mike@example.com', permissions: ['view_sales'] }
])

const newMember = ref({
  name: '',
  email: '',
  role: 'agent',
  permissions: ['view_sales']
})

const availablePermissions = [
  { id: 'view_sales', name: 'View Sales Data' },
  { id: 'generate_codes', name: 'Generate Sales Codes' },
  { id: 'manage_team', name: 'Manage Team Members' }
]

const addMember = () => {
  if (!newMember.value.name || !newMember.value.email) return

  teamMembers.value.push({
    id: teamMembers.value.length + 1,
    ...newMember.value
  })

  newMember.value = {
    name: '',
    email: '',
    role: 'agent',
    permissions: ['view_sales']
  }
}

const togglePermission = (memberId: number, permission: string) => {
  const member = teamMembers.value.find(m => m.id === memberId)
  if (!member) return

  if (member.permissions.includes(permission)) {
    member.permissions = member.permissions.filter(p => p !== permission)
  } else {
    member.permissions.push(permission)
  }
}
</script>

<template>
  <div class="team-management">
