            <th>Email</th>
            <th>Role</th>
            <th>Permissions</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="member in teamMembers" :key="member.id">
            <td>{{ member.name }}</td>
            <td>{{ member.email }}</td>
            <td>{{ member.role }}</td>
            <td>
              <div class="permissions">
                <div 
                  v-for="perm in availablePermissions" 
                  :key="perm.id"
                  class="permission"
                  :class="{ active: member.permissions.includes(perm.id) }"
                  @click="togglePermission(member.id, perm.id)"
                >
                  {{ perm.name }}
                </div>
              </div>
            </td>
