<script setup lang="ts">
defineProps<{
  modelValue: {
    name: string
    industry: string
    size: string
    contact: string
    address: string
  }
}>()

const emit = defineEmits(['update:modelValue'])

const updateValue = (field: string, value: string) => {
  emit('update:modelValue', {
    ...props.modelValue,
    [field]: value
  })
}
</script>

