I'll create a beautiful API data viewer with thistle background and medium purple UI components. Here's the implementation:

<boltArtifact id="api-data-viewer" title="API Data Viewer with Thistle Background">
  <boltAction type="file" filePath="src/App.tsx">import React, { useState, useEffect } from 'react';
import { RefreshCw, Loader2 } from 'lucide-react';

interface DataItem {
  id: number;
  title: string;
  body: string;
  userId: number;
}

const App: React.FC = () => {
  const [data, setData] = useState<DataItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('https://jsonplaceholder.typicode.com/posts');
      if (!response.ok) throw new Error('Failed to fetch data');
      const jsonData = await response.json();
      setData(jsonData.slice(0, 10)); // Limit to 10 items for demo
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  return (
    <div className="min-h-screen bg-thistle p-6">
      <div className="max-w-4xl mx-auto">
        <header className="mb-8">
          <h1 className="text-3xl font-bold text-medium-purple mb-2">API Data Viewer</h1>
          <p className="text-medium-purple/80">View and refresh data from JSONPlaceholder API</p>
        </header>

        <div className="bg-white bg-opacity-80 rounded-xl shadow-lg p-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-medium-purple">Posts Data</h2>
            <button
              onClick={fetchData}
              disabled={loading}
              className="flex items-center gap-2 bg-medium-purple hover:bg-medium-purple/90 text-white px-4 py-2 rounded-lg transition-colors disabled:opacity-50"
            >
              {loading ? (
                <Loader2 className="animate-spin" size={18} />
              ) : (
                <RefreshCw size={18} />
              )}
              Refresh Data
            </button>
          </div>

          {error ? (
            <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded">
              <p>Error: {error}</p>
            </div>
          ) : loading && data.length === 0 ? (
            <div className="flex justify-center items-center h-40">
              <Loader2 className="animate-spin text-medium-purple" size={32} />
            </div>
          ) : (
            <div className="space-y-4">
              {data.map((item) => (
                <div key={item.id} className="p-4 border border-medium-purple/20 rounded-lg hover:bg-medium-purple/5 transition-colors">
                  <h3 className="font-medium text-medium-purple">{item.title}</h3>
                  <p className="text-gray-700 mt-1">{item.body}</p>
                  <div className="mt-2 text-sm text-medium-purple/70">User ID: {item.userId}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default App;
</boltAction>

