<script setup lang="ts">
import { ref, computed } from 'vue'

const location = ref('')
const radius = ref(10) // Default 10km radius
const competitions = ref([])
const isLoading = ref(false)
const error = ref(null)

const filteredCompetitions = computed(() => {
  if (!location.value) return competitions.value
  // In a real app, this would use actual geocoding and distance calculation
  return competitions.value.filter(comp => {
    return Math.random() > 0.5 // Simulate filtering for demo
  })
})

const searchCompetitions = async () => {
  if (!location.value) return

  isLoading.value = true
  error.value = null

  try {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000))
    competitions.value = Array(20).fill().map((_, i) => ({
      id: i,
      name: `Running Competition ${i+1}`,
      location: `City ${i+1}`,
      date: new Date(Date.now() + i * 86400000).toLocaleDateString()
    }))
  } catch (err) {
    error.value = 'Failed to load competitions'
  } finally {
    isLoading.value = false
  }
}
</script>

