        <option value="20">20 km</option>
        <option value="50">50 km</option>
        <option value="100">100 km</option>
      </select>
      <button @click="searchCompetitions" :disabled="isLoading">
        {{ isLoading ? 'Searching...' : 'Search' }}
      </button>
    </div>

    <div v-if="error" class="error">{{ error }}</div>

